-- Original Tests02-20; approved Test01, saved work and all accounting remain intact.
begin;
drop index academy_tcf_reading.reading_one_active;
create unique index reading_one_active_paper on academy_tcf_reading.attempts(user_id,test_id,version) where status='active';
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-02','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-02","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 02","topic":"Habiter et vivre dans son quartier","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible.","question":"Que faut-il faire mardi soir ?","options":["Nettoyer les escaliers","Retirer les vélos de la cour","Fermer le local à vélos","Rapporter les clés"],"correct":"B","explanation":"Le passage indique : « Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible. » Cela justifie la réponse : Retirer les vélos de la cour."},{"number":2,"points":3,"passage":"Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi.","question":"Quand faut-il appeler le numéro affiché ?","options":["En cas de fuite urgente","Pour changer de boîte aux lettres","Pour réserver une visite","Pour payer le loyer"],"correct":"A","explanation":"Le passage indique : « Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi. » Cela justifie la réponse : En cas de fuite urgente."},{"number":3,"points":3,"passage":"La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques.","question":"Qu'est-ce qui change ?","options":["Le lieu des rendez-vous","Le prix du service","Les pièces à fournir","Les jours d'ouverture"],"correct":"A","explanation":"Le passage indique : « La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques. » Cela justifie la réponse : Le lieu des rendez-vous."},{"number":4,"points":3,"passage":"Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits.","question":"Quelle activité est autorisée ?","options":["Entrer après vingt heures","Allumer un barbecue","Organiser un feu de bois","Prendre son déjeuner au jardin"],"correct":"D","explanation":"Le passage indique : « Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits. » Cela justifie la réponse : Prendre son déjeuner au jardin."},{"number":5,"points":9,"passage":"Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus.","question":"Quel critère Nora doit-elle comprendre comme prioritaire ?","options":["La taille de la chambre","La présence d'un balcon","Le prix le plus bas possible","La facilité des trajets"],"correct":"D","explanation":"Le passage indique : « Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus. » Cela justifie la réponse : La facilité des trajets."},{"number":6,"points":9,"passage":"Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience.","question":"Pourquoi ce message est-il envoyé ?","options":["Annoncer une panne durable","Demander un changement d'étage","Prévenir d'une gêne temporaire","Interdire l'usage de l'ascenseur"],"correct":"C","explanation":"Le passage indique : « Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience. » Cela justifie la réponse : Prévenir d'une gêne temporaire."},{"number":7,"points":9,"passage":"Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement.","question":"Comment le propriétaire participera-t-il ?","options":["À distance","Par courrier uniquement","En venant dimanche soir","En passant chez un voisin"],"correct":"A","explanation":"Le passage indique : « Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement. » Cela justifie la réponse : À distance."},{"number":8,"points":9,"passage":"L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place.","question":"Quel service est proposé ?","options":["Collecter les coordonnées des participants","Aider à comprendre un contrat","Signer un bail pour le locataire","Trouver un appartement garanti"],"correct":"B","explanation":"Le passage indique : « L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place. » Cela justifie la réponse : Aider à comprendre un contrat."},{"number":9,"points":9,"passage":"Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues.","question":"Quelle obligation accompagne l'hébergement ?","options":["Verser un salaire à l'hôte","Assurer des soins quotidiens","Être présent certains soirs","Travailler toutes les nuits"],"correct":"C","explanation":"Le passage indique : « Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues. » Cela justifie la réponse : Être présent certains soirs."},{"number":10,"points":9,"passage":"Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé.","question":"Pourquoi l'horaire a-t-il été modifié ?","options":["Faciliter la participation des parents","Terminer des travaux urgents","Réduire le nombre de participants","Ajouter un vote supplémentaire"],"correct":"A","explanation":"Le passage indique : « Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé. » Cela justifie la réponse : Faciliter la participation des parents."},{"number":11,"points":15,"passage":"Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins.","question":"Quelle difficulté est signalée ?","options":["L'interdiction de laver chez soi","L'absence totale de réservation","La consommation excessive de papier","Le non-respect des créneaux"],"correct":"D","explanation":"Le passage indique : « Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins. » Cela justifie la réponse : Le non-respect des créneaux."},{"number":12,"points":15,"passage":"La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres.","question":"Quel est le rôle des bénévoles ?","options":["Vérifier les déclarations fiscales","Vendre les outils aux habitants","Expliquer l'utilisation du matériel","Rénover gratuitement les logements"],"correct":"C","explanation":"Le passage indique : « La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres. » Cela justifie la réponse : Expliquer l'utilisation du matériel."},{"number":13,"points":15,"passage":"Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir.","question":"Quel choix guide le projet ?","options":["Réserver l'hôtel aux touristes","Construire des maisons séparées","Réutiliser un bâtiment existant","Supprimer les espaces communs"],"correct":"C","explanation":"Le passage indique : « Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir. » Cela justifie la réponse : Réutiliser un bâtiment existant."},{"number":14,"points":15,"passage":"Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien.","question":"Quel avantage Sarah découvre-t-elle ?","options":["Une pièce supplémentaire","Des meubles plus volumineux","Un garage gratuit","Un entretien moins important"],"correct":"D","explanation":"Le passage indique : « Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien. » Cela justifie la réponse : Un entretien moins important."},{"number":15,"points":15,"passage":"Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu.","question":"À quoi sert cette marche ?","options":["Collecter une taxe locale","Visiter seulement des monuments","Découvrir les services du quotidien","Vendre des abonnements touristiques"],"correct":"C","explanation":"Le passage indique : « Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu. » Cela justifie la réponse : Découvrir les services du quotidien."},{"number":16,"points":15,"passage":"Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire.","question":"Comment faut-il interpréter ces chiffres ?","options":["Comme une indication dépendant de l'usage","Comme un prix fixe garanti","Comme le montant du dépôt","Comme une consommation toujours nulle"],"correct":"A","explanation":"Le passage indique : « Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire. » Cela justifie la réponse : Comme une indication dépendant de l'usage."},{"number":17,"points":15,"passage":"Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation.","question":"À qui cette mesure peut-elle particulièrement servir ?","options":["Aux propriétaires vendant leur logement","Aux résidents isolés pendant la chaleur","Aux touristes réservant une chambre","Aux automobilistes cherchant un parking"],"correct":"B","explanation":"Le passage indique : « Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation. » Cela justifie la réponse : Aux résidents isolés pendant la chaleur."},{"number":18,"points":15,"passage":"La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour.","question":"Pourquoi la tente a-t-elle été écartée ?","options":["Elle gênerait un passage de sécurité","Elle empêcherait toute musique","Elle coûterait plus que le repas","Elle manquerait de places assises"],"correct":"A","explanation":"Le passage indique : « La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour. » Cela justifie la réponse : Elle gênerait un passage de sécurité."},{"number":19,"points":15,"passage":"Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende.","question":"Quelle est sa mission ?","options":["Décider du montant des loyers","Remplacer le gardien de nuit","Faciliter un accord entre voisins","Sanctionner immédiatement les habitants"],"correct":"C","explanation":"Le passage indique : « Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende. » Cela justifie la réponse : Faciliter un accord entre voisins."},{"number":20,"points":21,"passage":"Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées.","question":"Quel principe est retenu ?","options":["La suppression des assemblées","Des votes proportionnels à la richesse","Une participation sans domination financière","La réservation des décisions aux investisseurs"],"correct":"C","explanation":"Le passage indique : « Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. » Cela justifie la réponse : Une participation sans domination financière."},{"number":21,"points":21,"passage":"Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients.","question":"Que permet principalement ce service ?","options":["Remplacer les achats par des dons","Faciliter l'accès aux commerces locaux","Décider des menus des clients","Fermer les boutiques de proximité"],"correct":"B","explanation":"Le passage indique : « Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. » Cela justifie la réponse : Faciliter l'accès aux commerces locaux."},{"number":22,"points":21,"passage":"Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique.","question":"Quelle préoccupation a influencé le dispositif ?","options":["La suppression de l'entretien","L'augmentation du débit d'eau","Le contrôle des visiteurs","La protection de la vie privée"],"correct":"D","explanation":"Le passage indique : « Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. » Cela justifie la réponse : La protection de la vie privée."},{"number":23,"points":21,"passage":"Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois.","question":"Quelle logique suit la commune ?","options":["Adapter l'occupation à différents besoins annuels","Interdire toutes les locations touristiques","Fermer les appartements après l'été","Réserver les logements aux retraités"],"correct":"A","explanation":"Le passage indique : « Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. » Cela justifie la réponse : Adapter l'occupation à différents besoins annuels."},{"number":24,"points":21,"passage":"Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente.","question":"Pourquoi les bancs seront-ils mobiles ?","options":["Pour tester plusieurs aménagements","Pour éviter toute observation","Pour les louer chaque soir","Pour empêcher les rencontres"],"correct":"A","explanation":"Le passage indique : « Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. » Cela justifie la réponse : Pour tester plusieurs aménagements."},{"number":25,"points":21,"passage":"Un bailleur propose de remplacer certaines réunions par un questionnaire. Les locataires acceptent le questionnaire, mais demandent de conserver un échange oral pour les sujets complexes. Ils estiment qu'une case cochée n'explique pas toujours une difficulté.","question":"Que souhaitent les locataires ?","options":["Combiner plusieurs formes de consultation","Interdire les réponses écrites","Supprimer toutes les réunions","Confier les décisions à un logiciel"],"correct":"A","explanation":"Le passage indique : « Un bailleur propose de remplacer certaines réunions par un questionnaire. Les locataires acceptent le questionnaire, mais demandent de conserver un échange oral pour les sujets complexes. Ils estiment qu'une case cochée n'explique pas toujours une difficulté. » Cela justifie la réponse : Combiner plusieurs formes de consultation."},{"number":26,"points":21,"passage":"La rénovation d'une rue inclut des arbres, mais leurs racines ne disposeront pas partout du même espace. Des habitants demandent de revoir le sous-sol avant la plantation. Ils craignent que des arbres mal installés dépérissent rapidement.","question":"Quelle priorité défendent-ils ?","options":["Remplacer tous les trottoirs par du gravier","Choisir uniquement des arbres artificiels","Planter davantage sans étude","Préparer des conditions durables de plantation"],"correct":"D","explanation":"Le passage indique : « La rénovation d'une rue inclut des arbres, mais leurs racines ne disposeront pas partout du même espace. Des habitants demandent de revoir le sous-sol avant la plantation. Ils craignent que des arbres mal installés dépérissent rapidement. » Cela justifie la réponse : Préparer des conditions durables de plantation."},{"number":27,"points":21,"passage":"Une résidence supprime les petites poubelles individuelles dans ses espaces communs. Les déchets sont triés à un point unique. Le volume collecté baisse, mais le conseil rappelle qu'un déplacement du problème vers la rue annulerait ce bénéfice.","question":"Quelle réserve accompagne le bilan ?","options":["Les habitants doivent acheter plus d'emballages","Les espaces communs doivent fermer","Les déchets ne doivent pas être abandonnés ailleurs","Le tri doit devenir payant"],"correct":"C","explanation":"Le passage indique : « Une résidence supprime les petites poubelles individuelles dans ses espaces communs. Les déchets sont triés à un point unique. Le volume collecté baisse, mais le conseil rappelle qu'un déplacement du problème vers la rue annulerait ce bénéfice. » Cela justifie la réponse : Les déchets ne doivent pas être abandonnés ailleurs."},{"number":28,"points":21,"passage":"Dans un quartier en pente, un service municipal accompagne les personnes âgées au marché. Les bénévoles portent les sacs, mais laissent les bénéficiaires choisir leurs achats et leur rythme. L'autonomie compte autant que l'aide matérielle.","question":"Quelle idée caractérise l'accompagnement ?","options":["Réserver le marché aux bénévoles","Aider sans décider à la place des personnes","Faire les courses sans rencontrer les bénéficiaires","Imposer un trajet unique et rapide"],"correct":"B","explanation":"Le passage indique : « Dans un quartier en pente, un service municipal accompagne les personnes âgées au marché. Les bénévoles portent les sacs, mais laissent les bénéficiaires choisir leurs achats et leur rythme. L'autonomie compte autant que l'aide matérielle. » Cela justifie la réponse : Aider sans décider à la place des personnes."},{"number":29,"points":21,"passage":"Une cour d'école devient accessible aux riverains le week-end. La convention prévoit un partage des frais de nettoyage. L'association de parents y voit une ouverture utile, à condition que les élèves retrouvent un lieu propre le lundi.","question":"Quelle condition les parents posent-ils ?","options":["Fermer l'école le lundi","Réserver la cour aux adultes","Préserver la qualité du lieu pour les élèves","Supprimer tous les frais d'entretien"],"correct":"C","explanation":"Le passage indique : « Une cour d'école devient accessible aux riverains le week-end. La convention prévoit un partage des frais de nettoyage. L'association de parents y voit une ouverture utile, à condition que les élèves retrouvent un lieu propre le lundi. » Cela justifie la réponse : Préserver la qualité du lieu pour les élèves."},{"number":30,"points":26,"passage":"On présente souvent les immeubles partagés comme une réponse automatique à la solitude. Pourtant, un salon commun ne crée pas à lui seul des relations. Dans une résidence récente, les rencontres ont commencé lorsque des habitants ont proposé des activités souples, auxquelles chacun pouvait refuser de participer.","question":"Quelle idée l'auteur remet-il en cause ?","options":["L'utilité de toute activité collective","L'idée qu'un espace commun suffit à créer des liens","Le droit de refuser une invitation","La possibilité de vivre seul volontairement"],"correct":"B","explanation":"Le passage indique : « On présente souvent les immeubles partagés comme une réponse automatique à la solitude. Pourtant, un salon commun ne crée pas à lui seul des relations. Dans une résidence récente, les rencontres ont commencé lorsque des habitants ont proposé des activités souples, auxquelles chacun pouvait refuser de participer. » Cela justifie la réponse : L'idée qu'un espace commun suffit à créer des liens."},{"number":31,"points":26,"passage":"La ville mesure la réussite de ses rénovations par le nombre de façades refaites. Un urbaniste demande d'ajouter le confort d'été et les charges des occupants. Une façade plus belle peut masquer un appartement encore coûteux à chauffer. L'apparence ne suffit donc pas à apprécier les effets d'une intervention.","question":"Quel changement d'évaluation propose-t-il ?","options":["Abandonner toute mesure de résultat","Intégrer les conditions réelles d'habitation","Compter uniquement les logements vendus","Évaluer la couleur des façades seulement"],"correct":"B","explanation":"Le passage indique : « La ville mesure la réussite de ses rénovations par le nombre de façades refaites. Un urbaniste demande d'ajouter le confort d'été et les charges des occupants. Une façade plus belle peut masquer un appartement encore coûteux à chauffer. L'apparence ne suffit donc pas à apprécier les effets d'une intervention. » Cela justifie la réponse : Intégrer les conditions réelles d'habitation."},{"number":32,"points":26,"passage":"Un café de quartier accueille les réunions associatives sans exiger de consommation. Cette ouverture attire des habitants qui ne fréquentaient pas le lieu. Pour financer les soirées, le gérant répartit les coûts entre location ponctuelle de salle et recettes habituelles. La gratuité pour les participants repose ainsi sur un équilibre économique précis.","question":"Que comprend-on de cette gratuité ?","options":["Elle supprime les activités commerciales","Elle dépend d'autres sources de financement","Elle oblige chaque visiteur à commander","Elle signifie que le café n'a aucune dépense"],"correct":"B","explanation":"Le passage indique : « Un café de quartier accueille les réunions associatives sans exiger de consommation. Cette ouverture attire des habitants qui ne fréquentaient pas le lieu. Pour financer les soirées, le gérant répartit les coûts entre location ponctuelle de salle et recettes habituelles. La gratuité pour les participants repose ainsi sur un équilibre économique précis. » Cela justifie la réponse : Elle dépend d'autres sources de financement."},{"number":33,"points":26,"passage":"Les petites surfaces sont parfois vantées pour leur sobriété. Ce raisonnement oublie les activités déplacées hors du logement : laverie, stockage ou déplacements supplémentaires. Un logement compact peut être économe si le quartier fournit des services accessibles. Sans cette proximité, la réduction de surface ne garantit pas une réduction des dépenses.","question":"Quelle nuance le texte apporte-t-il ?","options":["La sobriété dépend aussi des services environnants","Une laverie remplace tous les services publics","Les grands logements sont toujours moins chers","La surface n'a aucun effet sur le quotidien"],"correct":"A","explanation":"Le passage indique : « Les petites surfaces sont parfois vantées pour leur sobriété. Ce raisonnement oublie les activités déplacées hors du logement : laverie, stockage ou déplacements supplémentaires. Un logement compact peut être économe si le quartier fournit des services accessibles. Sans cette proximité, la réduction de surface ne garantit pas une réduction des dépenses. » Cela justifie la réponse : La sobriété dépend aussi des services environnants."},{"number":34,"points":26,"passage":"Pour attribuer des jardins familiaux, une ville utilisait uniquement l'ancienneté de la demande. Elle réserve désormais quelques parcelles aux personnes sans espace extérieur et organise un renouvellement partiel. Cette modification rend l'accès moins prévisible pour les anciens inscrits, mais élargit les profils des bénéficiaires.","question":"Quel arbitrage est décrit ?","options":["Supprimer l'accès aux personnes sans balcon","Attribuer tous les jardins au hasard chaque semaine","Favoriser exclusivement les premiers inscrits","Équilibrer continuité des demandes et ouverture à d'autres besoins"],"correct":"D","explanation":"Le passage indique : « Pour attribuer des jardins familiaux, une ville utilisait uniquement l'ancienneté de la demande. Elle réserve désormais quelques parcelles aux personnes sans espace extérieur et organise un renouvellement partiel. Cette modification rend l'accès moins prévisible pour les anciens inscrits, mais élargit les profils des bénéficiaires. » Cela justifie la réponse : Équilibrer continuité des demandes et ouverture à d'autres besoins."},{"number":35,"points":26,"passage":"Les commerces au rez-de-chaussée participent à l'animation d'une rue. Pourtant, certaines activités gênent les riverains par leurs livraisons ou leurs horaires. Une association refuse de choisir entre une rue vide et une activité sans règles. Elle défend des accords locaux qui maintiennent les services tout en limitant les nuisances.","question":"Quelle position l'association adopte-t-elle ?","options":["Éloigner systématiquement les habitants","Fermer tous les commerces","Rechercher une coexistence négociée","Accepter toute nuisance commerciale"],"correct":"C","explanation":"Le passage indique : « Les commerces au rez-de-chaussée participent à l'animation d'une rue. Pourtant, certaines activités gênent les riverains par leurs livraisons ou leurs horaires. Une association refuse de choisir entre une rue vide et une activité sans règles. Elle défend des accords locaux qui maintiennent les services tout en limitant les nuisances. » Cela justifie la réponse : Rechercher une coexistence négociée."},{"number":36,"points":33,"passage":"Une ville annonce des logements « abordables » en comparant leurs loyers à ceux des annonces privées les plus récentes. Une chercheuse remarque que cette comparaison ignore les revenus des ménages visés. Un prix inférieur au marché peut encore absorber une part excessive du budget d'une famille. Elle ne rejette pas le programme, mais demande de préciser pour qui il devient accessible. L'abordabilité doit donc être appréciée par rapport aux ressources des occupants, et pas seulement aux prix voisins.","question":"Quelle limite de l'annonce est soulignée ?","options":["La chercheuse exige l'arrêt immédiat du programme","Les revenus empêchent toute comparaison de logements","Un loyer inférieur au marché est nécessairement accessible","La comparaison des prix ne suffit pas à mesurer l'accessibilité"],"correct":"D","explanation":"Le passage indique : « L'abordabilité doit donc être appréciée par rapport aux ressources des occupants, et pas seulement aux prix voisins. » Cela justifie la réponse : La comparaison des prix ne suffit pas à mesurer l'accessibilité."},{"number":37,"points":33,"passage":"Une résidence organise chaque semaine un repas partagé. Au début, le conseil souhaitait rendre la présence obligatoire pour lutter contre l'isolement. Plusieurs habitants ont expliqué qu'ils travaillaient le soir ou préféraient des rencontres moins nombreuses. Le projet a été revu : chacun peut proposer un autre créneau ou participer autrement. L'objectif de convivialité est conservé, mais il ne justifie plus une obligation identique pour tous.","question":"Que révèle l'évolution du projet ?","options":["L'impossibilité de modifier une décision collective","L'abandon complet de toute activité commune","Le refus des habitants de se rencontrer un jour","La participation collective doit tenir compte des situations individuelles"],"correct":"D","explanation":"Le passage indique : « L'objectif de convivialité est conservé, mais il ne justifie plus une obligation identique pour tous. » Cela justifie la réponse : La participation collective doit tenir compte des situations individuelles."},{"number":38,"points":33,"passage":"À l'occasion d'une rénovation, un quartier reçoit une nouvelle image dans les brochures touristiques. Ses commerces et ses places deviennent plus attractifs. Cependant, plusieurs ateliers anciens quittent les lieux après une hausse des loyers. Les responsables célèbrent la fréquentation, tandis que des habitants regrettent la disparition de services familiers. Le renouvellement urbain peut améliorer l'attractivité tout en fragilisant certaines fonctions qui faisaient vivre le quartier.","question":"Quel paradoxe le texte met-il en évidence ?","options":["Les habitants refusent toute amélioration des places","Le succès d'un quartier peut évincer des activités utiles à ses habitants","Les loyers diminuent lorsque les commerces partent","La rénovation empêche toujours l'arrivée de visiteurs"],"correct":"B","explanation":"Le passage indique : « Le renouvellement urbain peut améliorer l'attractivité tout en fragilisant certaines fonctions qui faisaient vivre le quartier. » Cela justifie la réponse : Le succès d'un quartier peut évincer des activités utiles à ses habitants."},{"number":39,"points":33,"passage":"Pour construire plus vite, une municipalité veut uniformiser les plans de ses futurs logements. Des architectes reconnaissent que certains éléments techniques peuvent être répétés. Ils contestent toutefois l'idée qu'une même distribution conviendrait à un étudiant, à une famille et à une personne qui travaille chez elle. Leur proposition conserve des composants communs tout en permettant des transformations. L'économie de moyens devient pertinente lorsqu'elle rend l'adaptation possible au lieu d'effacer la diversité des usages.","question":"Quelle solution ces architectes défendent-ils ?","options":["Dessiner un logement strictement identique pour chaque occupant","Renoncer à toute technique répétable","Interdire l'évolution des logements après leur construction","Associer des éléments communs à des aménagements adaptables"],"correct":"D","explanation":"Le passage indique : « L'économie de moyens devient pertinente lorsqu'elle rend l'adaptation possible au lieu d'effacer la diversité des usages. » Cela justifie la réponse : Associer des éléments communs à des aménagements adaptables."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-03','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-03","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 03","topic":"Travailler et développer ses compétences","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale.","question":"Qu'est-ce qui est maintenu ?","options":["L'accueil toute la journée","Les cours de l'après-midi","Les inscriptions du soir","L'entrée principale ouverte"],"correct":"B","explanation":"Le passage indique : « L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale. » Cela justifie la réponse : Les cours de l'après-midi."},{"number":2,"points":3,"passage":"Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles.","question":"Que faut-il apporter ?","options":["Un contrat signé","Une offre d'emploi","Une lettre de recommandation","Un ordinateur"],"correct":"B","explanation":"Le passage indique : « Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles. » Cela justifie la réponse : Une offre d'emploi."},{"number":3,"points":3,"passage":"Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis.","question":"Quand faut-il libérer les casiers ?","options":["Lundi après les travaux","Mardi matin","À la fin du mois","Avant dimanche soir"],"correct":"D","explanation":"Le passage indique : « Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis. » Cela justifie la réponse : Avant dimanche soir."},{"number":4,"points":3,"passage":"La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes.","question":"Quel changement est annoncé ?","options":["La durée de la réunion","Le jour de la réunion","Le nom du responsable","Le mode de participation"],"correct":"D","explanation":"Le passage indique : « La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes. » Cela justifie la réponse : Le mode de participation."},{"number":5,"points":9,"passage":"Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient.","question":"Quel service l'auteur veut-il conserver ?","options":["Celui du mercredi","Celui du samedi","Celui du vendredi","Tous les services du matin"],"correct":"C","explanation":"Le passage indique : « Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient. » Cela justifie la réponse : Celui du vendredi."},{"number":6,"points":9,"passage":"Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage.","question":"Quelle qualité est particulièrement recherchée ?","options":["La discrétion","Une expérience de direction","La maîtrise d'un camion","La connaissance de trois langues"],"correct":"A","explanation":"Le passage indique : « Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage. » Cela justifie la réponse : La discrétion."},{"number":7,"points":9,"passage":"J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille.","question":"Pourquoi cette personne refuse-t-elle ?","options":["Le salaire serait réduit","Le poste disparaît prochainement","Les déplacements ne lui conviennent pas","Elle souhaite travailler à l'étranger"],"correct":"C","explanation":"Le passage indique : « J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille. » Cela justifie la réponse : Les déplacements ne lui conviennent pas."},{"number":8,"points":9,"passage":"La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement.","question":"À quoi sert cette visite ?","options":["Remplacer l'entretien","Signer immédiatement le contrat","Mieux comprendre le travail proposé","Noter la vitesse des candidats"],"correct":"C","explanation":"Le passage indique : « La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement. » Cela justifie la réponse : Mieux comprendre le travail proposé."},{"number":9,"points":9,"passage":"Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale.","question":"Quelles demandes peuvent encore être traitées ce mois-ci ?","options":["Toutes les demandes tardives","Les demandes sans justification professionnelle","Les urgences familiales","Seulement les demandes de congés d'été"],"correct":"C","explanation":"Le passage indique : « Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale. » Cela justifie la réponse : Les urgences familiales."},{"number":10,"points":9,"passage":"L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée.","question":"Comment l'apprentissage sera-t-il organisé ?","options":["Uniquement à domicile","Entre formation et travail accompagné","Sans présence en entreprise","Par un examen quotidien éliminatoire"],"correct":"B","explanation":"Le passage indique : « L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée. » Cela justifie la réponse : Entre formation et travail accompagné."},{"number":11,"points":15,"passage":"Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur.","question":"Quel est son objectif ?","options":["Devenir formatrice immédiatement","Ouvrir une agence de voyages","Abandonner son secteur","Mettre ses compétences à jour"],"correct":"D","explanation":"Le passage indique : « Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur. » Cela justifie la réponse : Mettre ses compétences à jour."},{"number":12,"points":15,"passage":"Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions.","question":"Qu'est-ce qui caractérise ce carnet ?","options":["Il est réservé aux clients","Il reste définitivement inchangé","Il remplace toutes les formations","Il s'enrichit de l'expérience du terrain"],"correct":"D","explanation":"Le passage indique : « Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions. » Cela justifie la réponse : Il s'enrichit de l'expérience du terrain."},{"number":13,"points":15,"passage":"Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique.","question":"Quelle approche privilégie-t-il ?","options":["L'essai accompagné","L'observation sans exercice","La mémorisation des tarifs","Le travail sans retour"],"correct":"A","explanation":"Le passage indique : « Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique. » Cela justifie la réponse : L'essai accompagné."},{"number":14,"points":15,"passage":"La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil.","question":"Qui peut bénéficier du prêt ?","options":["Seulement les formateurs","Les entreprises achetant un abonnement","Uniquement des chômeurs inscrits","Des personnes aux situations professionnelles variées"],"correct":"D","explanation":"Le passage indique : « La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil. » Cela justifie la réponse : Des personnes aux situations professionnelles variées."},{"number":15,"points":15,"passage":"Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne.","question":"Quelle limite encadre cette souplesse ?","options":["L'obligation de manger ensemble","Le maintien du fonctionnement de la ligne","La suppression de toutes les pauses","L'autorisation préalable des clients"],"correct":"B","explanation":"Le passage indique : « Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne. » Cela justifie la réponse : Le maintien du fonctionnement de la ligne."},{"number":16,"points":15,"passage":"Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard.","question":"Que cherche ce procédé ?","options":["Examiner d'abord les compétences en situation","Éliminer toute personne diplômée","Choisir les candidats les plus jeunes","Supprimer l'entretien avec le candidat"],"correct":"A","explanation":"Le passage indique : « Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard. » Cela justifie la réponse : Examiner d'abord les compétences en situation."},{"number":17,"points":15,"passage":"Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion.","question":"Pourquoi garde-t-elle son emploi ?","options":["Parce que la formation est déjà terminée","Pour avancer prudemment dans son projet","Pour devenir responsable du cours","Parce qu'elle renonce au métier envisagé"],"correct":"B","explanation":"Le passage indique : « Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion. » Cela justifie la réponse : Pour avancer prudemment dans son projet."},{"number":18,"points":15,"passage":"Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges.","question":"Quelle précaution est prise ?","options":["Préserver la confidentialité des échanges","Diffuser les questions à toute l'équipe","Enregistrer toutes les conversations publiquement","Recevoir uniquement des groupes"],"correct":"A","explanation":"Le passage indique : « Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges. » Cela justifie la réponse : Préserver la confidentialité des échanges."},{"number":19,"points":15,"passage":"Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification.","question":"Quel comportement est demandé ?","options":["Vérifier les informations incertaines","Rassurer le client sans consulter personne","Éviter toute conversation avec la cuisine","Supprimer tous les plats du menu"],"correct":"A","explanation":"Le passage indique : « Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification. » Cela justifie la réponse : Vérifier les informations incertaines."},{"number":20,"points":21,"passage":"Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants.","question":"Quel avantage offre l'évaluation initiale ?","options":["Garantir le diplôme sans formation","Imposer le même calendrier à chacun","Supprimer tous les examens","Éviter des apprentissages déjà maîtrisés"],"correct":"D","explanation":"Le passage indique : « Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. » Cela justifie la réponse : Éviter des apprentissages déjà maîtrisés."},{"number":21,"points":21,"passage":"Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante.","question":"Quels critères seront comparés ?","options":["Uniquement le prix des véhicules","La performance et les conditions de travail","Le nombre de publicités affichées","Les préférences musicales des conducteurs"],"correct":"B","explanation":"Le passage indique : « Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. » Cela justifie la réponse : La performance et les conditions de travail."},{"number":22,"points":21,"passage":"Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent.","question":"Quelle limite du service est précisée ?","options":["Seuls les salariés sont reçus","L'accompagnement ne garantit pas la certification","Le bénévolat ne peut jamais être décrit","L'association délivre tous les diplômes"],"correct":"B","explanation":"Le passage indique : « Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. » Cela justifie la réponse : L'accompagnement ne garantit pas la certification."},{"number":23,"points":21,"passage":"Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations.","question":"Pourquoi l'organisation a-t-elle évolué ?","options":["Pour concilier échange et concentration","Pour interdire tout travail collectif","Pour augmenter le bruit des appels","Pour réduire le nombre de clients"],"correct":"A","explanation":"Le passage indique : « Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. » Cela justifie la réponse : Pour concilier échange et concentration."},{"number":24,"points":21,"passage":"Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun.","question":"Quel objectif poursuit l'hôtel ?","options":["Imposer des nuits à tous les clients","Remplacer tout le personnel par une machine","Rendre le service moins dépendant d'une personne","Supprimer les repos"],"correct":"C","explanation":"Le passage indique : « Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. » Cela justifie la réponse : Rendre le service moins dépendant d'une personne."},{"number":25,"points":21,"passage":"Les salariés d'une petite entreprise choisissent les sujets de leur journée annuelle de formation. Certains demandent des outils immédiatement utiles, d'autres un temps de réflexion sur leur métier. Le programme final conserve les deux approches.","question":"Quel compromis est trouvé ?","options":["Choisir uniquement des sujets théoriques","Reporter toutes les formations","Associer utilité immédiate et réflexion professionnelle","Réserver la journée aux cadres"],"correct":"C","explanation":"Le passage indique : « Les salariés d'une petite entreprise choisissent les sujets de leur journée annuelle de formation. Certains demandent des outils immédiatement utiles, d'autres un temps de réflexion sur leur métier. Le programme final conserve les deux approches. » Cela justifie la réponse : Associer utilité immédiate et réflexion professionnelle."},{"number":26,"points":21,"passage":"Une école professionnelle invite d'anciens élèves ayant changé plusieurs fois de métier. Elle veut montrer des parcours rarement linéaires, plutôt que présenter une seule trajectoire idéale. Les témoignages portent aussi sur les hésitations et les échecs.","question":"Que souhaitent montrer les organisateurs ?","options":["L'inutilité de toute formation","Une réussite sans difficulté pour tous","La nécessité de garder toujours le même poste","La diversité des parcours professionnels"],"correct":"D","explanation":"Le passage indique : « Une école professionnelle invite d'anciens élèves ayant changé plusieurs fois de métier. Elle veut montrer des parcours rarement linéaires, plutôt que présenter une seule trajectoire idéale. Les témoignages portent aussi sur les hésitations et les échecs. » Cela justifie la réponse : La diversité des parcours professionnels."},{"number":27,"points":21,"passage":"Un atelier réserve du temps à la transmission avant le départ d'un salarié expérimenté. Des vidéos seront réalisées, mais elles seront accompagnées de séances pratiques. Certaines décisions dépendent de sensations que l'image seule explique mal.","question":"Pourquoi les vidéos ne suffisent-elles pas ?","options":["Les nouveaux employés refusent de regarder","Une partie du savoir exige une expérience pratique","Le salarié ne connaît pas son métier","Les vidéos sont interdites dans l'atelier"],"correct":"B","explanation":"Le passage indique : « Un atelier réserve du temps à la transmission avant le départ d'un salarié expérimenté. Des vidéos seront réalisées, mais elles seront accompagnées de séances pratiques. Certaines décisions dépendent de sensations que l'image seule explique mal. » Cela justifie la réponse : Une partie du savoir exige une expérience pratique."},{"number":28,"points":21,"passage":"Une enquête interne révèle que des employés n'utilisent pas leur droit à la formation. Les horaires proposés coïncident avec leurs obligations familiales. La direction ajoute des créneaux différents plutôt que conclure à un manque de motivation.","question":"Quelle interprétation est privilégiée ?","options":["Les formations sont inutiles par nature","Les employés refusent tous d'apprendre","Les familles doivent financer les cours","L'organisation peut empêcher la participation"],"correct":"D","explanation":"Le passage indique : « Une enquête interne révèle que des employés n'utilisent pas leur droit à la formation. Les horaires proposés coïncident avec leurs obligations familiales. La direction ajoute des créneaux différents plutôt que conclure à un manque de motivation. » Cela justifie la réponse : L'organisation peut empêcher la participation."},{"number":29,"points":21,"passage":"Un espace de travail propose des bureaux à la journée. Plusieurs indépendants apprécient la souplesse, mais demandent une formule stable pour retrouver les mêmes voisins. La liberté de venir ponctuellement ne répond pas à tous les besoins de relation professionnelle.","question":"Quel besoin supplémentaire apparaît ?","options":["Des horaires toujours plus courts","Une continuité dans les rencontres","Une fermeture des bureaux partagés","L'absence totale de collègues"],"correct":"B","explanation":"Le passage indique : « Un espace de travail propose des bureaux à la journée. Plusieurs indépendants apprécient la souplesse, mais demandent une formule stable pour retrouver les mêmes voisins. La liberté de venir ponctuellement ne répond pas à tous les besoins de relation professionnelle. » Cela justifie la réponse : Une continuité dans les rencontres."},{"number":30,"points":26,"passage":"Une entreprise compte les heures de connexion pour évaluer le travail à distance. Une représentante du personnel remarque qu'une présence numérique longue ne dit rien de la difficulté des dossiers traités. Elle propose d'étudier les résultats avec les salariés, tout en tenant compte du temps nécessaire pour les obtenir.","question":"Quelle critique formule-t-elle ?","options":["Les dossiers difficiles demandent toujours moins de temps","Le travail à distance interdit toute évaluation","La durée de connexion est un indicateur insuffisant","Les résultats ne doivent jamais être examinés"],"correct":"C","explanation":"Le passage indique : « Une entreprise compte les heures de connexion pour évaluer le travail à distance. Une représentante du personnel remarque qu'une présence numérique longue ne dit rien de la difficulté des dossiers traités. Elle propose d'étudier les résultats avec les salariés, tout en tenant compte du temps nécessaire pour les obtenir. » Cela justifie la réponse : La durée de connexion est un indicateur insuffisant."},{"number":31,"points":26,"passage":"Les appels à la « passion du métier » peuvent soutenir l'engagement. Mais lorsqu'ils servent à justifier des heures non reconnues, ils masquent un déséquilibre. Un collectif de soignants défend la qualité du service tout en demandant des moyens et des horaires soutenables. Leur demande ne traduit pas un désintérêt pour leur travail.","question":"Quelle opposition le texte refuse-t-il ?","options":["Opposer deux méthodes de prise de notes","Opposer engagement professionnel et bonnes conditions de travail","Distinguer salaire et coût des transports","Comparer deux spécialités médicales"],"correct":"B","explanation":"Le passage indique : « Les appels à la « passion du métier » peuvent soutenir l'engagement. Mais lorsqu'ils servent à justifier des heures non reconnues, ils masquent un déséquilibre. Un collectif de soignants défend la qualité du service tout en demandant des moyens et des horaires soutenables. Leur demande ne traduit pas un désintérêt pour leur travail. » Cela justifie la réponse : Opposer engagement professionnel et bonnes conditions de travail."},{"number":32,"points":26,"passage":"Un diplôme décrit des acquis, mais ne résume pas toutes les aptitudes nécessaires dans une équipe. Un recruteur combine donc exercice technique, entretien et période d'observation rémunérée. Aucun de ces éléments n'est considéré comme infaillible. Leur intérêt vient du croisement des informations qu'ils apportent.","question":"Quelle conception du recrutement est défendue ?","options":["Éclairer la décision par plusieurs observations","Choisir sans rencontrer les candidats","Écarter toute preuve technique","Se fier exclusivement au diplôme"],"correct":"A","explanation":"Le passage indique : « Un diplôme décrit des acquis, mais ne résume pas toutes les aptitudes nécessaires dans une équipe. Un recruteur combine donc exercice technique, entretien et période d'observation rémunérée. Aucun de ces éléments n'est considéré comme infaillible. Leur intérêt vient du croisement des informations qu'ils apportent. » Cela justifie la réponse : Éclairer la décision par plusieurs observations."},{"number":33,"points":26,"passage":"La spécialisation rend certains services très efficaces, jusqu'au jour où une personne indispensable s'absente. Pour limiter ce risque, une entreprise organise des échanges de savoirs. Elle ne demande pas à chacun de tout maîtriser : elle veut que les collègues comprennent suffisamment les tâches voisines pour assurer une continuité.","question":"Quel équilibre recherche-t-elle ?","options":["Conserver l'expertise tout en réduisant la dépendance individuelle","Rendre toutes les compétences identiques","Supprimer les congés des spécialistes","Multiplier les tâches sans formation"],"correct":"A","explanation":"Le passage indique : « La spécialisation rend certains services très efficaces, jusqu'au jour où une personne indispensable s'absente. Pour limiter ce risque, une entreprise organise des échanges de savoirs. Elle ne demande pas à chacun de tout maîtriser : elle veut que les collègues comprennent suffisamment les tâches voisines pour assurer une continuité. » Cela justifie la réponse : Conserver l'expertise tout en réduisant la dépendance individuelle."},{"number":34,"points":26,"passage":"Une formation courte promet des débouchés rapides. Des anciens stagiaires saluent la qualité des exercices, tout en signalant le manque de contacts avec les employeurs locaux. Ils distinguent l'apprentissage d'une technique de l'accès effectif à un emploi. Améliorer le second suppose un accompagnement que le seul contenu des cours ne remplace pas.","question":"Quelle distinction est faite ?","options":["Une formation pratique empêche de travailler","Les employeurs doivent supprimer les exercices","Savoir faire un travail ne garantit pas d'obtenir un poste","Les stagiaires refusent tout accompagnement"],"correct":"C","explanation":"Le passage indique : « Une formation courte promet des débouchés rapides. Des anciens stagiaires saluent la qualité des exercices, tout en signalant le manque de contacts avec les employeurs locaux. Ils distinguent l'apprentissage d'une technique de l'accès effectif à un emploi. Améliorer le second suppose un accompagnement que le seul contenu des cours ne remplace pas. » Cela justifie la réponse : Savoir faire un travail ne garantit pas d'obtenir un poste."},{"number":35,"points":26,"passage":"Un service accorde aux équipes le choix de leurs méthodes, mais maintient des objectifs de sécurité communs. Cette autonomie exige de discuter les décisions et d'expliquer les écarts. Elle ne consiste donc pas à laisser chaque salarié agir sans règle. Les responsables doivent davantage accompagner et moins contrôler chaque geste.","question":"Comment l'autonomie est-elle présentée ?","options":["Comme l'absence de toute règle","Comme un retour au contrôle permanent","Comme une suppression du rôle des responsables","Comme une responsabilité encadrée par des exigences partagées"],"correct":"D","explanation":"Le passage indique : « Un service accorde aux équipes le choix de leurs méthodes, mais maintient des objectifs de sécurité communs. Cette autonomie exige de discuter les décisions et d'expliquer les écarts. Elle ne consiste donc pas à laisser chaque salarié agir sans règle. Les responsables doivent davantage accompagner et moins contrôler chaque geste. » Cela justifie la réponse : Comme une responsabilité encadrée par des exigences partagées."},{"number":36,"points":33,"passage":"Le terme de compétence « transférable » laisse parfois croire qu'une aptitude passe sans effort d'un métier à un autre. Une organisatrice d'événements sait gérer des imprévus, mais doit apprendre les règles particulières du secteur hospitalier où elle souhaite travailler. Son expérience constitue un appui, pas une équivalence totale. Reconnaître les acquis et identifier ce qui reste à apprendre sont deux démarches complémentaires.","question":"Quelle nuance est apportée à la notion de transfert ?","options":["Une aptitude utile doit être adaptée au nouveau contexte","Toute expérience antérieure devient inutile","Un changement de secteur dispense de formation","Les règles professionnelles sont identiques partout"],"correct":"A","explanation":"Le passage indique : « Reconnaître les acquis et identifier ce qui reste à apprendre sont deux démarches complémentaires. » Cela justifie la réponse : Une aptitude utile doit être adaptée au nouveau contexte."},{"number":37,"points":33,"passage":"Un logiciel réduit le temps consacré aux tâches administratives. La direction veut utiliser tout le temps libéré pour augmenter le nombre de dossiers. Les salariés proposent d'en consacrer une partie à l'accueil des cas complexes, jusqu'alors traités trop vite. Ils ne contestent pas l'outil, mais la seule définition quantitative de son bénéfice. Un gain de temps peut améliorer la qualité du travail sans se traduire intégralement par une hausse du volume.","question":"Quel débat le logiciel fait-il apparaître ?","options":["La nécessité d'interdire tout outil numérique","Le remplacement immédiat des salariés","La manière de répartir les bénéfices de la productivité","La disparition de tous les cas complexes"],"correct":"C","explanation":"Le passage indique : « Un gain de temps peut améliorer la qualité du travail sans se traduire intégralement par une hausse du volume. » Cela justifie la réponse : La manière de répartir les bénéfices de la productivité."},{"number":38,"points":33,"passage":"Dans un atelier, le meilleur réparateur devient responsable d'équipe. Il découvre que transmettre une consigne et résoudre un conflit demandent d'autres aptitudes que réparer une machine. L'entreprise avait considéré la promotion comme une récompense suffisante, sans prévoir de formation. L'expertise technique ne prépare pas automatiquement à l'accompagnement des personnes, même si elle peut en faciliter la compréhension du travail.","question":"Quelle erreur d'organisation est mise en évidence ?","options":["Confondre maîtrise technique et préparation au management","Maintenir des machines en état de fonctionnement","Considérer les conflits comme toujours utiles","Promouvoir un salarié connaissant l'atelier"],"correct":"A","explanation":"Le passage indique : « L'expertise technique ne prépare pas automatiquement à l'accompagnement des personnes, même si elle peut en faciliter la compréhension du travail. » Cela justifie la réponse : Confondre maîtrise technique et préparation au management."},{"number":39,"points":33,"passage":"Une organisation souhaite diversifier ses recrutements. Elle affiche cet objectif, puis conserve des entretiens à une heure inaccessible aux personnes déjà en poste et exige des stages non rémunérés. Une association souligne le décalage entre l'intention et les conditions concrètes. L'ouverture réelle du recrutement suppose de revoir les procédures qui excluent des candidats, même quand elles semblent ordinaires aux recruteurs.","question":"Que faut-il changer selon cette association ?","options":["Les objectifs de sécurité des postes","Les compétences de tous les anciens salariés","Uniquement le graphisme des annonces","Les obstacles pratiques intégrés au recrutement"],"correct":"D","explanation":"Le passage indique : « L'ouverture réelle du recrutement suppose de revoir les procédures qui excluent des candidats, même quand elles semblent ordinaires aux recruteurs. » Cela justifie la réponse : Les obstacles pratiques intégrés au recrutement."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-04','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-04","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 04","topic":"Voyager et se déplacer","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures.","question":"Que doit vérifier le voyageur ?","options":["Le numéro de sa place","Un nouvel horaire","Le prix du billet","Le nouveau quai"],"correct":"D","explanation":"Le passage indique : « Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures. » Cela justifie la réponse : Le nouveau quai."},{"number":2,"points":3,"passage":"Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire.","question":"Comment utiliser un billet acheté pour la veille ?","options":["Acheter un second billet","Demander un remboursement obligatoire","Le présenter directement à l'entrée","L'envoyer par courrier"],"correct":"C","explanation":"Le passage indique : « Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire. » Cela justifie la réponse : Le présenter directement à l'entrée."},{"number":3,"points":3,"passage":"La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin.","question":"Quel itinéraire est proposé aux cyclistes ?","options":["Prendre un bateau obligatoire","Traverser la passerelle à vélo","Attendre le lendemain","Passer par le pont voisin"],"correct":"D","explanation":"Le passage indique : « La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin. » Cela justifie la réponse : Passer par le pont voisin."},{"number":4,"points":3,"passage":"Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques.","question":"Où chercher un bagage oublié ?","options":["Dans une consigne automatique","Au bureau de la gare","À l'arrêt du tramway","Dans le train suivant"],"correct":"B","explanation":"Le passage indique : « Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques. » Cela justifie la réponse : Au bureau de la gare."},{"number":5,"points":9,"passage":"Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé.","question":"Pourquoi l'achat doit-il attendre ?","options":["Les billets sont tous gratuits","Le trajet est annulé définitivement","La durée du séjour reste incertaine","La famille refuse la visite"],"correct":"C","explanation":"Le passage indique : « Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé. » Cela justifie la réponse : La durée du séjour reste incertaine."},{"number":6,"points":9,"passage":"Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures.","question":"Que doit apporter le client ?","options":["Un réfrigérateur","Des draps","Une serviette","Une clé de cuisine"],"correct":"C","explanation":"Le passage indique : « Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures. » Cela justifie la réponse : Une serviette."},{"number":7,"points":9,"passage":"Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas.","question":"Quel avantage motive ce choix ?","options":["Arriver en soirée","Voyager sans réservation","Économiser une nuit d'hébergement","Atteindre la vitesse maximale"],"correct":"C","explanation":"Le passage indique : « Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas. » Cela justifie la réponse : Économiser une nuit d'hébergement."},{"number":8,"points":9,"passage":"L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ.","question":"Pourquoi faut-il s'inscrire ?","options":["La visite nécessite un passeport","Le nombre de participants est limité","L'entrée de la ville est payante","Le guide travaille uniquement en ligne"],"correct":"B","explanation":"Le passage indique : « L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ. » Cela justifie la réponse : Le nombre de participants est limité."},{"number":9,"points":9,"passage":"Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation.","question":"Quel effet le marché a-t-il sur le trajet ?","options":["Tous les arrêts deviennent payants","Le bus circule en sens inverse","Le lieu d'embarquement change","Le service cesse pour la journée"],"correct":"C","explanation":"Le passage indique : « Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation. » Cela justifie la réponse : Le lieu d'embarquement change."},{"number":10,"points":9,"passage":"Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel.","question":"Quelle contrainte veut-on éviter ?","options":["Réserver un hébergement","Transporter les vélos pendant les correspondances","Pédaler sur place","Acheter des boissons"],"correct":"B","explanation":"Le passage indique : « Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel. » Cela justifie la réponse : Transporter les vélos pendant les correspondances."},{"number":11,"points":15,"passage":"Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile.","question":"Quel service subsiste malgré la transformation ?","options":["Une aide humaine pour acheter un billet","La vente de repas chauds","La gratuité de tous les billets","Un guichet ouvert sans interruption"],"correct":"A","explanation":"Le passage indique : « Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile. » Cela justifie la réponse : Une aide humaine pour acheter un billet."},{"number":12,"points":15,"passage":"Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons.","question":"Pourquoi limiter les groupes ?","options":["Supprimer les visites culturelles","Réserver les rues aux voitures","Interdire tout tourisme","Faciliter la circulation dans les ruelles"],"correct":"D","explanation":"Le passage indique : « Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons. » Cela justifie la réponse : Faciliter la circulation dans les ruelles."},{"number":13,"points":15,"passage":"Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives.","question":"Pourquoi cette carte lui convient-elle ?","options":["Elle inclut un hôtel","Il ne prendra jamais le bus","Il prévoit plusieurs déplacements","Elle interdit les correspondances"],"correct":"C","explanation":"Le passage indique : « Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives. » Cela justifie la réponse : Il prévoit plusieurs déplacements."},{"number":14,"points":15,"passage":"Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués.","question":"Qu'est-ce qu'un pédibus dans ce texte ?","options":["Un autocar touristique","Un prêt de bicyclettes","Un trajet à pied accompagné","Un cours de conduite"],"correct":"C","explanation":"Le passage indique : « Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués. » Cela justifie la réponse : Un trajet à pied accompagné."},{"number":15,"points":15,"passage":"Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas.","question":"Pourquoi anticiper la réservation du dîner ?","options":["Réserver toutes les chambres","Éviter les frais de transport des clients","Adapter des provisions limitées","Permettre un service nocturne permanent"],"correct":"C","explanation":"Le passage indique : « Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas. » Cela justifie la réponse : Adapter des provisions limitées."},{"number":16,"points":15,"passage":"Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles.","question":"Quelle particularité offre cette promenade ?","options":["La parole des habitants enrichit la visite","Les informations historiques sont interdites","Le visiteur doit devenir guide","Les monuments sont tous reconstruits"],"correct":"A","explanation":"Le passage indique : « Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles. » Cela justifie la réponse : La parole des habitants enrichit la visite."},{"number":17,"points":15,"passage":"Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus.","question":"Pourquoi consulter les non-utilisateurs ?","options":["Les obliger à acheter un vélo","Comprendre ce qui freine l'usage","Fixer le prix des voitures","Remplacer les cyclistes dans l'enquête"],"correct":"B","explanation":"Le passage indique : « Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus. » Cela justifie la réponse : Comprendre ce qui freine l'usage."},{"number":18,"points":15,"passage":"Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures.","question":"Quelle distinction faut-il faire ?","options":["Les chambres deviennent des consignes publiques","Les sacs doivent quitter l'hôtel à onze heures","Le dépôt inclut une nouvelle nuit","Déposer ses sacs ne permet pas de garder sa chambre"],"correct":"D","explanation":"Le passage indique : « Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures. » Cela justifie la réponse : Déposer ses sacs ne permet pas de garder sa chambre."},{"number":19,"points":15,"passage":"La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale.","question":"Quel objectif est poursuivi ?","options":["Rendre l'orientation plus accessible aux jeunes","Réserver les stations aux familles","Augmenter le nombre de correspondances","Supprimer les noms des lignes"],"correct":"A","explanation":"Le passage indique : « La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale. » Cela justifie la réponse : Rendre l'orientation plus accessible aux jeunes."},{"number":20,"points":21,"passage":"Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison.","question":"Quelle prudence accompagne le premier bilan ?","options":["Attendre une observation plus longue","Conclure à une baisse certaine des visiteurs","Fermer les commerces le matin","Supprimer immédiatement le second bateau"],"correct":"A","explanation":"Le passage indique : « Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. » Cela justifie la réponse : Attendre une observation plus longue."},{"number":21,"points":21,"passage":"Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes.","question":"Quelle comparaison pratique-t-elle ?","options":["Elle exclut tout temps d'attente","Elle compare uniquement les repas","Elle retient seulement le prix affiché","Elle considère le trajet dans son ensemble"],"correct":"D","explanation":"Le passage indique : « Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. » Cela justifie la réponse : Elle considère le trajet dans son ensemble."},{"number":22,"points":21,"passage":"Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production.","question":"Quel principe organise ces visites ?","options":["Respecter l'activité principale de l'atelier","Garantir une ouverture touristique permanente","Transformer toutes les commandes en visites","Remplacer le métier par des spectacles"],"correct":"A","explanation":"Le passage indique : « Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. » Cela justifie la réponse : Respecter l'activité principale de l'atelier."},{"number":23,"points":21,"passage":"Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique.","question":"Que revendiquent les habitants ?","options":["Un traitement équitable pour les trajets locaux","Une priorité pour les touristes étrangers","Le rétablissement des embouteillages","La fermeture des hébergements"],"correct":"A","explanation":"Le passage indique : « Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. » Cela justifie la réponse : Un traitement équitable pour les trajets locaux."},{"number":24,"points":21,"passage":"Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule.","question":"Quelle limite de l'application est montrée ?","options":["La poussette empêche tout déplacement","Tous les itinéraires sont trop longs","Les escaliers accélèrent chaque trajet","La rapidité ne garantit pas l'accessibilité"],"correct":"D","explanation":"Le passage indique : « Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. » Cela justifie la réponse : La rapidité ne garantit pas l'accessibilité."},{"number":25,"points":21,"passage":"Un village réduit le stationnement au centre et ouvre un parking extérieur relié à pied. Les recettes du stationnement financent l'entretien du chemin. La mesure associe donc limitation de la voiture et amélioration de l'accès final.","question":"Comment les recettes sont-elles utilisées ?","options":["Pour supprimer le chemin piéton","Pour faciliter la liaison depuis le parking","Pour distribuer des voitures","Pour agrandir les rues centrales"],"correct":"B","explanation":"Le passage indique : « Un village réduit le stationnement au centre et ouvre un parking extérieur relié à pied. Les recettes du stationnement financent l'entretien du chemin. La mesure associe donc limitation de la voiture et amélioration de l'accès final. » Cela justifie la réponse : Pour faciliter la liaison depuis le parking."},{"number":26,"points":21,"passage":"Une famille choisit deux étapes longues plutôt que sept villes en dix jours. Elle renonce à plusieurs sites célèbres, mais souhaite disposer de temps pour improviser et connaître la vie quotidienne sur place.","question":"Quelle conception du voyage adopte-t-elle ?","options":["Privilégier une découverte moins dispersée","Suivre tous les sites proposés par une agence","Visiter uniquement des aéroports","Multiplier les déplacements rapides"],"correct":"A","explanation":"Le passage indique : « Une famille choisit deux étapes longues plutôt que sept villes en dix jours. Elle renonce à plusieurs sites célèbres, mais souhaite disposer de temps pour improviser et connaître la vie quotidienne sur place. » Cela justifie la réponse : Privilégier une découverte moins dispersée."},{"number":27,"points":21,"passage":"Un organisateur de sorties invite les participants à indiquer leurs besoins avant de s'inscrire. Il précise ce qui peut être adapté et ce qui ne peut pas l'être. Cette transparence évite de confondre accueil bienveillant et accessibilité réellement assurée.","question":"Pourquoi fournir ces précisions ?","options":["Refuser toute demande particulière","Réduire les informations avant l'achat","Garantir une adaptation illimitée","Permettre un choix éclairé selon les besoins"],"correct":"D","explanation":"Le passage indique : « Un organisateur de sorties invite les participants à indiquer leurs besoins avant de s'inscrire. Il précise ce qui peut être adapté et ce qui ne peut pas l'être. Cette transparence évite de confondre accueil bienveillant et accessibilité réellement assurée. » Cela justifie la réponse : Permettre un choix éclairé selon les besoins."},{"number":28,"points":21,"passage":"Une ligne rurale de bus semblait peu utilisée d'après les validations électroniques. Une enquête a révélé que plusieurs abonnements n'exigeaient pas de validation. Le comptage devait être corrigé avant de décider une suppression.","question":"Que révèle l'enquête ?","options":["Tous les trajets étaient fictifs","L'indicateur initial sous-estimait l'usage","Les abonnements étaient interdits","La ligne n'avait aucun passager"],"correct":"B","explanation":"Le passage indique : « Une ligne rurale de bus semblait peu utilisée d'après les validations électroniques. Une enquête a révélé que plusieurs abonnements n'exigeaient pas de validation. Le comptage devait être corrigé avant de décider une suppression. » Cela justifie la réponse : L'indicateur initial sous-estimait l'usage."},{"number":29,"points":21,"passage":"Une destination met en avant des séjours hors saison. Certains professionnels craignent des recettes plus faibles par semaine ; d'autres espèrent une activité moins concentrée et des emplois plus stables.","question":"Quel bénéfice possible est évoqué ?","options":["La disparition de tous les emplois saisonniers","Une meilleure continuité de l'activité","La fermeture définitive des hôtels","Une fréquentation identique chaque jour"],"correct":"B","explanation":"Le passage indique : « Une destination met en avant des séjours hors saison. Certains professionnels craignent des recettes plus faibles par semaine ; d'autres espèrent une activité moins concentrée et des emplois plus stables. » Cela justifie la réponse : Une meilleure continuité de l'activité."},{"number":30,"points":26,"passage":"Les classements touristiques comptent souvent les arrivées. Une commune préfère également regarder la durée des séjours et les dépenses réalisées auprès des entreprises locales. Un passage très bref peut encombrer le centre sans soutenir beaucoup son économie.","question":"Quelle réserve porte sur le nombre d'arrivées ?","options":["Il ne décrit pas à lui seul les retombées locales","Il prouve toujours un séjour long","Il mesure exactement chaque dépense","Il ne peut jamais être compté"],"correct":"A","explanation":"Le passage indique : « Les classements touristiques comptent souvent les arrivées. Une commune préfère également regarder la durée des séjours et les dépenses réalisées auprès des entreprises locales. Un passage très bref peut encombrer le centre sans soutenir beaucoup son économie. » Cela justifie la réponse : Il ne décrit pas à lui seul les retombées locales."},{"number":31,"points":26,"passage":"Un billet unique facilite les correspondances entre deux réseaux. Pourtant, les horaires restent mal coordonnés. Les voyageurs gagnent en simplicité d'achat, mais continuent à perdre du temps à attendre. L'intégration tarifaire représente une étape, pas une solution complète.","question":"Que manque-t-il principalement ?","options":["Une coordination des horaires","Un troisième moyen de paiement","Une hausse des prix","Une interdiction de changer de réseau"],"correct":"A","explanation":"Le passage indique : « Un billet unique facilite les correspondances entre deux réseaux. Pourtant, les horaires restent mal coordonnés. Les voyageurs gagnent en simplicité d'achat, mais continuent à perdre du temps à attendre. L'intégration tarifaire représente une étape, pas une solution complète. » Cela justifie la réponse : Une coordination des horaires."},{"number":32,"points":26,"passage":"Le terme de voyage « authentique » est parfois utilisé pour vendre une expérience préparée à l'avance. Cela ne la rend pas nécessairement sans intérêt. La difficulté apparaît lorsque les visiteurs croient découvrir une vie quotidienne spontanée alors qu'ils assistent à une mise en scène conçue pour eux.","question":"Quel problème l'auteur souligne-t-il ?","options":["Le manque de clarté sur la nature de l'expérience","L'inutilité de toute rencontre organisée","L'impossibilité de préparer une visite utile","L'absence totale de visiteurs intéressés"],"correct":"A","explanation":"Le passage indique : « Le terme de voyage « authentique » est parfois utilisé pour vendre une expérience préparée à l'avance. Cela ne la rend pas nécessairement sans intérêt. La difficulté apparaît lorsque les visiteurs croient découvrir une vie quotidienne spontanée alors qu'ils assistent à une mise en scène conçue pour eux. » Cela justifie la réponse : Le manque de clarté sur la nature de l'expérience."},{"number":33,"points":26,"passage":"Installer une piste cyclable sur un axe isolé améliore un segment du trajet. Si elle s'arrête avant un carrefour dangereux, certaines personnes continueront à éviter le vélo. Pour elles, la sécurité du parcours dépend de son point le plus difficile, et non de sa seule longueur aménagée.","question":"Quelle priorité se dégage ?","options":["Augmenter seulement la longueur annoncée","Assurer la continuité des trajets sécurisés","Ignorer les carrefours","Réserver les pistes aux habitués"],"correct":"B","explanation":"Le passage indique : « Installer une piste cyclable sur un axe isolé améliore un segment du trajet. Si elle s'arrête avant un carrefour dangereux, certaines personnes continueront à éviter le vélo. Pour elles, la sécurité du parcours dépend de son point le plus difficile, et non de sa seule longueur aménagée. » Cela justifie la réponse : Assurer la continuité des trajets sécurisés."},{"number":34,"points":26,"passage":"Une ville historique fait payer l'accès à un belvédère pour financer sa restauration. Le débat ne porte pas seulement sur le tarif : certains habitants souhaitent pouvoir continuer à fréquenter un lieu qui appartenait à leurs promenades ordinaires. La conservation soulève ainsi une question d'usage local.","question":"Quel enjeu accompagne le financement ?","options":["Réserver la promenade aux donateurs","Maintenir une place aux usages des habitants","Transformer toutes les rues en musées","Interdire la restauration du monument"],"correct":"B","explanation":"Le passage indique : « Une ville historique fait payer l'accès à un belvédère pour financer sa restauration. Le débat ne porte pas seulement sur le tarif : certains habitants souhaitent pouvoir continuer à fréquenter un lieu qui appartenait à leurs promenades ordinaires. La conservation soulève ainsi une question d'usage local. » Cela justifie la réponse : Maintenir une place aux usages des habitants."},{"number":35,"points":26,"passage":"Des stations indiquent le temps moyen de correspondance. Une association demande d'ajouter une marge pour les personnes se déplaçant lentement. Une moyenne peut être exacte pour l'ensemble des voyageurs et néanmoins trompeuse pour une partie d'entre eux. L'information doit permettre d'anticiper cette variation.","question":"Quelle amélioration est proposée ?","options":["Supprimer les correspondances","Remplacer tous les horaires par un prix","Rendre visibles les différences de temps de parcours","Annoncer une durée identique pour chacun"],"correct":"C","explanation":"Le passage indique : « Des stations indiquent le temps moyen de correspondance. Une association demande d'ajouter une marge pour les personnes se déplaçant lentement. Une moyenne peut être exacte pour l'ensemble des voyageurs et néanmoins trompeuse pour une partie d'entre eux. L'information doit permettre d'anticiper cette variation. » Cela justifie la réponse : Rendre visibles les différences de temps de parcours."},{"number":36,"points":33,"passage":"Une métropole vante une nouvelle liaison rapide avec son aéroport. Les affiches annoncent quinze minutes de trajet. Pour beaucoup d'usagers, il faut toutefois rejoindre la gare de départ, attendre le train puis parcourir les terminaux. Le chiffre annoncé reste exact entre deux points précis. Il devient trompeur lorsqu'il est compris comme la durée totale du déplacement.","question":"Quel écart le texte met-il en évidence ?","options":["Celui entre les vitesses de deux avions","Celui entre une durée partielle et le trajet réellement vécu","Celui entre les horaires d'été et d'hiver","Celui entre deux prix de billets identiques"],"correct":"B","explanation":"Le passage indique : « Il devient trompeur lorsqu'il est compris comme la durée totale du déplacement. » Cela justifie la réponse : Celui entre une durée partielle et le trajet réellement vécu."},{"number":37,"points":33,"passage":"Une région encourage le tourisme à vélo. Elle finance des itinéraires, mais plusieurs hébergements refusent encore les séjours d'une seule nuit. Les cyclistes qui avancent chaque jour doivent alors s'éloigner de leur parcours ou modifier leurs étapes. Le développement d'un mode de voyage suppose une cohérence entre l'infrastructure et les services qui permettent effectivement de l'utiliser.","question":"Quelle condition manque encore ?","options":["Des voitures pour accompagner chaque cycliste","Des séjours obligatoires d'une semaine","Des services d'hébergement adaptés à l'itinérance","La disparition des parcours balisés"],"correct":"C","explanation":"Le passage indique : « Le développement d'un mode de voyage suppose une cohérence entre l'infrastructure et les services qui permettent effectivement de l'utiliser. » Cela justifie la réponse : Des services d'hébergement adaptés à l'itinérance."},{"number":38,"points":33,"passage":"Un parc naturel limite les réservations estivales pour préserver certains sites. Des prestataires proposent en réponse des horaires très matinaux, hors du créneau réglementé. La fréquentation totale risque de rester inchangée, avec davantage de perturbations pour la faune. Une règle évaluée uniquement sur ses créneaux officiels peut déplacer la pression plutôt que la diminuer.","question":"Quelle conséquence imprévue est envisagée ?","options":["Une suppression automatique de toute visite","La fermeture de tous les prestataires","Une augmentation certaine de la biodiversité","Le déplacement de la fréquentation vers d'autres heures"],"correct":"D","explanation":"Le passage indique : « Une règle évaluée uniquement sur ses créneaux officiels peut déplacer la pression plutôt que la diminuer. » Cela justifie la réponse : Le déplacement de la fréquentation vers d'autres heures."},{"number":39,"points":33,"passage":"Les voyageurs souhaitent souvent être guidés vers des lieux moins fréquentés. Mais lorsqu'une plateforme recommande simultanément la même petite place à des milliers de personnes, elle transforme ce lieu discret en nouvelle attraction. Les informations qui dispersent individuellement les parcours peuvent ainsi concentrer collectivement les visiteurs. La gestion des flux exige d'observer les effets d'ensemble des recommandations, pas seulement leur utilité pour chaque utilisateur.","question":"Quel paradoxe est décrit ?","options":["Une information individuelle reste toujours sans effet collectif","Tous les voyageurs refusent les petites places","Les plateformes empêchent tout déplacement","Une recommandation de détour peut créer un nouveau point de concentration"],"correct":"D","explanation":"Le passage indique : « La gestion des flux exige d'observer les effets d'ensemble des recommandations, pas seulement leur utilité pour chaque utilisateur. » Cela justifie la réponse : Une recommandation de détour peut créer un nouveau point de concentration."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-05','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-05","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 05","topic":"Protéger les ressources et les milieux","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin.","question":"Où déposer les piles ?","options":["Dans la rue","Au rayon alimentaire","Dans le bac à papier","À l'accueil"],"correct":"D","explanation":"Le passage indique : « Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin. » Cela justifie la réponse : À l'accueil."},{"number":2,"points":3,"passage":"La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie.","question":"Quel contenant faut-il utiliser ?","options":["Un sac en papier","Un sac en plastique","Une boîte métallique fermée","Un seau de peinture"],"correct":"A","explanation":"Le passage indique : « La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie. » Cela justifie la réponse : Un sac en papier."},{"number":3,"points":3,"passage":"En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures.","question":"Quel arrosage reste permis ?","options":["Celui des jeunes arbres tôt le matin","Celui des parkings toute la journée","Celui des routes en soirée","Celui des pelouses à midi"],"correct":"A","explanation":"Le passage indique : « En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures. » Cela justifie la réponse : Celui des jeunes arbres tôt le matin."},{"number":4,"points":3,"passage":"Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire.","question":"Quelle nouvelle habitude est proposée ?","options":["Acheter un couvercle à chaque visite","Refuser toute boisson chaude","Rapporter des tasses sales","Utiliser sa propre tasse propre"],"correct":"D","explanation":"Le passage indique : « Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire. » Cela justifie la réponse : Utiliser sa propre tasse propre."},{"number":5,"points":9,"passage":"Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles.","question":"Que cherche à limiter ce message ?","options":["La quantité de fruits","La durée du pique-nique","Le nombre de participants","Les contenants jetables"],"correct":"D","explanation":"Le passage indique : « Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles. » Cela justifie la réponse : Les contenants jetables."},{"number":6,"points":9,"passage":"L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire.","question":"Pourquoi certains appareils sont-ils refusés ?","options":["Pour respecter les compétences disponibles","Pour limiter les lampes apportées","Parce que tout appareil ancien est interdit","Pour favoriser leur remplacement systématique"],"correct":"A","explanation":"Le passage indique : « L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire. » Cela justifie la réponse : Pour respecter les compétences disponibles."},{"number":7,"points":9,"passage":"Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon.","question":"Comment le jardin sera-t-il entretenu ?","options":["En tondant chaque jour toute la surface","En fermant le cabanon","Avec des zones volontairement non tondues","En supprimant toutes les plantes"],"correct":"C","explanation":"Le passage indique : « Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon. » Cela justifie la réponse : Avec des zones volontairement non tondues."},{"number":8,"points":9,"passage":"La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité.","question":"Quelle condition concerne les enfants ?","options":["Acheter un billet spécial","Apporter des déchets dangereux","Venir sans adulte","Avoir au moins huit ans"],"correct":"D","explanation":"Le passage indique : « La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité. » Cela justifie la réponse : Avoir au moins huit ans."},{"number":9,"points":9,"passage":"Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels.","question":"Que faut-il faire pour récupérer la somme déposée ?","options":["Le jeter dans une poubelle","Rapporter le gobelet à temps","Le conserver comme souvenir","Acheter un second billet"],"correct":"B","explanation":"Le passage indique : « Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels. » Cela justifie la réponse : Rapporter le gobelet à temps."},{"number":10,"points":9,"passage":"Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires.","question":"Quel critère est privilégié ?","options":["Le prix des outils","La gestion de l'eau","La rareté des fleurs","La hauteur des clôtures"],"correct":"B","explanation":"Le passage indique : « Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires. » Cela justifie la réponse : La gestion de l'eau."},{"number":11,"points":15,"passage":"Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis.","question":"Pourquoi pèse-t-on le contenant vide ?","options":["Pour fixer le prix du verre","Pour interdire les bocaux lourds","Pour ne facturer que le produit","Pour calculer l'âge du contenant"],"correct":"C","explanation":"Le passage indique : « Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis. » Cela justifie la réponse : Pour ne facturer que le produit."},{"number":12,"points":15,"passage":"Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables.","question":"Pourquoi répéter les mêmes conditions ?","options":["Éviter toute prise de notes","Modifier le climat du quartier","Attirer de nouveaux oiseaux artificiels","Faciliter la comparaison des observations"],"correct":"D","explanation":"Le passage indique : « Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables. » Cela justifie la réponse : Faciliter la comparaison des observations."},{"number":13,"points":15,"passage":"Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture.","question":"Quel problème la démonstration doit-elle résoudre ?","options":["Le manque de place pour les voitures","L'absence de jardin public","Les erreurs de dépôt","Le prix des légumes"],"correct":"C","explanation":"Le passage indique : « Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture. » Cela justifie la réponse : Les erreurs de dépôt."},{"number":14,"points":15,"passage":"La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année.","question":"Quel objectif guide ce remplacement ?","options":["Favoriser la diversité du vivant","Supprimer les abris d'animaux","Accroître la taille des parkings","Uniformiser tous les jardins"],"correct":"A","explanation":"Le passage indique : « La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année. » Cela justifie la réponse : Favoriser la diversité du vivant."},{"number":15,"points":15,"passage":"Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres.","question":"Pourquoi distinguer les deux catégories ?","options":["Refuser tous les tissus anciens","Éviter de trier les vêtements","Préserver la possibilité de réutilisation","Augmenter le prix des dons"],"correct":"C","explanation":"Le passage indique : « Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres. » Cela justifie la réponse : Préserver la possibilité de réutilisation."},{"number":16,"points":15,"passage":"Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs.","question":"Quelle précaution est prise ?","options":["Déplacer les nids sur la promenade","Éviter certains habitats pendant le nettoyage","Arracher toutes les plantes aquatiques","Accéder partout sans restriction"],"correct":"B","explanation":"Le passage indique : « Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs. » Cela justifie la réponse : Éviter certains habitats pendant le nettoyage."},{"number":17,"points":15,"passage":"Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel.","question":"Que veulent-ils éviter ?","options":["Une baisse de la précision des compteurs","Une interprétation trop rapide des chiffres","Un partage des informations techniques","Un remplacement des robinets"],"correct":"B","explanation":"Le passage indique : « Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel. » Cela justifie la réponse : Une interprétation trop rapide des chiffres."},{"number":18,"points":15,"passage":"Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée.","question":"Quel service est inclus ?","options":["Le nettoyage après retour","La préparation des repas","Le transport des invités","La décoration des salles"],"correct":"A","explanation":"Le passage indique : « Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée. » Cela justifie la réponse : Le nettoyage après retour."},{"number":19,"points":15,"passage":"Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux.","question":"Pourquoi choisir ce moment ?","options":["Éviter tout contact avec du sable","Réduire un risque pour les participants","Observer uniquement les poissons","Garantir la présence de touristes"],"correct":"B","explanation":"Le passage indique : « Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux. » Cela justifie la réponse : Réduire un risque pour les participants."},{"number":20,"points":21,"passage":"Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement.","question":"Quelle limite accompagne la promotion ?","options":["Supprimer toutes les réductions","Jeter les produits avant leur date","Éviter de déplacer le gaspillage vers les foyers","Acheter les plus grandes quantités"],"correct":"C","explanation":"Le passage indique : « Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. » Cela justifie la réponse : Éviter de déplacer le gaspillage vers les foyers."},{"number":21,"points":21,"passage":"Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés.","question":"Quel motif explique les fermetures ?","options":["La fragilité temporaire du sol","L'absence de panneaux publicitaires","Le prix du bois","La volonté de supprimer toutes les promenades"],"correct":"A","explanation":"Le passage indique : « Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. » Cela justifie la réponse : La fragilité temporaire du sol."},{"number":22,"points":21,"passage":"Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer.","question":"Pourquoi ajouter d'autres équipements ?","options":["Remplacer toute végétation","Empêcher les arbres de grandir","Répondre aux besoins avant la croissance des arbres","Accueillir uniquement les automobilistes"],"correct":"C","explanation":"Le passage indique : « Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. » Cela justifie la réponse : Répondre aux besoins avant la croissance des arbres."},{"number":23,"points":21,"passage":"Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim.","question":"Quelle organisation est adoptée ?","options":["Distribuer le même volume obligatoire","Supprimer les seconds services","Adapter le premier service avec possibilité de complément","Réserver les repas aux grands élèves"],"correct":"C","explanation":"Le passage indique : « Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. » Cela justifie la réponse : Adapter le premier service avec possibilité de complément."},{"number":24,"points":21,"passage":"Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile.","question":"Pourquoi noter les sorties sans prise ?","options":["Pour augmenter artificiellement les captures","Pour rendre les journées plus longues","Pour éviter un relevé limité aux résultats positifs","Pour remplacer les règles de pêche"],"correct":"C","explanation":"Le passage indique : « Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. » Cela justifie la réponse : Pour éviter un relevé limité aux résultats positifs."},{"number":25,"points":21,"passage":"Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet.","question":"Quel élément faut-il aussi considérer ?","options":["La taille des étiquettes","Les déplacements liés à l'emplacement","Uniquement la couleur des murs","Le nombre d'affiches à l'entrée"],"correct":"B","explanation":"Le passage indique : « Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet. » Cela justifie la réponse : Les déplacements liés à l'emplacement."},{"number":26,"points":21,"passage":"Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année.","question":"Quelle attitude adopte-t-il ?","options":["Évaluer les effets dans la durée","Remplacer toutes les cultures par du béton","Garantir une récolte identique sans observation","Refuser toute présence d'insectes"],"correct":"A","explanation":"Le passage indique : « Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année. » Cela justifie la réponse : Évaluer les effets dans la durée."},{"number":27,"points":21,"passage":"Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats.","question":"Quel facteur devient important dans le bilan ?","options":["La couleur des cartes de prêt","La distance entre les étagères","Le nombre de prospectus imprimés","La durée réelle d'utilisation du matériel"],"correct":"D","explanation":"Le passage indique : « Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats. » Cela justifie la réponse : La durée réelle d'utilisation du matériel."},{"number":28,"points":21,"passage":"Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée.","question":"Quel principe de gestion est retenu ?","options":["Remplir les réservoirs avec des déchets","Vendre l'eau comme potable","Arroser toutes les surfaces sans limite","Réserver l'eau aux besoins prioritaires"],"correct":"D","explanation":"Le passage indique : « Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée. » Cela justifie la réponse : Réserver l'eau aux besoins prioritaires."},{"number":29,"points":21,"passage":"Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir.","question":"Quelle limite encadre l'observation ?","options":["Transformer les refuges en vitrines","Respecter les animaux même si cela réduit la visibilité","Toucher les animaux pour les identifier","Éclairer les refuges en permanence"],"correct":"B","explanation":"Le passage indique : « Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir. » Cela justifie la réponse : Respecter les animaux même si cela réduit la visibilité."},{"number":30,"points":26,"passage":"Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace.","question":"À quel moment souhaite-t-il agir ?","options":["Après la disparition de toute matière","Après l'abandon des déchets dans la nature","Uniquement pendant la collecte","Lors de la conception du produit"],"correct":"D","explanation":"Le passage indique : « Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace. » Cela justifie la réponse : Lors de la conception du produit."},{"number":31,"points":26,"passage":"Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements.","question":"Quelle relation le texte met-il en avant ?","options":["L'emballage et les pertes de produits doivent être évalués ensemble","Un emballage léger protège toujours mieux","La casse n'a aucun effet sur le bilan","Le remplacement des produits supprime les déchets"],"correct":"A","explanation":"Le passage indique : « Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements. » Cela justifie la réponse : L'emballage et les pertes de produits doivent être évalués ensemble."},{"number":32,"points":26,"passage":"Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat.","question":"Quel intérêt présente la diversité ?","options":["Accélérer automatiquement la croissance","Supprimer le besoin d'eau","Réduire une vulnérabilité collective","Garantir l'absence de toute maladie"],"correct":"C","explanation":"Le passage indique : « Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat. » Cela justifie la réponse : Réduire une vulnérabilité collective."},{"number":33,"points":26,"passage":"Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement.","question":"Quelle condition favorise l'action ?","options":["La répétition exclusive des slogans","La suppression des services de collecte","L'augmentation des emballages imposés","La présence de moyens concrets accessibles"],"correct":"D","explanation":"Le passage indique : « Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement. » Cela justifie la réponse : La présence de moyens concrets accessibles."},{"number":34,"points":26,"passage":"Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue.","question":"Quelle approche du réemploi est proposée ?","options":["Une suppression de tout contrôle technique","Un rejet systématique des matériaux anciens","Une comparaison limitée au prix des poignées","Une appréciation dépassant la seule vitesse du chantier"],"correct":"D","explanation":"Le passage indique : « Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue. » Cela justifie la réponse : Une appréciation dépassant la seule vitesse du chantier."},{"number":35,"points":26,"passage":"Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique.","question":"Quel enjeu complète celui de la superficie ?","options":["La taille des panneaux d'entrée","La connexion entre les habitats","Le nombre de parkings","La longueur des brochures touristiques"],"correct":"B","explanation":"Le passage indique : « Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique. » Cela justifie la réponse : La connexion entre les habitats."},{"number":36,"points":33,"passage":"Une municipalité propose des sacs recyclables pour ses événements. Une équipe constate que beaucoup sont jetés avec des restes alimentaires, rendant leur traitement difficile. Le choix du matériau n'était qu'une partie du problème. Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif.","question":"Quelle distinction est essentielle ?","options":["Celle entre des événements gratuits et payants uniquement","Celle entre un matériau recyclable et son traitement réel","Celle entre deux couleurs de logo","Celle entre du matériel neuf et du matériel interdit"],"correct":"B","explanation":"Le passage indique : « Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif. » Cela justifie la réponse : Celle entre un matériau recyclable et son traitement réel."},{"number":37,"points":33,"passage":"Pour améliorer un cours d'eau, une association supprime certains obstacles et restaure des berges. Les résultats évoluent lentement et varient selon les saisons. Des financeurs souhaiteraient un chiffre simple chaque mois. L'équipe défend un suivi de plusieurs indicateurs sur plusieurs années. L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique.","question":"Pourquoi l'équipe refuse-t-elle un bilan mensuel unique ?","options":["Les saisons n'influencent jamais la rivière","Les effets du projet sont progressifs et variables","Aucune observation ne peut être réalisée","Les financeurs doivent décider sans information"],"correct":"B","explanation":"Le passage indique : « L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique. » Cela justifie la réponse : Les effets du projet sont progressifs et variables."},{"number":38,"points":33,"passage":"Une marque met en avant une forte baisse de consommation pour chaque appareil vendu. Dans le même temps, elle encourage les clients à multiplier les équipements connectés dans leur logement. Le bilan individuel s'améliore, mais le nombre d'appareils augmente. Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale.","question":"Quelle conclusion peut-on tirer ?","options":["L'efficacité technique est impossible à mesurer","Chaque nouvel appareil réduit toujours la consommation totale","Il faut regarder aussi le volume des équipements utilisés","Le nombre d'appareils reste sans rapport avec l'énergie"],"correct":"C","explanation":"Le passage indique : « Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale. » Cela justifie la réponse : Il faut regarder aussi le volume des équipements utilisés."},{"number":39,"points":33,"passage":"La plantation d'arbres est parfois proposée comme compensation immédiate d'émissions présentes. Les arbres peuvent contribuer au stockage du carbone, mais leur croissance prend du temps et leur survie dépend des conditions locales. Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis.","question":"Quelle critique est formulée ?","options":["Une promesse de stockage futur ne vaut pas un résultat immédiat garanti","Tout projet de plantation doit être abandonné","Les conditions locales n'affectent pas la survie des arbres","Les arbres ne grandissent jamais"],"correct":"A","explanation":"Le passage indique : « Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis. » Cela justifie la réponse : Une promesse de stockage futur ne vaut pas un résultat immédiat garanti."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-06','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-06","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 06","topic":"Arts, spectacles et création","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre.","question":"À partir de quand peut-on entrer ?","options":["Vingt heures","Dix-neuf heures trente","Dix-huit heures précises","Dix-huit heures trente"],"correct":"D","explanation":"Le passage indique : « Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre. » Cela justifie la réponse : Dix-huit heures trente."},{"number":2,"points":3,"passage":"La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires.","question":"Pourquoi la galerie ferme-t-elle ?","options":["Pour réduire ses horaires","Pour installer une exposition","Pour organiser un concert","Pour vendre le bâtiment"],"correct":"B","explanation":"Le passage indique : « La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires. » Cela justifie la réponse : Pour installer une exposition."},{"number":3,"points":3,"passage":"Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu.","question":"Que faut-il éviter ?","options":["Laver soi-même les costumes","Les rapporter vendredi matin","Les rendre avant midi","Utiliser la réception"],"correct":"A","explanation":"Le passage indique : « Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu. » Cela justifie la réponse : Laver soi-même les costumes."},{"number":4,"points":3,"passage":"La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte.","question":"Qu'est-ce qui change ?","options":["Le jour de la répétition","Le groupe de chanteurs","La salle de répétition","La porte d'entrée"],"correct":"C","explanation":"Le passage indique : « La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte. » Cela justifie la réponse : La salle de répétition."},{"number":5,"points":9,"passage":"Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage.","question":"Pourquoi une répétition supplémentaire est-elle prévue ?","options":["Préparer un remplacement","Vendre les instruments","Choisir la date du concert","Composer une nouvelle œuvre"],"correct":"A","explanation":"Le passage indique : « Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage. » Cela justifie la réponse : Préparer un remplacement."},{"number":6,"points":9,"passage":"L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever.","question":"Quel objet doit apporter le participant ?","options":["Du papier","De l'encre","Une blouse","Une presse"],"correct":"C","explanation":"Le passage indique : « L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever. » Cela justifie la réponse : Une blouse."},{"number":7,"points":9,"passage":"Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne.","question":"Quel risque existe sans confirmation ?","options":["Le spectacle commence plus tôt","La salle devient privée","La place peut être réattribuée","Le billet est envoyé par courrier"],"correct":"C","explanation":"Le passage indique : « Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne. » Cela justifie la réponse : La place peut être réattribuée."},{"number":8,"points":9,"passage":"Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies.","question":"Quel est le but de ce choix ?","options":["Vendre les biographies séparément","Interdire les discussions","Cacher définitivement les artistes","Regarder d'abord les œuvres elles-mêmes"],"correct":"D","explanation":"Le passage indique : « Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies. » Cela justifie la réponse : Regarder d'abord les œuvres elles-mêmes."},{"number":9,"points":9,"passage":"Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres.","question":"À quel besoin cette séance répond-elle ?","options":["Un film réservé aux critiques","Une projection plus rapide","Une salle entièrement obscure","Un environnement sensoriel plus souple"],"correct":"D","explanation":"Le passage indique : « Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres. » Cela justifie la réponse : Un environnement sensoriel plus souple."},{"number":10,"points":9,"passage":"Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain.","question":"Que peut décider le destinataire ?","options":["L'heure d'ouverture du théâtre","Le programme de la saison","Le nom des danseurs","La représentation à laquelle assister"],"correct":"D","explanation":"Le passage indique : « Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain. » Cela justifie la réponse : La représentation à laquelle assister."},{"number":11,"points":15,"passage":"Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques.","question":"Qu'est-ce qui facilite ces déplacements ?","options":["Une absence de répétitions","Un décor facilement transportable","Une scène permanente dans chaque village","Un spectacle sans interprètes"],"correct":"B","explanation":"Le passage indique : « Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques. » Cela justifie la réponse : Un décor facilement transportable."},{"number":12,"points":15,"passage":"Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles.","question":"Quel est leur intérêt ?","options":["Authentifier les œuvres vendues","Remplacer tous les originaux","Découvrir les formes par le toucher","Supprimer les visites guidées"],"correct":"C","explanation":"Le passage indique : « Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles. » Cela justifie la réponse : Découvrir les formes par le toucher."},{"number":13,"points":15,"passage":"La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande.","question":"Quelle activité n'est pas promise ?","options":["Dessiner pour chaque demande individuelle","Rencontrer des lecteurs","Créer un album","Travailler sur place"],"correct":"A","explanation":"Le passage indique : « La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande. » Cela justifie la réponse : Dessiner pour chaque demande individuelle."},{"number":14,"points":15,"passage":"Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat.","question":"Quel avantage est offert ?","options":["Tester un instrument avant de l'acheter","Éviter toute pratique personnelle","Recevoir un instrument définitivement gratuit","Choisir sans jamais essayer"],"correct":"A","explanation":"Le passage indique : « Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat. » Cela justifie la réponse : Tester un instrument avant de l'acheter."},{"number":15,"points":15,"passage":"Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement.","question":"Quel critère guide cette recommandation ?","options":["Le prix du programme","La proximité du vestiaire","La lisibilité des sous-titres","L'accès aux coulisses"],"correct":"C","explanation":"Le passage indique : « Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement. » Cela justifie la réponse : La lisibilité des sous-titres."},{"number":16,"points":15,"passage":"Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale.","question":"Que découvrent les visiteurs ?","options":["Le travail progressif de l'écriture","Les revenus exacts de l'auteur","Une version sans aucune modification","La disparition de tous les manuscrits"],"correct":"A","explanation":"Le passage indique : « Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale. » Cela justifie la réponse : Le travail progressif de l'écriture."},{"number":17,"points":15,"passage":"Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association.","question":"Quelle pièce est demandée ?","options":["Une adhésion associative","Un justificatif de domicile","Une attestation de voyage","Une carte professionnelle"],"correct":"B","explanation":"Le passage indique : « Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association. » Cela justifie la réponse : Un justificatif de domicile."},{"number":18,"points":15,"passage":"Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final.","question":"Quel contrôle leur est accordé ?","options":["Décider de toutes les images","Choisir tous les autres témoins","Remplacer le réalisateur","Vérifier l'exactitude de leurs propos"],"correct":"D","explanation":"Le passage indique : « Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final. » Cela justifie la réponse : Vérifier l'exactitude de leurs propos."},{"number":19,"points":15,"passage":"Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation.","question":"Quelle règle favorise l'accueil ?","options":["Seuls les auteurs expérimentés peuvent écouter","Les débutants doivent se taire","Tous doivent publier un livre","La lecture de son texte reste facultative"],"correct":"D","explanation":"Le passage indique : « Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation. » Cela justifie la réponse : La lecture de son texte reste facultative."},{"number":20,"points":21,"passage":"Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués.","question":"Que veut-elle préserver ?","options":["L'absence de contact avec le public","Une dimension sociale de la sortie","La suppression des échanges spontanés","Une exclusivité complète sur place"],"correct":"B","explanation":"Le passage indique : « Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. » Cela justifie la réponse : Une dimension sociale de la sortie."},{"number":21,"points":21,"passage":"Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique.","question":"Quelle est la portée de la consultation ?","options":["Elle supprime le travail de l'artiste","Elle concerne l'insertion de l'œuvre dans l'espace public","Elle fixe tous les gestes du sculpteur","Elle décide du prix des billets"],"correct":"B","explanation":"Le passage indique : « Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. » Cela justifie la réponse : Elle concerne l'insertion de l'œuvre dans l'espace public."},{"number":22,"points":21,"passage":"Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir.","question":"Quelle limite subsiste ?","options":["Un examen est obligatoire partout","Les ateliers ne disposent d'aucun enseignant","Les horaires peuvent encore exclure des participants","Aucun adulte ne souhaite apprendre"],"correct":"C","explanation":"Le passage indique : « Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. » Cela justifie la réponse : Les horaires peuvent encore exclure des participants."},{"number":23,"points":21,"passage":"Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle.","question":"Quel effet est décrit ?","options":["Un succès immédiat garanti","Un abandon de tous les petits éditeurs","La disparition des rencontres","La construction lente d'un lectorat"],"correct":"D","explanation":"Le passage indique : « Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. » Cela justifie la réponse : La construction lente d'un lectorat."},{"number":24,"points":21,"passage":"Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes.","question":"Pourquoi cette précision importe-t-elle ?","options":["Distinguer création artistique et fidélité documentaire","Remplacer tous les témoignages","Interdire toute interprétation","Garantir l'exactitude de chaque dialogue"],"correct":"A","explanation":"Le passage indique : « Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. » Cela justifie la réponse : Distinguer création artistique et fidélité documentaire."},{"number":25,"points":21,"passage":"Un théâtre réduit son décor pour diminuer les transports. La mise en scène utilise davantage la lumière et les mouvements. La sobriété matérielle devient un choix artistique autant qu'une contrainte logistique.","question":"Quelle conséquence dépasse la logistique ?","options":["L'abandon de toute création","L'évolution du langage scénique","La suppression de la mise en scène","L'obligation de jouer sans public"],"correct":"B","explanation":"Le passage indique : « Un théâtre réduit son décor pour diminuer les transports. La mise en scène utilise davantage la lumière et les mouvements. La sobriété matérielle devient un choix artistique autant qu'une contrainte logistique. » Cela justifie la réponse : L'évolution du langage scénique."},{"number":26,"points":21,"passage":"Une médiatrice recueille les impressions avant d'expliquer un tableau. Elle veut que les visiteurs osent regarder sans chercher immédiatement une interprétation autorisée.","question":"Quel comportement encourage-t-elle ?","options":["Identifier le prix de vente avant tout","Formuler une perception personnelle","Répéter d'abord une réponse officielle","Éviter toute observation"],"correct":"B","explanation":"Le passage indique : « Une médiatrice recueille les impressions avant d'expliquer un tableau. Elle veut que les visiteurs osent regarder sans chercher immédiatement une interprétation autorisée. » Cela justifie la réponse : Formuler une perception personnelle."},{"number":27,"points":21,"passage":"Une collection privée est accessible sur rendez-vous. Son propriétaire publie des images en ligne, mais certaines fragilités matérielles justifient de limiter les visites physiques.","question":"Pourquoi l'accès sur place est-il limité ?","options":["Pour réserver les images aux acheteurs","Pour supprimer toute consultation","Pour préserver les objets","Pour empêcher la recherche"],"correct":"C","explanation":"Le passage indique : « Une collection privée est accessible sur rendez-vous. Son propriétaire publie des images en ligne, mais certaines fragilités matérielles justifient de limiter les visites physiques. » Cela justifie la réponse : Pour préserver les objets."},{"number":28,"points":21,"passage":"Une maison d'édition publie simultanément un livre papier et une version audio. Les deux formats répondent à différents usages ; les éditeurs ne présentent pas l'un comme la disparition de l'autre.","question":"Quelle relation entre les formats est défendue ?","options":["Une hiérarchie juridique","Une opposition obligatoire","Une identité matérielle totale","Une complémentarité"],"correct":"D","explanation":"Le passage indique : « Une maison d'édition publie simultanément un livre papier et une version audio. Les deux formats répondent à différents usages ; les éditeurs ne présentent pas l'un comme la disparition de l'autre. » Cela justifie la réponse : Une complémentarité."},{"number":29,"points":21,"passage":"Un festival mesure aussi la satisfaction des bénévoles. Une organisation épuisante pourrait compromettre les éditions suivantes, même si le public actuel est nombreux.","question":"Pourquoi consulter les bénévoles ?","options":["Choisir les ventes de boissons uniquement","Calculer la météo future","Remplacer le public par les organisateurs","Évaluer la capacité à faire durer l'événement"],"correct":"D","explanation":"Le passage indique : « Un festival mesure aussi la satisfaction des bénévoles. Une organisation épuisante pourrait compromettre les éditions suivantes, même si le public actuel est nombreux. » Cela justifie la réponse : Évaluer la capacité à faire durer l'événement."},{"number":30,"points":26,"passage":"Un abonnement culturel donne accès à de nombreux lieux. Pourtant, les personnes qui ne connaissent pas les programmes l'utilisent peu. Un accompagnement à la découverte est ajouté : disposer d'un droit d'entrée ne suffit pas toujours à se sentir invité.","question":"Quelle idée est soulignée ?","options":["L'accès matériel doit parfois être accompagné","Les lieux n'ont plus besoin de communiquer","Les programmes doivent rester confidentiels","Un abonnement crée automatiquement des habitudes"],"correct":"A","explanation":"Le passage indique : « Un abonnement culturel donne accès à de nombreux lieux. Pourtant, les personnes qui ne connaissent pas les programmes l'utilisent peu. Un accompagnement à la découverte est ajouté : disposer d'un droit d'entrée ne suffit pas toujours à se sentir invité. » Cela justifie la réponse : L'accès matériel doit parfois être accompagné."},{"number":31,"points":26,"passage":"Les restaurateurs d'une fresque conservent des traces de transformations anciennes. Leur objectif n'est pas de fabriquer une surface paraissant neuve, mais de rendre l'œuvre lisible en respectant son histoire. La restauration suppose donc des choix, pas un simple effacement du temps.","question":"Quelle démarche adoptent-ils ?","options":["Préserver l'histoire matérielle de l'œuvre","Supprimer toutes les traces anciennes","Reproduire une peinture contemporaine","Remplacer la fresque par une photographie"],"correct":"A","explanation":"Le passage indique : « Les restaurateurs d'une fresque conservent des traces de transformations anciennes. Leur objectif n'est pas de fabriquer une surface paraissant neuve, mais de rendre l'œuvre lisible en respectant son histoire. La restauration suppose donc des choix, pas un simple effacement du temps. » Cela justifie la réponse : Préserver l'histoire matérielle de l'œuvre."},{"number":32,"points":26,"passage":"Un succès en ligne conduit un groupe à jouer dans une grande salle. Les musiciens découvrent que l'attention d'un public assis diffère des réactions fragmentées sur une plateforme. La notoriété numérique facilite la rencontre, mais ne dispense pas d'adapter le spectacle.","question":"Quelle nuance est apportée ?","options":["La scène interdit toute musique connue","La notoriété supprime le besoin de répétition","Le succès numérique ne prépare pas à tous les aspects de la scène","Un public en ligne est toujours identique au public présent"],"correct":"C","explanation":"Le passage indique : « Un succès en ligne conduit un groupe à jouer dans une grande salle. Les musiciens découvrent que l'attention d'un public assis diffère des réactions fragmentées sur une plateforme. La notoriété numérique facilite la rencontre, mais ne dispense pas d'adapter le spectacle. » Cela justifie la réponse : Le succès numérique ne prépare pas à tous les aspects de la scène."},{"number":33,"points":26,"passage":"Une exposition multiplie les écrans pour attirer les jeunes. Certains visiteurs apprécient l'interactivité ; d'autres regrettent de moins voir les objets. L'équipe réaménage des zones plus calmes. Elle ne renonce pas aux outils, mais cherche un équilibre entre médiation et présence des œuvres.","question":"Quelle solution est retenue ?","options":["Remplacer tous les objets par des vidéos","Rééquilibrer les dispositifs et l'observation directe","Supprimer toute information sur les œuvres","Écarter les visiteurs critiques"],"correct":"B","explanation":"Le passage indique : « Une exposition multiplie les écrans pour attirer les jeunes. Certains visiteurs apprécient l'interactivité ; d'autres regrettent de moins voir les objets. L'équipe réaménage des zones plus calmes. Elle ne renonce pas aux outils, mais cherche un équilibre entre médiation et présence des œuvres. » Cela justifie la réponse : Rééquilibrer les dispositifs et l'observation directe."},{"number":34,"points":26,"passage":"Une œuvre participative invite chacun à ajouter un fragment. L'artiste fixe cependant une règle commune afin que les contributions puissent dialoguer. Participer n'équivaut donc pas à agir sans cadre. La liberté s'exerce dans une structure qui rend la création collective possible.","question":"Quel rôle joue la règle ?","options":["Donner une cohérence à la participation","Transformer chaque participant en propriétaire exclusif","Supprimer les différences entre les fragments","Interdire toute contribution personnelle"],"correct":"A","explanation":"Le passage indique : « Une œuvre participative invite chacun à ajouter un fragment. L'artiste fixe cependant une règle commune afin que les contributions puissent dialoguer. Participer n'équivaut donc pas à agir sans cadre. La liberté s'exerce dans une structure qui rend la création collective possible. » Cela justifie la réponse : Donner une cohérence à la participation."},{"number":35,"points":26,"passage":"Les statistiques de fréquentation valorisent les grandes expositions. Un musée examine aussi les retours de petits groupes accompagnés sur plusieurs séances. Leur nombre est faible, mais leur relation aux œuvres devient plus approfondie. La quantité des entrées ne décrit pas à elle seule tous les effets culturels.","question":"Quelle approche d'évaluation est proposée ?","options":["Supprimer les données sur le public","Exclure les petits groupes du bilan","Associer fréquentation et qualité des expériences","Compter uniquement les billets les plus chers"],"correct":"C","explanation":"Le passage indique : « Les statistiques de fréquentation valorisent les grandes expositions. Un musée examine aussi les retours de petits groupes accompagnés sur plusieurs séances. Leur nombre est faible, mais leur relation aux œuvres devient plus approfondie. La quantité des entrées ne décrit pas à elle seule tous les effets culturels. » Cela justifie la réponse : Associer fréquentation et qualité des expériences."},{"number":36,"points":33,"passage":"Une ville souhaite transformer un atelier d'artistes en attraction permanente. Les créateurs apprécient l'intérêt du public, mais craignent de devoir montrer un travail immédiatement compréhensible à toute heure. Certaines recherches exigent des essais sans résultat présentable. Rendre la création visible ne doit pas obliger à confondre le temps de recherche et celui de la représentation.","question":"Quel risque les artistes identifient-ils ?","options":["La pression à présenter sans cesse un résultat","L'absence de toute possibilité de rencontre","La disparition de toute curiosité du public","L'obligation de quitter la ville dès l'ouverture"],"correct":"A","explanation":"Le passage indique : « Rendre la création visible ne doit pas obliger à confondre le temps de recherche et celui de la représentation. » Cela justifie la réponse : La pression à présenter sans cesse un résultat."},{"number":37,"points":33,"passage":"Un documentaire donne la parole à des habitants longtemps absents des médias. Le réalisateur refuse pourtant de présenter ces voix comme un groupe parfaitement homogène. Les désaccords font partie de leur expérience commune. Accorder une visibilité ne consiste pas à fabriquer une parole unique qui effacerait les différences internes.","question":"Quel principe de représentation défend-il ?","options":["Éliminer tous les désaccords au montage","Choisir uniquement les récits identiques","Présenter chaque habitant comme un adversaire","Montrer aussi la diversité au sein du groupe"],"correct":"D","explanation":"Le passage indique : « Accorder une visibilité ne consiste pas à fabriquer une parole unique qui effacerait les différences internes. » Cela justifie la réponse : Montrer aussi la diversité au sein du groupe."},{"number":38,"points":33,"passage":"Une plateforme recommande des livres proches de ceux déjà lus. Ce service aide à choisir, mais peut réduire les découvertes inattendues. Une libraire propose à ses clients un titre éloigné de leurs habitudes, en expliquant le lien possible avec leurs intérêts. Découvrir ne suppose pas forcément l'absence de repères, mais parfois un déplacement accompagné de ces repères.","question":"Quelle conception de la découverte est proposée ?","options":["Choisir sans tenir compte du lecteur","Ouvrir les habitudes grâce à une médiation","Interdire toute recommandation technique","Répéter uniquement les lectures déjà appréciées"],"correct":"B","explanation":"Le passage indique : « Découvrir ne suppose pas forcément l'absence de repères, mais parfois un déplacement accompagné de ces repères. » Cela justifie la réponse : Ouvrir les habitudes grâce à une médiation."},{"number":39,"points":33,"passage":"On associe parfois un grand nombre de visiteurs à la réussite d'un lieu culturel. Dans une petite salle, l'augmentation des entrées a réduit le temps d'échange et rendu certaines personnes moins à l'aise. L'équipe choisit des groupes plus petits malgré une baisse du chiffre annoncé. Le succès dépend ici de la relation rendue possible, et non de la seule capacité à remplir la salle.","question":"Quel arbitrage est assumé ?","options":["Réserver toutes les visites aux artistes","Abandonner les rencontres avec les visiteurs","Privilégier la qualité d'accueil sur le volume des entrées","Mesurer la réussite uniquement par le remplissage"],"correct":"C","explanation":"Le passage indique : « Le succès dépend ici de la relation rendue possible, et non de la seule capacité à remplir la salle. » Cela justifie la réponse : Privilégier la qualité d'accueil sur le volume des entrées."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-07','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-07","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 07","topic":"Manger, produire et partager","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord.","question":"Quel service reste disponible après la fermeture ?","options":["L'ouverture de la poissonnerie","Le retrait de commandes payées","La livraison sans commande","L'achat libre sur tous les stands"],"correct":"B","explanation":"Le passage indique : « Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord. » Cela justifie la réponse : Le retrait de commandes payées."},{"number":2,"points":3,"passage":"Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies.","question":"Que doit apporter le participant ?","options":["De la levure","De la farine","Un saladier","Un four"],"correct":"C","explanation":"Le passage indique : « Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies. » Cela justifie la réponse : Un saladier."},{"number":3,"points":3,"passage":"Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté.","question":"Quelle condition faut-il respecter ?","options":["Utiliser un contenant propre","Apporter un sac en papier","Acheter uniquement en espèces","Réserver une semaine avant"],"correct":"A","explanation":"Le passage indique : « Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté. » Cela justifie la réponse : Utiliser un contenant propre."},{"number":4,"points":3,"passage":"Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée.","question":"Quand faut-il signaler ce choix ?","options":["À l'entrée de la salle","Le lendemain du repas","Après le dessert","Au moment de l'inscription"],"correct":"D","explanation":"Le passage indique : « Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée. » Cela justifie la réponse : Au moment de l'inscription."},{"number":5,"points":9,"passage":"J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud.","question":"Qu'est-ce qui change dans le programme ?","options":["La personne préparant la salade","Le nombre d'invités","Le jour du rendez-vous","Le lieu du repas"],"correct":"D","explanation":"Le passage indique : « J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud. » Cela justifie la réponse : Le lieu du repas."},{"number":6,"points":9,"passage":"Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait.","question":"Quelle aide accompagne le panier ?","options":["Un restaurant réservé aux adhérents","Un cours obligatoire de jardinage","Des conseils pour préparer les légumes","Un remboursement de tous les achats"],"correct":"C","explanation":"Le passage indique : « Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait. » Cela justifie la réponse : Des conseils pour préparer les légumes."},{"number":7,"points":9,"passage":"Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur.","question":"Que garantit une réservation ?","options":["Une place en terrasse","Un repas gratuit","Une table en salle","Une heure de départ libre"],"correct":"C","explanation":"Le passage indique : « Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur. » Cela justifie la réponse : Une table en salle."},{"number":8,"points":9,"passage":"Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert.","question":"Pourquoi choisir ce format ?","options":["Prévoir deux desserts par personne","Adapter la quantité aux personnes qui en mangeront","Conserver tout le gâteau pour le lendemain","Réduire le nombre d'invités"],"correct":"B","explanation":"Le passage indique : « Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert. » Cela justifie la réponse : Adapter la quantité aux personnes qui en mangeront."},{"number":9,"points":9,"passage":"La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants.","question":"Quelle obligation est absente ?","options":["Acheter une huile","Respecter l'heure du rendez-vous","S'inscrire à la dégustation","Goûter dans le lieu prévu"],"correct":"A","explanation":"Le passage indique : « La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants. » Cela justifie la réponse : Acheter une huile."},{"number":10,"points":9,"passage":"Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés.","question":"Pourquoi certains dépôts sont-ils exclus ?","options":["Pour réserver les aliments aux commerçants","Pour interdire les dons gratuits","Pour privilégier les emballages décoratifs","Pour disposer d'informations vérifiables sur les produits"],"correct":"D","explanation":"Le passage indique : « Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés. » Cela justifie la réponse : Pour disposer d'informations vérifiables sur les produits."},{"number":11,"points":15,"passage":"Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis.","question":"Quelle caractéristique faut-il accepter ?","options":["Un choix toujours identique","La variation saisonnière du panier","Une livraison quotidienne obligatoire","L'absence de légumes locaux"],"correct":"B","explanation":"Le passage indique : « Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis. » Cela justifie la réponse : La variation saisonnière du panier."},{"number":12,"points":15,"passage":"Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion.","question":"Quelle approche est choisie ?","options":["Une découverte progressive","Un changement de menu quotidien imposé","Une consommation forcée","La suppression de tout choix"],"correct":"A","explanation":"Le passage indique : « Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion. » Cela justifie la réponse : Une découverte progressive."},{"number":13,"points":15,"passage":"Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance.","question":"Que nécessite cette méthode ?","options":["Une attention continue à la préparation","Le remplacement de la farine par de l'eau","L'absence de toute organisation","L'arrêt définitif des fournées"],"correct":"A","explanation":"Le passage indique : « Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance. » Cela justifie la réponse : Une attention continue à la préparation."},{"number":14,"points":15,"passage":"Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage.","question":"Quelle règle rend le partage possible ?","options":["L'accès sans limite aux stocks des autres","La fermeture aux nouveaux producteurs","Le respect des créneaux et du nettoyage","La préparation simultanée sans réservation"],"correct":"C","explanation":"Le passage indique : « Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage. » Cela justifie la réponse : Le respect des créneaux et du nettoyage."},{"number":15,"points":15,"passage":"Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer.","question":"Pourquoi un échange reste-t-il nécessaire ?","options":["Les ingrédients peuvent changer","La cuisine refuse toute question","Les allergies disparaissent au restaurant","Les indications sont volontairement fausses"],"correct":"A","explanation":"Le passage indique : « Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer. » Cela justifie la réponse : Les ingrédients peuvent changer."},{"number":16,"points":15,"passage":"Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie.","question":"Quel apprentissage est visé ?","options":["Éviter toute dégustation","Mémoriser le prix des serres","Reconnaître une diversité au sein d'un aliment","Choisir uniquement la plus grosse tomate"],"correct":"C","explanation":"Le passage indique : « Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie. » Cela justifie la réponse : Reconnaître une diversité au sein d'un aliment."},{"number":17,"points":15,"passage":"Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard.","question":"Quel problème cette activité aide-t-elle à résoudre ?","options":["L'absence totale de matières premières","Le besoin d'importer tous les légumes","La perte de récoltes difficiles à écouler immédiatement","Le manque de magasins d'électroménager"],"correct":"C","explanation":"Le passage indique : « Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard. » Cela justifie la réponse : La perte de récoltes difficiles à écouler immédiatement."},{"number":18,"points":15,"passage":"Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante.","question":"Quelle précaution accompagne l'économie ?","options":["Masquer l'origine des produits","Utiliser tous les restes sans distinction","Supprimer les réfrigérateurs","Vérifier la sécurité des aliments"],"correct":"D","explanation":"Le passage indique : « Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante. » Cela justifie la réponse : Vérifier la sécurité des aliments."},{"number":19,"points":15,"passage":"Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services.","question":"Quel objectif guide ce changement ?","options":["Augmenter les pertes en cuisine","Supprimer tous les produits frais","Fermer plusieurs jours par semaine","Simplifier la gestion des approvisionnements"],"correct":"D","explanation":"Le passage indique : « Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services. » Cela justifie la réponse : Simplifier la gestion des approvisionnements."},{"number":20,"points":21,"passage":"Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché.","question":"Quel compromis est décrit ?","options":["Plus de prévisibilité contre moins de choix instantané","Un prix changeant après chaque livraison","Une suppression de toute relation avec les fermes","Des commandes sans engagement pour les producteurs"],"correct":"A","explanation":"Le passage indique : « Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. » Cela justifie la réponse : Plus de prévisibilité contre moins de choix instantané."},{"number":21,"points":21,"passage":"Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin.","question":"Quelle conséquence le choix local a-t-il ?","options":["Les mêmes produits restent disponibles partout","Le menu suit davantage les saisons","Les clients doivent apporter tous leurs légumes","Le service devient uniquement estival"],"correct":"B","explanation":"Le passage indique : « Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. » Cela justifie la réponse : Le menu suit davantage les saisons."},{"number":22,"points":21,"passage":"Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants.","question":"Que suggère cette observation ?","options":["L'aménagement pratique influence les usages","Les enfants refusent tous les verres","La fontaine est inutile","L'eau doit être payante pour être bue"],"correct":"A","explanation":"Le passage indique : « Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. » Cela justifie la réponse : L'aménagement pratique influence les usages."},{"number":23,"points":21,"passage":"Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible.","question":"Quelle idée la visite aide-t-elle à comprendre ?","options":["L'indépendance complète vis-à-vis du climat","Une quantité identique garantie chaque jour","La disparition du besoin de travail","L'incertitude inhérente à certaines productions"],"correct":"D","explanation":"Le passage indique : « Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. » Cela justifie la réponse : L'incertitude inhérente à certaines productions."},{"number":24,"points":21,"passage":"Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux.","question":"Pourquoi ce choix de matériel ?","options":["Démontrer l'inutilité de tous les outils","Réserver l'activité aux professionnels","Faciliter le réemploi des apprentissages à domicile","Augmenter le coût des recettes"],"correct":"C","explanation":"Le passage indique : « Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. » Cela justifie la réponse : Faciliter le réemploi des apprentissages à domicile."},{"number":25,"points":21,"passage":"Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique.","question":"Que permet l'affichage ?","options":["Mesurer la qualité gustative","Garantir que tout grand format est moins cher","Remplacer la liste des ingrédients","Comparer les prix sur une même base"],"correct":"D","explanation":"Le passage indique : « Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique. » Cela justifie la réponse : Comparer les prix sur une même base."},{"number":26,"points":21,"passage":"Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats.","question":"Quel lien organise cette pratique ?","options":["Imposer le même menu toute l'année","Relier la quantité préparée aux besoins réels","Commander sans connaître le nombre d'invités","Supprimer les achats de dernière minute pour les clients seulement"],"correct":"B","explanation":"Le passage indique : « Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats. » Cela justifie la réponse : Relier la quantité préparée aux besoins réels."},{"number":27,"points":21,"passage":"Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres.","question":"Quelle conception de la transmission apparaît ?","options":["Seules les recettes écrites sont valables","Chaque plat doit avoir une forme identique partout","Une tradition peut comporter plusieurs variantes","Les recettes familiales ne changent jamais"],"correct":"C","explanation":"Le passage indique : « Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres. » Cela justifie la réponse : Une tradition peut comporter plusieurs variantes."},{"number":28,"points":21,"passage":"Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes.","question":"Que révèle cette distinction ?","options":["Tous les repas rapides sont librement choisis","Les conditions de travail influencent les pratiques alimentaires","Le goût n'a jamais d'importance","Les salariés disposent tous du même temps"],"correct":"B","explanation":"Le passage indique : « Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes. » Cela justifie la réponse : Les conditions de travail influencent les pratiques alimentaires."},{"number":29,"points":21,"passage":"Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long.","question":"Quelle fonction remplit ce stand ?","options":["Garantir des ventes identiques","Offrir une période d'essai commercial","Remplacer le travail agricole par une formation","Éliminer les producteurs établis"],"correct":"B","explanation":"Le passage indique : « Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long. » Cela justifie la réponse : Offrir une période d'essai commercial."},{"number":30,"points":26,"passage":"L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention.","question":"Quelle limite d'interprétation est signalée ?","options":["Une mention ne renseigne pas sur toutes les dimensions du repas","Une étiquette remplace l'observation du menu","L'origine des aliments est toujours secrète","Toute préparation maison est identique"],"correct":"A","explanation":"Le passage indique : « L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention. » Cela justifie la réponse : Une mention ne renseigne pas sur toutes les dimensions du repas."},{"number":31,"points":26,"passage":"Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché.","question":"Quelle attitude le texte recommande-t-il ?","options":["Considérer le prix comme une preuve unique de qualité","Examiner les mécanismes derrière le prix","Condamner tous les prix bas de la même manière","Ignorer les conditions de production"],"correct":"B","explanation":"Le passage indique : « Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché. » Cela justifie la réponse : Examiner les mécanismes derrière le prix."},{"number":32,"points":26,"passage":"Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent.","question":"Quelle idée est défendue ?","options":["La transmission cesse dès qu'une famille déménage","Toute modification détruit obligatoirement l'héritage","Une recette doit ignorer les produits disponibles","L'adaptation peut faire vivre une tradition"],"correct":"D","explanation":"Le passage indique : « Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent. » Cela justifie la réponse : L'adaptation peut faire vivre une tradition."},{"number":33,"points":26,"passage":"Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes.","question":"Pourquoi organiser des dégustations ?","options":["Supprimer toutes les habitudes alimentaires","Éviter de présenter les plats nouveaux","Imposer un résultat sans échange","Éclairer les préférences avant de les mesurer"],"correct":"D","explanation":"Le passage indique : « Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes. » Cela justifie la réponse : Éclairer les préférences avant de les mesurer."},{"number":34,"points":26,"passage":"Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent.","question":"Quelle condition rend le changement viable ?","options":["L'indifférence aux besoins des restaurants","La multiplication des trajets individuels","L'adaptation coordonnée des partenaires","La suppression des réserves alimentaires"],"correct":"C","explanation":"Le passage indique : « Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent. » Cela justifie la réponse : L'adaptation coordonnée des partenaires."},{"number":35,"points":26,"passage":"La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus.","question":"Quelle priorité est proposée ?","options":["Prévenir la formation des surplus","Produire plus de restes pour mieux les recycler","Abandonner les prévisions de repas","Considérer tout surplus comme inévitable"],"correct":"A","explanation":"Le passage indique : « La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus. » Cela justifie la réponse : Prévenir la formation des surplus."},{"number":36,"points":33,"passage":"Un service de paniers « personnalisés » promet de répondre à chaque préférence. Pour y parvenir, il multiplie les petites commandes et les emballages séparés. Les clients gagnent en choix, mais le système perd une partie de l'efficacité du panier commun. La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible.","question":"Quel arbitrage est mis en évidence ?","options":["Une commande personnalisée réduit toujours les emballages","Les préférences n'ont aucun effet sur l'approvisionnement","Les paniers communs interdisent toute alimentation variée","Choix individuel et efficacité collective peuvent entrer en tension"],"correct":"D","explanation":"Le passage indique : « La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible. » Cela justifie la réponse : Choix individuel et efficacité collective peuvent entrer en tension."},{"number":37,"points":33,"passage":"Un restaurant annonce une cuisine locale. Son menu comporte surtout des produits de proximité, mais certains ingrédients complémentaires viennent d'ailleurs. Le chef publie ces exceptions et leurs raisons. La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait.","question":"Quelle démarche le chef privilégie-t-il ?","options":["Supprimer toute information sur les fournisseurs","Rendre son engagement précis et vérifiable","Prétendre que tous les produits sont locaux","Cacher les ingrédients qui viennent de loin"],"correct":"B","explanation":"Le passage indique : « La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait. » Cela justifie la réponse : Rendre son engagement précis et vérifiable."},{"number":38,"points":33,"passage":"Une ville distribue des brochures pour encourager une alimentation variée. Une enquête montre cependant que plusieurs ménages disposent d'un équipement de cuisson limité et de peu de commerces accessibles. La connaissance des recommandations n'est pas leur principale difficulté. Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre.","question":"Quelle limite de la campagne est soulignée ?","options":["L'accès aux commerces n'influence pas l'alimentation","L'information ne résout pas les obstacles matériels","Les ménages refusent nécessairement toute diversité","Une brochure crée automatiquement une cuisine équipée"],"correct":"B","explanation":"Le passage indique : « Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre. » Cela justifie la réponse : L'information ne résout pas les obstacles matériels."},{"number":39,"points":33,"passage":"Une ferme propose aux clients de partager les risques d'une saison en payant un panier à l'avance. Certains craignent de recevoir moins lors d'une mauvaise récolte. Le producteur explique que le contrat n'est pas une garantie de volume identique, mais une relation différente avec l'activité agricole. Le prix finance aussi une continuité de production confrontée à l'incertitude.","question":"Qu'est-ce qui distingue ce contrat d'un achat ordinaire ?","options":["Un engagement qui prend en compte le risque de production","Une absence de relation avec la ferme","Une obligation d'acheter chaque produit séparément","Une promesse de quantité constante sans aléa"],"correct":"A","explanation":"Le passage indique : « Le prix finance aussi une continuité de production confrontée à l'incertitude. » Cela justifie la réponse : Un engagement qui prend en compte le risque de production."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-08','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-08","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 08","topic":"Santé, sport et équilibre quotidien","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires.","question":"Jusqu'à quand peut-on se changer ?","options":["Dix-neuf heures trente","Dix-neuf heures quinze","Dix-huit heures quarante-cinq","Vingt heures"],"correct":"B","explanation":"Le passage indique : « La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires. » Cela justifie la réponse : Dix-neuf heures quinze."},{"number":2,"points":3,"passage":"Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin.","question":"Quel matériel est demandé ?","options":["Un ballon","Un tapis","Une chaise","Un casque"],"correct":"B","explanation":"Le passage indique : « Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin. » Cela justifie la réponse : Un tapis."},{"number":3,"points":3,"passage":"L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale.","question":"Qui peut venir mardi matin ?","options":["Uniquement les livreurs","Les visiteurs sans motif","Les patients ayant rendez-vous","Toute personne souhaitant s'inscrire"],"correct":"C","explanation":"Le passage indique : « L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale. » Cela justifie la réponse : Les patients ayant rendez-vous."},{"number":4,"points":3,"passage":"Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé.","question":"Que conseille l'annonce ?","options":["Une sortie sans chaussures","Une course plus rapide","L'accès au parcours glissant","Un itinéraire alternatif"],"correct":"D","explanation":"Le passage indique : « Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé. » Cela justifie la réponse : Un itinéraire alternatif."},{"number":5,"points":9,"passage":"Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie.","question":"Quel parcours est souhaité ?","options":["Une route inconnue de nuit","Une compétition chronométrée","Une ascension difficile","Un trajet sans montée importante"],"correct":"D","explanation":"Le passage indique : « Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie. » Cela justifie la réponse : Un trajet sans montée importante."},{"number":6,"points":9,"passage":"Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas.","question":"Que faire en cas d'indisponibilité ?","options":["Contacter le secrétariat","Venir sans prévenir un autre jour","Annuler tous les soins","Demander à un voisin de consulter"],"correct":"A","explanation":"Le passage indique : « Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas. » Cela justifie la réponse : Contacter le secrétariat."},{"number":7,"points":9,"passage":"L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité.","question":"Quel est l'intérêt du prêt ?","options":["Recevoir un équipement définitif","Essayer avant de s'équiper","Participer sans jamais s'inscrire","Éviter toute séance encadrée"],"correct":"B","explanation":"Le passage indique : « L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité. » Cela justifie la réponse : Essayer avant de s'équiper."},{"number":8,"points":9,"passage":"Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer.","question":"Quelle adaptation est prévue ?","options":["Un départ sans accompagnateur","Des arrêts plus fréquents","Une distance doublée","La suppression des boissons"],"correct":"B","explanation":"Le passage indique : « Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer. » Cela justifie la réponse : Des arrêts plus fréquents."},{"number":9,"points":9,"passage":"La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire.","question":"À qui s'adresse la séance ?","options":["Aux enfants accompagnés","Aux adultes qui apprennent","Aux nageurs en compétition seulement","Aux entraîneurs professionnels"],"correct":"B","explanation":"Le passage indique : « La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire. » Cela justifie la réponse : Aux adultes qui apprennent."},{"number":10,"points":9,"passage":"Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille.","question":"Qu'est-ce qui motive ce changement ?","options":["Un projet de compétition","Un déménagement en montagne","Une interdiction de courir","Une meilleure organisation du quotidien"],"correct":"D","explanation":"Le passage indique : « Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille. » Cela justifie la réponse : Une meilleure organisation du quotidien."},{"number":11,"points":15,"passage":"Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin.","question":"Quelle place est donnée à la performance ?","options":["Elle n'est pas l'objectif principal","Elle exclut les nouveaux membres","Elle détermine le droit d'entrer","Elle impose un temps identique"],"correct":"A","explanation":"Le passage indique : « Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin. » Cela justifie la réponse : Elle n'est pas l'objectif principal."},{"number":12,"points":15,"passage":"Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel.","question":"Quelle limite est précisée ?","options":["L'atelier ne remplace pas un suivi individuel","Les animateurs prescrivent systématiquement un traitement","Aucune question ne peut être posée","Les participants reçoivent tous un diagnostic"],"correct":"A","explanation":"Le passage indique : « Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel. » Cela justifie la réponse : L'atelier ne remplace pas un suivi individuel."},{"number":13,"points":15,"passage":"Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement.","question":"Quel objectif poursuit l'aménagement ?","options":["Permettre différentes capacités de participation","Supprimer les explications","Réserver le parc aux spécialistes","Imposer une difficulté unique"],"correct":"A","explanation":"Le passage indique : « Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement. » Cela justifie la réponse : Permettre différentes capacités de participation."},{"number":14,"points":15,"passage":"Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse.","question":"Pourquoi ce groupe est-il créé ?","options":["Pour imposer un classement plus strict","Pour limiter l'accès aux nouveaux venus","Pour remplacer toutes les sorties","Pour diversifier les façons de pratiquer"],"correct":"D","explanation":"Le passage indique : « Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse. » Cela justifie la réponse : Pour diversifier les façons de pratiquer."},{"number":15,"points":15,"passage":"Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau.","question":"Quel obstacle cherche-t-on à réduire ?","options":["L'existence d'un accueil","La diversité des horaires","La dépendance aux outils numériques","Le besoin d'un rendez-vous"],"correct":"C","explanation":"Le passage indique : « Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau. » Cela justifie la réponse : La dépendance aux outils numériques."},{"number":16,"points":15,"passage":"Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement.","question":"Quelle approche est adoptée ?","options":["Remplacer tous les meubles par des écrans","Agir sur l'organisation et les pauses","Exiger l'immobilité toute la journée","Supprimer les changements de tâche"],"correct":"B","explanation":"Le passage indique : « Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement. » Cela justifie la réponse : Agir sur l'organisation et les pauses."},{"number":17,"points":15,"passage":"Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours.","question":"Pourquoi recueillir ces sensations ?","options":["Comparer uniquement les chaussures","Mieux comprendre l'effort réellement ressenti","Remplacer tout mouvement par un questionnaire","Garantir des progrès identiques"],"correct":"B","explanation":"Le passage indique : « Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours. » Cela justifie la réponse : Mieux comprendre l'effort réellement ressenti."},{"number":18,"points":15,"passage":"Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie.","question":"Quel principe est appliqué ?","options":["Une participation obligatoirement gratuite","Une réservation réservée aux donateurs","Une portion proportionnelle au paiement","Un accueil indépendant de la contribution financière"],"correct":"D","explanation":"Le passage indique : « Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie. » Cela justifie la réponse : Un accueil indépendant de la contribution financière."},{"number":19,"points":15,"passage":"Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule.","question":"À quoi sert cet espace ?","options":["Distribuer les dossards avant le départ","Remplacer les vestiaires","Faciliter la récupération dans un environnement apaisé","Organiser une seconde course"],"correct":"C","explanation":"Le passage indique : « Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule. » Cela justifie la réponse : Faciliter la récupération dans un environnement apaisé."},{"number":20,"points":21,"passage":"Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres.","question":"Quelle priorité est donnée ?","options":["Remplacer tous les déplacements quotidiens","Sélectionner les marcheurs les plus rapides","Soutenir une pratique régulière et partagée","Atteindre une distance maximale"],"correct":"C","explanation":"Le passage indique : « Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. » Cela justifie la réponse : Soutenir une pratique régulière et partagée."},{"number":21,"points":21,"passage":"Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport.","question":"Quelle limite est reconnue ?","options":["Aucune donnée n'a été recueillie","Les réponses concernent uniquement les enfants","Le profil des participants peut influencer les résultats","Les clubs refusent toute enquête"],"correct":"C","explanation":"Le passage indique : « Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. » Cela justifie la réponse : Le profil des participants peut influencer les résultats."},{"number":22,"points":21,"passage":"Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées.","question":"Pourquoi poursuivre la consultation ?","options":["Confirmer que chacun l'utilise déjà","Comprendre les obstacles à une participation plus large","Supprimer toutes les activités gratuites","Fermer le terrain aux usagers actuels"],"correct":"B","explanation":"Le passage indique : « Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. » Cela justifie la réponse : Comprendre les obstacles à une participation plus large."},{"number":23,"points":21,"passage":"Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel.","question":"Quelle séparation souhaitent-ils préserver ?","options":["Celle entre débutants et entraîneurs uniquement","Celle entre les jours ouvrés et les congés scolaires","Celle entre deux vestiaires","Celle entre activité personnelle et évaluation au travail"],"correct":"D","explanation":"Le passage indique : « Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. » Cela justifie la réponse : Celle entre activité personnelle et évaluation au travail."},{"number":24,"points":21,"passage":"Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil.","question":"Quel besoin reste présent ?","options":["Une augmentation des obstacles matériels","Un classement plus précis","Un accompagnement humain","Une fermeture des inscriptions"],"correct":"C","explanation":"Le passage indique : « Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. » Cela justifie la réponse : Un accompagnement humain."},{"number":25,"points":21,"passage":"Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin.","question":"Comment la mesure sera-t-elle évaluée ?","options":["Par l'observation de son usage et de ses effets","Sans aucune information des patients","Par le nombre d'affiches imprimées","Uniquement par l'annonce de nouveaux horaires"],"correct":"A","explanation":"Le passage indique : « Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin. » Cela justifie la réponse : Par l'observation de son usage et de ses effets."},{"number":26,"points":21,"passage":"Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire.","question":"Que montrent ces réactions ?","options":["Un même outil peut avoir des effets différents","La pratique exige des messages permanents","Les rappels plaisent nécessairement à tous","Tous les utilisateurs abandonnent le sport"],"correct":"A","explanation":"Le passage indique : « Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire. » Cela justifie la réponse : Un même outil peut avoir des effets différents."},{"number":27,"points":21,"passage":"Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre.","question":"Quel principe applique-t-il ?","options":["Éviter toute information générale","Réserver la réunion aux professionnels","Protéger les informations individuelles","Transformer les dossiers en exemples publics"],"correct":"C","explanation":"Le passage indique : « Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre. » Cela justifie la réponse : Protéger les informations individuelles."},{"number":28,"points":21,"passage":"Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux.","question":"Quelle limite de l'ouverture apparaît ?","options":["Tous les habitants possèdent une voiture","Les horaires du gymnase n'ont pas changé","L'accès dépend aussi des transports","Le bus circule plus longtemps que le gymnase"],"correct":"C","explanation":"Le passage indique : « Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux. » Cela justifie la réponse : L'accès dépend aussi des transports."},{"number":29,"points":21,"passage":"Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre.","question":"Quel changement de perspective adopte-t-elle ?","options":["Considérer plusieurs dimensions du bien-être","Imposer un résultat identique à tous","Mesurer uniquement la taille des vêtements","Abandonner toute discussion sur les pratiques"],"correct":"A","explanation":"Le passage indique : « Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre. » Cela justifie la réponse : Considérer plusieurs dimensions du bien-être."},{"number":30,"points":26,"passage":"Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté.","question":"Quelle explication simpliste est contestée ?","options":["L'utilité d'activités accessibles","Le manque de motivation comme cause unique","L'influence possible des horaires","La diversité des situations familiales"],"correct":"B","explanation":"Le passage indique : « Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté. » Cela justifie la réponse : Le manque de motivation comme cause unique."},{"number":31,"points":26,"passage":"Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts.","question":"Quel indicateur complémentaire est proposé ?","options":["La couleur des cartes d'accès","Le nombre de casiers installés","La surface du parking uniquement","La continuité de la participation"],"correct":"D","explanation":"Le passage indique : « Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts. » Cela justifie la réponse : La continuité de la participation."},{"number":32,"points":26,"passage":"Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice.","question":"Quelle distinction est faite ?","options":["La régularité empêche les progrès","La publicité remplace un usage réel","Tout équipement est inutile","Posséder un objet ne garantit pas l'effet annoncé"],"correct":"D","explanation":"Le passage indique : « Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice. » Cela justifie la réponse : Posséder un objet ne garantit pas l'effet annoncé."},{"number":33,"points":26,"passage":"Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés.","question":"Quelle approche est mise en valeur ?","options":["Remplacer tous les chemins par des salles","Agir sur l'environnement des déplacements courants","Réserver la marche aux clubs","Exiger une inscription pour se déplacer"],"correct":"B","explanation":"Le passage indique : « Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés. » Cela justifie la réponse : Agir sur l'environnement des déplacements courants."},{"number":34,"points":26,"passage":"Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion.","question":"Quelle règle favorise la continuité à long terme ?","options":["Exclure dès la première absence","Imposer un résultat uniforme","Permettre le retour après une interruption","Supprimer tout accompagnement"],"correct":"C","explanation":"Le passage indique : « Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion. » Cela justifie la réponse : Permettre le retour après une interruption."},{"number":35,"points":26,"passage":"Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes.","question":"Pourquoi ajouter des échanges ?","options":["Comprendre ce que l'indicateur général ne détaille pas","Transformer chaque réponse en diagnostic individuel","Effacer toutes les réponses recueillies","Éviter d'écouter les salariés"],"correct":"A","explanation":"Le passage indique : « Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes. » Cela justifie la réponse : Comprendre ce que l'indicateur général ne détaille pas."},{"number":36,"points":33,"passage":"Un club veut rendre ses activités accessibles à tous en réduisant les cotisations. Les demandes augmentent, mais des personnes restent absentes : certaines n'osent pas venir seules, d'autres ne se reconnaissent pas dans les images utilisées. L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante.","question":"Quelle conclusion se dégage ?","options":["L'accessibilité comporte aussi des dimensions sociales","La baisse des prix ne peut jamais être utile","L'absence de nouveaux membres prouve une hausse des tarifs","Tout problème disparaît avec une inscription gratuite"],"correct":"A","explanation":"Le passage indique : « L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante. » Cela justifie la réponse : L'accessibilité comporte aussi des dimensions sociales."},{"number":37,"points":33,"passage":"Les outils de suivi comptent facilement les pas ou les minutes d'exercice. Ils décrivent moins bien le plaisir, la fatigue ou la confiance retrouvée. Un animateur utilise les chiffres comme point de discussion, sans en faire la définition complète du progrès. Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne.","question":"Quelle place donne-t-il aux données ?","options":["Un repère à interpréter dans une expérience plus large","Une obligation identique pour chaque participant","Une description exhaustive du bien-être","Un résultat qu'il faut ignorer systématiquement"],"correct":"A","explanation":"Le passage indique : « Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne. » Cela justifie la réponse : Un repère à interpréter dans une expérience plus large."},{"number":38,"points":33,"passage":"Une ville installe des équipements sportifs dans un parc. Les services observent des usages imprévus : certains habitants s'y retrouvent pour discuter et font quelques mouvements ensemble. Plutôt que restreindre cet usage, ils ajoutent des bancs. Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés.","question":"Comment la ville réagit-elle ?","options":["Elle exige une pratique chronométrée","Elle retire immédiatement les appareils","Elle interdit toutes les conversations","Elle adapte le lieu aux usages réellement observés"],"correct":"D","explanation":"Le passage indique : « Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés. » Cela justifie la réponse : Elle adapte le lieu aux usages réellement observés."},{"number":39,"points":33,"passage":"Une organisation souhaite prévenir l'épuisement professionnel en proposant des séances de relaxation. Les salariés apprécient l'offre, mais demandent aussi de revoir une répartition de tâches devenue irréaliste. Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté.","question":"Quelle complémentarité défendent-ils ?","options":["Supprimer les aides déjà proposées","Attribuer les difficultés aux salariés seulement","Associer soutien personnel et changements organisationnels","Remplacer toute discussion du travail par la relaxation"],"correct":"C","explanation":"Le passage indique : « Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté. » Cela justifie la réponse : Associer soutien personnel et changements organisationnels."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-09','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-09","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 09","topic":"Sciences, recherche et inventions","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures.","question":"Quelle solution est proposée ?","options":["Acheter un billet obligatoire","Assister à la séance de quinze heures","Revenir uniquement le mois prochain","Visiter gratuitement une autre ville"],"correct":"B","explanation":"Le passage indique : « Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures. » Cela justifie la réponse : Assister à la séance de quinze heures."},{"number":2,"points":3,"passage":"L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais.","question":"Quel objet faut-il apporter ?","options":["Un carnet","Un tournevis","Une perceuse","Un robot terminé"],"correct":"A","explanation":"Le passage indique : « L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais. » Cela justifie la réponse : Un carnet."},{"number":3,"points":3,"passage":"Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau.","question":"Qui peut venir samedi ?","options":["Uniquement les chercheurs","Des enfants accompagnés et inscrits","Des classes sans réservation","Des mineurs obligatoirement seuls"],"correct":"B","explanation":"Le passage indique : « Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau. » Cela justifie la réponse : Des enfants accompagnés et inscrits."},{"number":4,"points":3,"passage":"L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante.","question":"Que se passe-t-il en cas de nuages ?","options":["Tout le matériel est vendu","L'horaire est reporté d'un an","Les participants montent seuls sur le toit","L'activité se poursuit à l'intérieur"],"correct":"D","explanation":"Le passage indique : « L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante. » Cela justifie la réponse : L'activité se poursuit à l'intérieur."},{"number":5,"points":9,"passage":"Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles.","question":"Pourquoi l'envoi est-il différé ?","options":["Pour supprimer tous les résultats","Pour attendre un financement","Pour contrôler la fiabilité de l'instrument","Pour changer le sujet du projet"],"correct":"C","explanation":"Le passage indique : « Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles. » Cela justifie la réponse : Pour contrôler la fiabilité de l'instrument."},{"number":6,"points":9,"passage":"Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles.","question":"Quel équipement personnel est obligatoire ?","options":["Une caméra professionnelle","Une antenne radio","Aucun télescope n'est exigé","Un grand télescope"],"correct":"C","explanation":"Le passage indique : « Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles. » Cela justifie la réponse : Aucun télescope n'est exigé."},{"number":7,"points":9,"passage":"Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles.","question":"Quelle caractéristique du local est recherchée ?","options":["Une faible lumière extérieure","Un accès réservé aux vendeurs","Une exposition maximale au soleil","Une température tropicale"],"correct":"A","explanation":"Le passage indique : « Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles. » Cela justifie la réponse : Une faible lumière extérieure."},{"number":8,"points":9,"passage":"Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions.","question":"À quel public s'adresse l'événement ?","options":["Aussi aux personnes sans formation scientifique","Uniquement aux chercheurs diplômés","Seulement aux vendeurs d'instruments","Aux participants refusant les explications"],"correct":"A","explanation":"Le passage indique : « Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions. » Cela justifie la réponse : Aussi aux personnes sans formation scientifique."},{"number":9,"points":9,"passage":"Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche.","question":"Quel résultat n'est pas garanti ?","options":["La présence d'un animateur","L'observation des pièces","L'ouverture de l'atelier","La réparation de l'appareil"],"correct":"D","explanation":"Le passage indique : « Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche. » Cela justifie la réponse : La réparation de l'appareil."},{"number":10,"points":9,"passage":"Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement.","question":"Pourquoi changer les récipients ?","options":["Éviter toute répétition","Obtenir un résultat décidé d'avance","Rendre les conditions comparables","Augmenter la couleur des liquides"],"correct":"C","explanation":"Le passage indique : « Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement. » Cela justifie la réponse : Rendre les conditions comparables."},{"number":11,"points":15,"passage":"Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée.","question":"Qu'est-ce qui varie dans leur protocole ?","options":["L'heure de la mesure","Le lieu choisi","La longueur du bâton","Le nombre de saisons"],"correct":"A","explanation":"Le passage indique : « Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée. » Cela justifie la réponse : L'heure de la mesure."},{"number":12,"points":15,"passage":"Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches.","question":"Quel intérêt présente cette publication ?","options":["Dissimuler les méthodes employées","Rendre les tentatives infructueuses utiles à d'autres","Remplacer les expériences futures par des opinions","Prouver que toute recherche échoue"],"correct":"B","explanation":"Le passage indique : « Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches. » Cela justifie la réponse : Rendre les tentatives infructueuses utiles à d'autres."},{"number":13,"points":15,"passage":"Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels.","question":"Quelle limite de la maquette est indiquée ?","options":["Elle fonctionne comme un volcan réel","Elle remplace toutes les observations","Elle permet de prévoir toute éruption","Elle simplifie la réalité"],"correct":"D","explanation":"Le passage indique : « Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels. » Cela justifie la réponse : Elle simplifie la réalité."},{"number":14,"points":15,"passage":"Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil.","question":"Pourquoi préciser leur emplacement ?","options":["Rendre les capteurs invisibles aux oiseaux","Augmenter automatiquement les températures","Éviter une influence locale qui fausserait la comparaison","Accélérer la croissance des arbres"],"correct":"C","explanation":"Le passage indique : « Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil. » Cela justifie la réponse : Éviter une influence locale qui fausserait la comparaison."},{"number":15,"points":15,"passage":"Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée.","question":"Quel critère veulent-ils examiner ?","options":["Le prix du verre","La vitesse de livraison du produit","La couleur des couvercles","La facilité d'utilisation pour divers profils"],"correct":"D","explanation":"Le passage indique : « Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée. » Cela justifie la réponse : La facilité d'utilisation pour divers profils."},{"number":16,"points":15,"passage":"Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes.","question":"À quoi servent les archives ?","options":["Éviter toute comparaison","Remplacer les images actuelles par des publicités","Observer des changements sur la durée","Garantir que rien ne change"],"correct":"C","explanation":"Le passage indique : « Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes. » Cela justifie la réponse : Observer des changements sur la durée."},{"number":17,"points":15,"passage":"Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès.","question":"Quelle information complémentaire est nécessaire ?","options":["Le nombre d'affiches commerciales","Le nom du livreur","La forme de la facture","L'autonomie de la batterie"],"correct":"D","explanation":"Le passage indique : « Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès. » Cela justifie la réponse : L'autonomie de la batterie."},{"number":18,"points":15,"passage":"La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges.","question":"Pourquoi regrouper les questions ?","options":["Écarter tous les non-spécialistes","Interdire les désaccords","Mieux organiser la discussion","Fixer les réponses avant le débat"],"correct":"C","explanation":"Le passage indique : « La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges. » Cela justifie la réponse : Mieux organiser la discussion."},{"number":19,"points":15,"passage":"Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement.","question":"Quel est l'objectif principal ?","options":["Explorer le fonctionnement du dispositif","Éviter de modifier l'orientation","Ouvrir immédiatement un restaurant","Garantir une cuisson par tous les temps"],"correct":"A","explanation":"Le passage indique : « Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement. » Cela justifie la réponse : Explorer le fonctionnement du dispositif."},{"number":20,"points":21,"passage":"Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions.","question":"Quelle prudence expriment-ils ?","options":["Les essais sur petites pièces sont toujours inutiles","Le changement d'échelle doit être vérifié","Les matériaux sont déjà interdits","Toute comparaison est impossible"],"correct":"B","explanation":"Le passage indique : « Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. » Cela justifie la réponse : Le changement d'échelle doit être vérifié."},{"number":21,"points":21,"passage":"Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle.","question":"Quel est l'intérêt de l'échange ?","options":["Éliminer les artisans du projet","Choisir uniquement la meilleure photographie","Croiser mesures techniques et expérience d'usage","Remplacer toute mesure par une anecdote"],"correct":"C","explanation":"Le passage indique : « Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. » Cela justifie la réponse : Croiser mesures techniques et expérience d'usage."},{"number":22,"points":21,"passage":"Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente.","question":"Que faut-il distinguer ?","options":["Un laboratoire et un musée","Un potentiel et un résultat déjà généralisable","Une expérience et une absence totale de résultat","Deux découvertes nécessairement opposées"],"correct":"B","explanation":"Le passage indique : « Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. » Cela justifie la réponse : Un potentiel et un résultat déjà généralisable."},{"number":23,"points":21,"passage":"Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes.","question":"Pourquoi ajouter ces témoignages ?","options":["Relier les mesures aux situations vécues","Remplacer la carte par des votes","Annuler toutes les températures enregistrées","Garantir une météo uniforme"],"correct":"A","explanation":"Le passage indique : « Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. » Cela justifie la réponse : Relier les mesures aux situations vécues."},{"number":24,"points":21,"passage":"Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable.","question":"Quelle exigence demeure ?","options":["L'absence de tout réglage","La vérification des mesures","La suppression des relevés","L'achat d'un appareil plus lourd"],"correct":"B","explanation":"Le passage indique : « Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. » Cela justifie la réponse : La vérification des mesures."},{"number":25,"points":21,"passage":"Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments.","question":"Quel complément à la conception est nécessaire ?","options":["Un prix toujours croissant","Un brevet sur chaque vis","L'accès aux pièces de rechange","Un emballage impossible à ouvrir"],"correct":"C","explanation":"Le passage indique : « Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments. » Cela justifie la réponse : L'accès aux pièces de rechange."},{"number":26,"points":21,"passage":"Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes.","question":"Que montre cette démarche ?","options":["Tout désaccord annule toutes les observations","Les données ne jouent aucun rôle","La science exige une opinion identique sur tout","Un accord sur des faits peut coexister avec des débats"],"correct":"D","explanation":"Le passage indique : « Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes. » Cela justifie la réponse : Un accord sur des faits peut coexister avec des débats."},{"number":27,"points":21,"passage":"Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale.","question":"Quel rôle lui est attribué ?","options":["Décider seul de tous les résultats","Assister une vérification humaine","Interdire les contrôles","Supprimer les photographies utiles"],"correct":"B","explanation":"Le passage indique : « Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale. » Cela justifie la réponse : Assister une vérification humaine."},{"number":28,"points":21,"passage":"Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences.","question":"Quel objectif poursuit cette répétition ?","options":["Obtenir automatiquement la même opinion","Remplacer les instruments par un questionnaire","Tester la robustesse du résultat","Éviter d'expliquer les méthodes"],"correct":"C","explanation":"Le passage indique : « Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences. » Cela justifie la réponse : Tester la robustesse du résultat."},{"number":29,"points":21,"passage":"Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs.","question":"Que révèle cette sélection ?","options":["Une bonne performance garantit le succès","Le coût n'a aucun effet sur l'usage","L'utilité dépend aussi du contexte d'adoption","Toutes les inventions anciennes étaient défectueuses"],"correct":"C","explanation":"Le passage indique : « Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs. » Cela justifie la réponse : L'utilité dépend aussi du contexte d'adoption."},{"number":30,"points":26,"passage":"Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée.","question":"Quelle leçon veut-elle transmettre ?","options":["Les moyennes sont toujours fausses","Les mesures individuelles ne servent jamais","Deux moyennes égales prouvent des situations identiques","Une moyenne ne décrit pas toute la distribution"],"correct":"D","explanation":"Le passage indique : « Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée. » Cela justifie la réponse : Une moyenne ne décrit pas toute la distribution."},{"number":31,"points":26,"passage":"Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation.","question":"Quelle distinction est faite ?","options":["Démonstration réussie et fonctionnement quotidien","Matériel neuf et appareil obligatoirement inutile","Invention et absence de tout essai","Mesure scientifique et interdiction d'usage"],"correct":"A","explanation":"Le passage indique : « Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation. » Cela justifie la réponse : Démonstration réussie et fonctionnement quotidien."},{"number":32,"points":26,"passage":"Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi.","question":"Quelle valeur supplémentaire est attribuée aux collections ?","options":["Prouver que toutes les questions ont leur réponse","Remplacer tous les laboratoires","Empêcher les méthodes nouvelles","Permettre de nouvelles investigations"],"correct":"D","explanation":"Le passage indique : « Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi. » Cela justifie la réponse : Permettre de nouvelles investigations."},{"number":33,"points":26,"passage":"Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation.","question":"Que faut-il préserver dans la simplification ?","options":["Un résultat présenté comme certain à tout prix","Les éléments nécessaires à une interprétation juste","Tous les détails sans hiérarchie","Uniquement les couleurs du graphique"],"correct":"B","explanation":"Le passage indique : « Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation. » Cela justifie la réponse : Les éléments nécessaires à une interprétation juste."},{"number":34,"points":26,"passage":"Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent.","question":"Pourquoi modifier le programme ?","options":["Mieux comprendre le besoin avant de stabiliser la solution","Interdire toute idée technique","Garantir une invention sans essai","Réduire la place des utilisateurs"],"correct":"A","explanation":"Le passage indique : « Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent. » Cela justifie la réponse : Mieux comprendre le besoin avant de stabiliser la solution."},{"number":35,"points":26,"passage":"Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer.","question":"Quelle conception du savoir est défendue ?","options":["Un refus de publier les observations","Une opinion qu'aucune donnée ne peut modifier","Une certitude identique dès la première question","Un savoir révisable selon les preuves disponibles"],"correct":"D","explanation":"Le passage indique : « Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer. » Cela justifie la réponse : Un savoir révisable selon les preuves disponibles."},{"number":36,"points":33,"passage":"Une fondation souhaite ne financer que des recherches dont l'application serait immédiatement prévisible. Des chercheurs rappellent que certaines méthodes utiles aujourd'hui proviennent de travaux d'abord motivés par des questions fondamentales. Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard.","question":"Quel risque est souligné ?","options":["Réduire la diversité des voies de découverte","Financer automatiquement toutes les recherches","Garantir des résultats inutiles dans chaque projet","Supprimer le besoin de méthodes fiables"],"correct":"A","explanation":"Le passage indique : « Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard. » Cela justifie la réponse : Réduire la diversité des voies de découverte."},{"number":37,"points":33,"passage":"Une simulation aide une commune à anticiper les crues. Ses cartes dépendent d'hypothèses sur la pluie et l'état des sols. Les responsables les utilisent pour comparer des scénarios, sans les présenter comme une photographie certaine de l'avenir. La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude.","question":"Comment la simulation est-elle utilisée ?","options":["Comme une garantie exacte de chaque événement futur","Comme un appui à la comparaison de scénarios","Comme un substitut à toute décision publique","Comme une représentation indépendante de ses hypothèses"],"correct":"B","explanation":"Le passage indique : « La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude. » Cela justifie la réponse : Comme un appui à la comparaison de scénarios."},{"number":38,"points":33,"passage":"Une équipe cherche à reproduire un résultat publié et obtient un écart. Avant d'accuser les premiers auteurs, elle examine les instruments, les matériaux et les conditions de l'essai. Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute.","question":"Quelle attitude est mise en valeur ?","options":["Écarter les nouveaux résultats sans examen","Considérer toute reproduction comme inutile","Conclure immédiatement à une fraude","Enquêter sur les causes de l'écart"],"correct":"D","explanation":"Le passage indique : « Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute. » Cela justifie la réponse : Enquêter sur les causes de l'écart."},{"number":39,"points":33,"passage":"Des citoyens participent à une enquête sur la qualité de l'air. Les scientifiques les associent au choix des lieux, mais conservent un protocole commun de mesure. La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables.","question":"Quelle articulation est défendue ?","options":["Remplacer les données par un vote sur les résultats","Associer expérience citoyenne et méthode partagée","Réserver toutes les questions aux seuls experts","Laisser chaque mesure sans règle commune"],"correct":"B","explanation":"Le passage indique : « La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables. » Cela justifie la réponse : Associer expérience citoyenne et méthode partagée."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-10','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-10","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 10","topic":"Apprendre tout au long de la vie","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là.","question":"Quel service est disponible dimanche ?","options":["Rencontrer tous les enseignants","Travailler dans la salle","Emprunter des livres","Inscrire une classe"],"correct":"B","explanation":"Le passage indique : « La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là. » Cela justifie la réponse : Travailler dans la salle."},{"number":2,"points":3,"passage":"Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté.","question":"Qui peut s'inscrire ?","options":["Une personne déjà experte","Une personne débutante","Uniquement un diplômé","Un professeur seulement"],"correct":"B","explanation":"Le passage indique : « Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté. » Cela justifie la réponse : Une personne débutante."},{"number":3,"points":3,"passage":"Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi.","question":"Où un élève absent pourra-t-il récupérer sa copie ?","options":["Dans une autre école","Uniquement par courrier","Au secrétariat mardi","À la bibliothèque dimanche"],"correct":"C","explanation":"Le passage indique : « Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi. » Cela justifie la réponse : Au secrétariat mardi."},{"number":4,"points":3,"passage":"La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine.","question":"Quel accompagnement est proposé ?","options":["Un cours obligatoire pour les parents","Un examen pour les enfants","Une sortie scolaire payante","Une garde pendant la réunion"],"correct":"D","explanation":"Le passage indique : « La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine. » Cela justifie la réponse : Une garde pendant la réunion."},{"number":5,"points":9,"passage":"Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ?","question":"Que demande cette personne ?","options":["Un changement définitif de professeur","Une dispense de tous les cours","Les exercices qu'elle manquera","Un diplôme sans examen"],"correct":"C","explanation":"Le passage indique : « Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ? » Cela justifie la réponse : Les exercices qu'elle manquera."},{"number":6,"points":9,"passage":"Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement.","question":"Quelle condition détermine l'ouverture ?","options":["Un nombre minimal de confirmations","La réussite à un concours","Une expérience professionnelle précise","L'achat immédiat d'un manuel"],"correct":"A","explanation":"Le passage indique : « Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement. » Cela justifie la réponse : Un nombre minimal de confirmations."},{"number":7,"points":9,"passage":"Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale.","question":"À quoi servira l'objet ?","options":["Être vendu en classe","Décorer définitivement l'école","Remplacer l'inscription","Soutenir une prise de parole"],"correct":"D","explanation":"Le passage indique : « Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale. » Cela justifie la réponse : Soutenir une prise de parole."},{"number":8,"points":9,"passage":"Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ?","question":"Quel besoin est exprimé ?","options":["Un cours de dessin artistique uniquement","Un changement de lieu de travail","Une préparation à tous les examens","Un apprentissage lié à une tâche précise"],"correct":"D","explanation":"Le passage indique : « Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ? » Cela justifie la réponse : Un apprentissage lié à une tâche précise."},{"number":9,"points":9,"passage":"La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous.","question":"Quelle attitude est attendue ?","options":["Écarter les débutants","Partager une méthode sans l'imposer","Défendre une solution obligatoire","Comparer les notes publiquement"],"correct":"B","explanation":"Le passage indique : « La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous. » Cela justifie la réponse : Partager une méthode sans l'imposer."},{"number":10,"points":9,"passage":"Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes.","question":"Comment sont organisés les après-midi ?","options":["En autonomie avec une aide possible","Sans aucun travail prévu","Avec un examen permanent","Uniquement en présence du directeur"],"correct":"A","explanation":"Le passage indique : « Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes. » Cela justifie la réponse : En autonomie avec une aide possible."},{"number":11,"points":15,"passage":"Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide.","question":"Quel principe est retenu ?","options":["Multiplier les moyens d'accès à la consigne","Imposer une seule méthode","Réserver l'audio aux enseignants","Supprimer la lecture pour tous"],"correct":"A","explanation":"Le passage indique : « Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide. » Cela justifie la réponse : Multiplier les moyens d'accès à la consigne."},{"number":12,"points":15,"passage":"Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole.","question":"Pourquoi varier les groupes ?","options":["Éviter toute interaction","Supprimer les activités libres","Favoriser la participation de chacun","Classer définitivement les participants"],"correct":"C","explanation":"Le passage indique : « Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole. » Cela justifie la réponse : Favoriser la participation de chacun."},{"number":13,"points":15,"passage":"Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester.","question":"Quel apprentissage est travaillé ?","options":["Identifier le statut des informations","Écrire sans vérifier","Éliminer toutes les questions","Publier uniquement des certitudes personnelles"],"correct":"A","explanation":"Le passage indique : « Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester. » Cela justifie la réponse : Identifier le statut des informations."},{"number":14,"points":15,"passage":"Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée.","question":"Pourquoi la durée peut-elle varier ?","options":["Les participants choisissent leur diplôme","Les examens sont tirés au sort","Les acquis initiaux sont pris en compte","Le tarif dépend de la taille des classes"],"correct":"C","explanation":"Le passage indique : « Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée. » Cela justifie la réponse : Les acquis initiaux sont pris en compte."},{"number":15,"points":15,"passage":"Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation.","question":"À quoi sert le premier essai ?","options":["Distribuer des notes secrètes","Éviter toute correction","Apprendre à partir des erreurs","Remplacer définitivement l'évaluation"],"correct":"C","explanation":"Le passage indique : « Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation. » Cela justifie la réponse : Apprendre à partir des erreurs."},{"number":16,"points":15,"passage":"La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles.","question":"Quelle démarche est demandée ?","options":["Recopier une publicité sans commentaire","Évaluer le salaire des visiteurs","Donner uniquement une impression avant la visite","Confronter une représentation à l'expérience"],"correct":"D","explanation":"Le passage indique : « La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles. » Cela justifie la réponse : Confronter une représentation à l'expérience."},{"number":17,"points":15,"passage":"Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours.","question":"Quel problème cherche-t-on à réduire ?","options":["Une barrière matérielle à la formation","Le manque de places de parking","Le nombre de devoirs","La durée du trimestre"],"correct":"A","explanation":"Le passage indique : « Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours. » Cela justifie la réponse : Une barrière matérielle à la formation."},{"number":18,"points":15,"passage":"Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves.","question":"Quel choix est offert ?","options":["La suppression de la cour","Différentes façons de vivre la pause","Une obligation de rester en classe","Un examen pendant la récréation"],"correct":"B","explanation":"Le passage indique : « Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves. » Cela justifie la réponse : Différentes façons de vivre la pause."},{"number":19,"points":15,"passage":"Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer.","question":"Quelle précaution est enseignée ?","options":["Vérifier le contexte de l'image","Se fier uniquement à sa première impression","Ignorer la date de publication","Compter les couleurs"],"correct":"A","explanation":"Le passage indique : « Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer. » Cela justifie la réponse : Vérifier le contexte de l'image."},{"number":20,"points":21,"passage":"Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent.","question":"Que permet ce dispositif ?","options":["Éviter tout travail personnel","Obtenir immédiatement tous les diplômes","Interdire une poursuite d'études","Commencer progressivement sans perdre ses acquis"],"correct":"D","explanation":"Le passage indique : « Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. » Cela justifie la réponse : Commencer progressivement sans perdre ses acquis."},{"number":21,"points":21,"passage":"Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves.","question":"Quelle interprétation est ajoutée ?","options":["Toutes les questions sont inutiles","Les élèves comprennent toujours les consignes","La répétition prouve nécessairement un refus d'apprendre","La clarté de l'enseignement doit aussi être examinée"],"correct":"D","explanation":"Le passage indique : « Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. » Cela justifie la réponse : La clarté de l'enseignement doit aussi être examinée."},{"number":22,"points":21,"passage":"Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée.","question":"Quels éléments sont combinés ?","options":["Isolement et contrôle permanent","Absence d'horaires et absence de contact","Cours uniquement en présence","Autonomie et accompagnement"],"correct":"D","explanation":"Le passage indique : « Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. » Cela justifie la réponse : Autonomie et accompagnement."},{"number":23,"points":21,"passage":"Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires.","question":"Quel objectif est poursuivi ?","options":["Imposer une langue unique au domicile","Classer les familles selon leurs revenus","Reconnaître des pratiques linguistiques diverses","Organiser un examen pour les parents"],"correct":"C","explanation":"Le passage indique : « Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. » Cela justifie la réponse : Reconnaître des pratiques linguistiques diverses."},{"number":24,"points":21,"passage":"Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe.","question":"Quelle progression pédagogique est choisie ?","options":["Éviter toute mise en pratique","Commencer par un classement des participants","Apprendre toutes les commandes sans usage","Partir d'un besoin pour introduire les notions"],"correct":"D","explanation":"Le passage indique : « Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. » Cela justifie la réponse : Partir d'un besoin pour introduire les notions."},{"number":25,"points":21,"passage":"Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse.","question":"Quel rôle doivent-ils jouer ?","options":["Aider l'autre à construire sa démarche","Remplacer les enseignants dans toutes leurs tâches","Faire tous les exercices à sa place","Attribuer les notes finales"],"correct":"A","explanation":"Le passage indique : « Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse. » Cela justifie la réponse : Aider l'autre à construire sa démarche."},{"number":26,"points":21,"passage":"Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer.","question":"Quelle distinction motive cette évaluation ?","options":["Âge des participants et taille du centre","Plaisir de la formation et transfert dans la pratique","Prix du cours et couleur des supports","Présence en classe et nombre de fenêtres"],"correct":"B","explanation":"Le passage indique : « Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer. » Cela justifie la réponse : Plaisir de la formation et transfert dans la pratique."},{"number":27,"points":21,"passage":"Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère.","question":"Quel apprentissage est privilégié ?","options":["Refuser toute méthode différente","Comparer des démarches justifiées","Copier une préférence supposée","Choisir la réponse la plus longue"],"correct":"B","explanation":"Le passage indique : « Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère. » Cela justifie la réponse : Comparer des démarches justifiées."},{"number":28,"points":21,"passage":"Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants.","question":"Quel équilibre cherche-t-elle ?","options":["Interdire les échanges entre étudiants","Répondre à des usages de travail différents","Supprimer toute étude individuelle","Réserver les livres aux groupes"],"correct":"B","explanation":"Le passage indique : « Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants. » Cela justifie la réponse : Répondre à des usages de travail différents."},{"number":29,"points":21,"passage":"Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus.","question":"Quelle cause est identifiée ?","options":["Des contraintes extérieures à l'apprentissage","Le refus de toute aide","Une absence de progrès","Un niveau systématiquement trop élevé"],"correct":"A","explanation":"Le passage indique : « Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus. » Cela justifie la réponse : Des contraintes extérieures à l'apprentissage."},{"number":30,"points":26,"passage":"Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée.","question":"Quelle condition rend ce droit utile ?","options":["Une possibilité accompagnée d'analyser et de corriger","Une absence totale de retour","L'interdiction de recommencer","La suppression de tous les objectifs"],"correct":"A","explanation":"Le passage indique : « Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée. » Cela justifie la réponse : Une possibilité accompagnée d'analyser et de corriger."},{"number":31,"points":26,"passage":"Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées.","question":"Quel risque veulent-ils surveiller ?","options":["Une impossibilité de conserver les réponses","Une absence de tout exercice","Une limitation des occasions d'explorer d'autres tâches","Une multiplication certaine des enseignants"],"correct":"C","explanation":"Le passage indique : « Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées. » Cela justifie la réponse : Une limitation des occasions d'explorer d'autres tâches."},{"number":32,"points":26,"passage":"Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre.","question":"Pourquoi faire tourner les rôles ?","options":["Éviter les discussions sur le travail","Fixer les mêmes meneurs pour tous les projets","Supprimer les responsabilités","Distribuer plus équitablement les apprentissages"],"correct":"D","explanation":"Le passage indique : « Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre. » Cela justifie la réponse : Distribuer plus équitablement les apprentissages."},{"number":33,"points":26,"passage":"Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre.","question":"Que doit permettre l'accompagnement ?","options":["Remplacer l'expérience par une opinion","Mettre en mots une expérience déjà acquise","Conclure immédiatement à une absence de savoir-faire","Éviter tout exemple concret"],"correct":"B","explanation":"Le passage indique : « Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre. » Cela justifie la réponse : Mettre en mots une expérience déjà acquise."},{"number":34,"points":26,"passage":"Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants.","question":"Quelle prudence est recommandée ?","options":["Classer les établissements avec un seul pourcentage","Contextualiser les chiffres avant de comparer","Ignorer tous les abandons","Considérer les publics comme identiques partout"],"correct":"B","explanation":"Le passage indique : « Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants. » Cela justifie la réponse : Contextualiser les chiffres avant de comparer."},{"number":35,"points":26,"passage":"Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue.","question":"Comment l'autonomie est-elle envisagée ?","options":["Comme un objectif préparé par un accompagnement ajusté","Comme une aptitude impossible à développer","Comme l'absence immédiate de toute aide","Comme une obligation de travailler toujours seul"],"correct":"A","explanation":"Le passage indique : « Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue. » Cela justifie la réponse : Comme un objectif préparé par un accompagnement ajusté."},{"number":36,"points":33,"passage":"Une école distribue des tablettes à tous les élèves et constate des usages très différents. Certains disposent chez eux d'un espace calme et d'un adulte disponible ; d'autres partagent une connexion fragile. L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage.","question":"Quelle limite du dispositif apparaît ?","options":["Tous les élèves bénéficient du même soutien","La connexion ne joue aucun rôle","Les conditions d'utilisation restent inégales","Une tablette empêche nécessairement d'apprendre"],"correct":"C","explanation":"Le passage indique : « L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage. » Cela justifie la réponse : Les conditions d'utilisation restent inégales."},{"number":37,"points":33,"passage":"Une formation promet de respecter le rythme de chacun. Mais son calendrier final reste rigide, et les aides disparaissent après une courte période. Les participants qui ont besoin de plus de temps sont alors les premiers exclus. Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours.","question":"Quel décalage est dénoncé ?","options":["Une formation qui refuse d'utiliser des supports","Un accompagnement illimité pour tous","L'absence de toute date dans le programme","Une promesse de souplesse contredite par les règles du parcours"],"correct":"D","explanation":"Le passage indique : « Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours. » Cela justifie la réponse : Une promesse de souplesse contredite par les règles du parcours."},{"number":38,"points":33,"passage":"Apprendre une méthode ne signifie pas toujours savoir quand l'utiliser. Des élèves réussissent un exercice familier, puis échouent lorsque le même problème apparaît dans une présentation différente. Le professeur multiplie les contextes et fait discuter les choix. La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre.","question":"Quel objectif dépasse l'exécution d'une méthode ?","options":["Choisir la méthode la plus rapide sans analyser","Éviter toute situation nouvelle","Identifier ses conditions d'utilisation","Mémoriser seulement l'ordre des pages"],"correct":"C","explanation":"Le passage indique : « La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre. » Cela justifie la réponse : Identifier ses conditions d'utilisation."},{"number":39,"points":33,"passage":"Un centre valorise l'expérience de ses apprenants adultes. Il ne considère pourtant pas que cette expérience suffit à répondre à toute question. Les échanges mettent parfois en évidence des habitudes efficaces dans un contexte et inadaptées dans un autre. Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible.","question":"Quelle place est donnée à l'expérience ?","options":["Un obstacle qu'il faut toujours oublier","Un savoir nécessairement identique pour tous","Une ressource à examiner et à enrichir","Une preuve qui ne peut jamais être discutée"],"correct":"C","explanation":"Le passage indique : « Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible. » Cela justifie la réponse : Une ressource à examiner et à enrichir."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-11','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-11","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 11","topic":"Solidarité, associations et engagement","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain.","question":"Que peut-on donner cette semaine ?","options":["Des meubles démontés","Des aliments ouverts","Des couvertures propres","Des vêtements mouillés"],"correct":"C","explanation":"Le passage indique : « La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain. » Cela justifie la réponse : Des couvertures propres."},{"number":2,"points":3,"passage":"La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire.","question":"Quand peut-on venir directement ?","options":["Tous les matins","Le dimanche soir","Le lundi seulement","Le jeudi"],"correct":"D","explanation":"Le passage indique : « La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire. » Cela justifie la réponse : Le jeudi."},{"number":3,"points":3,"passage":"Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi.","question":"Qui est attendu à neuf heures ?","options":["Les musiciens du soir uniquement","Tous les convives","Les clients du marché","Les bénévoles chargés de l'installation"],"correct":"D","explanation":"Le passage indique : « Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi. » Cela justifie la réponse : Les bénévoles chargés de l'installation."},{"number":4,"points":3,"passage":"La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone.","question":"Quel document faut-il présenter ?","options":["La confirmation d'inscription","Un billet de spectacle","Un relevé bancaire","Un diplôme scolaire"],"correct":"A","explanation":"Le passage indique : « La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone. » Cela justifie la réponse : La confirmation d'inscription."},{"number":5,"points":9,"passage":"Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ?","question":"Quelle adaptation est demandée ?","options":["Un service de transport privé","Une absence d'activité","Une tâche sans port de charges lourdes","Un changement de tous les horaires"],"correct":"C","explanation":"Le passage indique : « Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ? » Cela justifie la réponse : Une tâche sans port de charges lourdes."},{"number":6,"points":9,"passage":"Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée.","question":"Quel profil convient ?","options":["Uniquement un comédien professionnel","Une personne intéressée par la lecture partagée","Une personne refusant de lire à voix haute","Un vendeur de livres seulement"],"correct":"B","explanation":"Le passage indique : « Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée. » Cela justifie la réponse : Une personne intéressée par la lecture partagée."},{"number":7,"points":9,"passage":"Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits.","question":"Pourquoi la confirmation est-elle importante ?","options":["Annuler toutes les inscriptions","Calculer le prix des repas","Organiser les équipes de deux","Modifier le lieu du festival"],"correct":"C","explanation":"Le passage indique : « Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits. » Cela justifie la réponse : Organiser les équipes de deux."},{"number":8,"points":9,"passage":"La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles.","question":"Quel rôle jouent les achats ordinaires ?","options":["Remplacer les dons par un impôt","Réserver tous les articles aux touristes","Soutenir le fonctionnement solidaire","Supprimer les tarifs adaptés"],"correct":"C","explanation":"Le passage indique : « La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles. » Cela justifie la réponse : Soutenir le fonctionnement solidaire."},{"number":9,"points":9,"passage":"Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent.","question":"Quelle forme d'engagement est choisie ?","options":["Une disponibilité moins fréquente mais fiable","Une participation sans calendrier","Un arrêt de toute aide","Une présence quotidienne"],"correct":"A","explanation":"Le passage indique : « Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent. » Cela justifie la réponse : Une disponibilité moins fréquente mais fiable."},{"number":10,"points":9,"passage":"L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité.","question":"À quoi sert cette séance ?","options":["Attribuer un diplôme professionnel","Présenter les dossiers personnels au public","Préparer l'entrée dans l'activité","Sélectionner les donateurs les plus riches"],"correct":"C","explanation":"Le passage indique : « L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité. » Cela justifie la réponse : Préparer l'entrée dans l'activité."},{"number":11,"points":15,"passage":"Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier.","question":"Quel principe régit l'échange ?","options":["Seuls les professionnels peuvent participer","Le revenu détermine le nombre d'heures","Une même durée a la même valeur","Les outils sont vendus aux voisins"],"correct":"C","explanation":"Le passage indique : « Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier. » Cela justifie la réponse : Une même durée a la même valeur."},{"number":12,"points":15,"passage":"Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place.","question":"Quel objectif accompagne l'aide immédiate ?","options":["Remplacer les décisions des bénéficiaires","Éviter toute explication","Confisquer les documents personnels","Renforcer la compréhension des démarches"],"correct":"D","explanation":"Le passage indique : « Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place. » Cela justifie la réponse : Renforcer la compréhension des démarches."},{"number":13,"points":15,"passage":"Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées.","question":"Pourquoi limiter ces informations publiques ?","options":["Supprimer les rencontres","Attirer des visiteurs payants","Empêcher toute coordination interne","Préserver la confidentialité"],"correct":"D","explanation":"Le passage indique : « Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées. » Cela justifie la réponse : Préserver la confidentialité."},{"number":14,"points":15,"passage":"Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet.","question":"Quelle barrière cherchent-ils à réduire ?","options":["Une difficulté d'accès numérique","La durée des réparations","Le nombre de chaises","Le coût des outils professionnels"],"correct":"A","explanation":"Le passage indique : « Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet. » Cela justifie la réponse : Une difficulté d'accès numérique."},{"number":15,"points":15,"passage":"Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres.","question":"Quel principe est défendu ?","options":["La publicité des dossiers","Le respect de la dignité","La sélection par la prise de parole","Le classement des difficultés"],"correct":"B","explanation":"Le passage indique : « Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres. » Cela justifie la réponse : Le respect de la dignité."},{"number":16,"points":15,"passage":"Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus.","question":"À quoi sert cette fiche ?","options":["Clarifier les responsabilités lors du prêt","Garantir que rien ne s'abîmera jamais","Remplacer tous les échanges humains","Fixer un prix de vente obligatoire"],"correct":"A","explanation":"Le passage indique : « Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus. » Cela justifie la réponse : Clarifier les responsabilités lors du prêt."},{"number":17,"points":15,"passage":"Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent.","question":"Quelle limite est posée ?","options":["Les conversations sont interdites","Les visiteurs prescrivent des traitements","Les bénéficiaires doivent rester seuls","Les visites ne remplacent pas des soins"],"correct":"D","explanation":"Le passage indique : « Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent. » Cela justifie la réponse : Les visites ne remplacent pas des soins."},{"number":18,"points":15,"passage":"Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement.","question":"Quel objectif guide ces choix ?","options":["Élargir la participation aux échanges","Rendre les documents plus techniques","Réserver les décisions aux traducteurs","Supprimer les débats"],"correct":"A","explanation":"Le passage indique : « Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement. » Cela justifie la réponse : Élargir la participation aux échanges."},{"number":19,"points":15,"passage":"Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables.","question":"Pourquoi vérifier les jeux ?","options":["Éviter tout tri","Assurer la qualité des dons distribués","Réserver les jeux aux organisateurs","Augmenter leur prix de revente"],"correct":"B","explanation":"Le passage indique : « Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables. » Cela justifie la réponse : Assurer la qualité des dons distribués."},{"number":20,"points":21,"passage":"Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies.","question":"Pourquoi cette consultation est-elle nécessaire ?","options":["Supprimer toute disponibilité bénévole","Prendre en compte des contraintes différentes","Fixer les horaires au hasard","Éviter de rencontrer les bénéficiaires"],"correct":"B","explanation":"Le passage indique : « Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. » Cela justifie la réponse : Prendre en compte des contraintes différentes."},{"number":21,"points":21,"passage":"Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire.","question":"Quelle distinction est faite ?","options":["Les frais réels sont toujours nuls","Tous les déplacements sont des emplois","Les conducteurs paient les passagers","Rembourser une dépense n'est pas rémunérer un service"],"correct":"D","explanation":"Le passage indique : « Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. » Cela justifie la réponse : Rembourser une dépense n'est pas rémunérer un service."},{"number":22,"points":21,"passage":"Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé.","question":"Quel souci manifeste cette démarche ?","options":["L'abandon du projet initial sans explication","La transparence envers les donateurs","Le refus de tout suivi","La recherche de nouveaux frais cachés"],"correct":"B","explanation":"Le passage indique : « Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. » Cela justifie la réponse : La transparence envers les donateurs."},{"number":23,"points":21,"passage":"Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives.","question":"Quel effet est recherché ?","options":["Éviter les intérêts personnels","Réserver le lieu aux nouveaux arrivants","Créer des relations qui dépassent le seul besoin d'aide","Transformer toutes les rencontres en démarches"],"correct":"C","explanation":"Le passage indique : « Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. » Cela justifie la réponse : Créer des relations qui dépassent le seul besoin d'aide."},{"number":24,"points":21,"passage":"Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires.","question":"Quel besoin complémentaire expriment-elles ?","options":["De l'aide pour intégrer les bénévoles","Une rémunération automatique de tous les volontaires","Un remplacement de leur activité par des annonces","Une suppression des missions"],"correct":"A","explanation":"Le passage indique : « Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. » Cela justifie la réponse : De l'aide pour intégrer les bénévoles."},{"number":25,"points":21,"passage":"Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique.","question":"Quelle idée de la participation apparaît ?","options":["Seule la force physique compte","Des apports différents peuvent être également utiles","Tous doivent accomplir la même tâche","L'accueil ne demande jamais de travail"],"correct":"B","explanation":"Le passage indique : « Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique. » Cela justifie la réponse : Des apports différents peuvent être également utiles."},{"number":26,"points":21,"passage":"Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock.","question":"Quel changement dans l'accueil est recherché ?","options":["Supprimer la gestion des stocks","Garantir tous les produits à toute heure","Laisser une place au choix des personnes","Distribuer sans aucun échange"],"correct":"C","explanation":"Le passage indique : « Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock. » Cela justifie la réponse : Laisser une place au choix des personnes."},{"number":27,"points":21,"passage":"Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs.","question":"Quel risque cherche-t-il à réduire ?","options":["La régularité des actions","Le partage des informations utiles","L'arrivée de nouveaux bénévoles","La dépendance à quelques personnes"],"correct":"D","explanation":"Le passage indique : « Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs. » Cela justifie la réponse : La dépendance à quelques personnes."},{"number":28,"points":21,"passage":"L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas.","question":"Pourquoi compléter les chiffres ?","options":["Comparer uniquement les budgets","Mieux comprendre les effets des actions","Remplacer les personnes par des statistiques","Renoncer à toute vérification"],"correct":"B","explanation":"Le passage indique : « L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas. » Cela justifie la réponse : Mieux comprendre les effets des actions."},{"number":29,"points":21,"passage":"Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli.","question":"Quelle règle distingue cette participation ?","options":["Elle concerne seulement les salariés","Elle ne conditionne pas l'accès à l'aide","Elle remplace toute aide matérielle","Elle est obligatoire chaque semaine"],"correct":"B","explanation":"Le passage indique : « Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli. » Cela justifie la réponse : Elle ne conditionne pas l'accès à l'aide."},{"number":30,"points":26,"passage":"L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action.","question":"Quelle organisation est recommandée ?","options":["Une absence de répartition des tâches","Une disponibilité permanente exigée de tous","Une interdiction de se retirer d'une mission","Un engagement soutenable avec des limites explicites"],"correct":"D","explanation":"Le passage indique : « L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action. » Cela justifie la réponse : Un engagement soutenable avec des limites explicites."},{"number":31,"points":26,"passage":"Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes.","question":"Quelle complémentarité est défendue ?","options":["Agir sur l'urgence et sur les causes","Remplacer toute aide immédiate par une étude","Confondre chaque distribution avec une réforme complète","Renoncer aux questions de logement"],"correct":"A","explanation":"Le passage indique : « Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes. » Cela justifie la réponse : Agir sur l'urgence et sur les causes."},{"number":32,"points":26,"passage":"Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée.","question":"Quelle distinction faut-il faire ?","options":["Bénévolat et obligation de salaire","Nombre d'ordinateurs et nombre de missions","Inscription et disponibilité réelle","Aide sociale et vente de billets"],"correct":"C","explanation":"Le passage indique : « Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée. » Cela justifie la réponse : Inscription et disponibilité réelle."},{"number":33,"points":26,"passage":"Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté.","question":"Quelle condition rend la consultation significative ?","options":["L'absence de tout retour aux participants","La publication de citations uniquement décoratives","Un questionnaire sans suite","Un lien explicite avec les décisions"],"correct":"D","explanation":"Le passage indique : « Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté. » Cela justifie la réponse : Un lien explicite avec les décisions."},{"number":34,"points":26,"passage":"Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service.","question":"Quelle position est défendue ?","options":["Qualité commerciale et mission sociale peuvent se soutenir","Une belle vitrine supprime toute solidarité","Les clients doivent renoncer à choisir","Un service solidaire doit être négligé"],"correct":"A","explanation":"Le passage indique : « Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service. » Cela justifie la réponse : Qualité commerciale et mission sociale peuvent se soutenir."},{"number":35,"points":26,"passage":"Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles.","question":"Quel équilibre recherche-t-il ?","options":["Associer confiance et organisation explicite","Refuser la croissance des besoins sans discussion","Maintenir toutes les règles secrètes","Remplacer toute relation par des formulaires"],"correct":"A","explanation":"Le passage indique : « Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles. » Cela justifie la réponse : Associer confiance et organisation explicite."},{"number":36,"points":33,"passage":"Un projet associe des personnes précaires à des ateliers culturels. Les organisateurs refusent de mesurer le résultat uniquement par un retour à l'emploi. Les relations, la confiance et la possibilité de participer à une vie commune ont une valeur propre. L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat.","question":"Quelle conception du résultat est défendue ?","options":["Transformer chaque atelier en entretien d'embauche","Reconnaître plusieurs effets utiles de la participation","Ignorer toute expérience des participants","Évaluer uniquement le nombre de contrats signés"],"correct":"B","explanation":"Le passage indique : « L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat. » Cela justifie la réponse : Reconnaître plusieurs effets utiles de la participation."},{"number":37,"points":33,"passage":"Une association dépend d'un financement annuel renouvelable. Elle peut annoncer beaucoup d'activités, mais hésite à former durablement son équipe sans visibilité. Les financeurs demandent de la stabilité aux actions qu'ils soutiennent. Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines.","question":"Quelle contradiction apparaît ?","options":["Financer des actions sans aucune attente de durée","Exiger la continuité sans garantir les moyens de la préparer","Garantir des moyens tout en interdisant les activités","Former une équipe qui dispose de ressources illimitées"],"correct":"B","explanation":"Le passage indique : « Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines. » Cela justifie la réponse : Exiger la continuité sans garantir les moyens de la préparer."},{"number":38,"points":33,"passage":"Un collectif publie les récits de personnes accompagnées pour sensibiliser le public. Il leur propose de relire les textes et de retirer leur accord avant diffusion. Le fait qu'un témoignage serve une cause utile ne supprime pas les droits de la personne dont il raconte l'expérience. L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer.","question":"Quel principe guide la publication ?","options":["Le public choisit à la place des personnes","La cause autorise automatiquement tous les récits","Toute aide reçue impose de témoigner","Le consentement reste nécessaire malgré l'utilité de la cause"],"correct":"D","explanation":"Le passage indique : « L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer. » Cela justifie la réponse : Le consentement reste nécessaire malgré l'utilité de la cause."},{"number":39,"points":33,"passage":"Une initiative locale attire l'attention nationale. Ses responsables sont invités à reproduire partout le même modèle. Ils présentent les principes, mais soulignent les relations de confiance et les ressources particulières qui ont permis leur réussite. Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation.","question":"Quelle limite à la reproduction du projet est soulignée ?","options":["La nécessité de tenir compte du contexte local","L'impossibilité de partager des connaissances","L'inutilité de toute relation de confiance","La certitude d'un résultat identique partout"],"correct":"A","explanation":"Le passage indique : « Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation. » Cela justifie la réponse : La nécessité de tenir compte du contexte local."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-12','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-12","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 12","topic":"Campagnes, agriculture et biodiversité","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal.","question":"Quel chemin reste accessible ?","options":["Tous les champs privés","Le sentier des vergers","La cour de la ferme","Le chemin communal"],"correct":"D","explanation":"Le passage indique : « Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal. » Cela justifie la réponse : Le chemin communal."},{"number":2,"points":3,"passage":"La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps.","question":"Que peut-on faire vendredi ?","options":["Dormir dans l'étable","Visiter l'élevage","Acheter à la boutique","Participer aux naissances"],"correct":"C","explanation":"Le passage indique : « La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps. » Cela justifie la réponse : Acheter à la boutique."},{"number":3,"points":3,"passage":"Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles.","question":"Quelle règle concerne les chiens ?","options":["Accompagner obligatoirement chaque visiteur","Courir librement dans les cultures","Rester attachés sur le chemin","Entrer dans tous les bâtiments"],"correct":"C","explanation":"Le passage indique : « Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles. » Cela justifie la réponse : Rester attachés sur le chemin."},{"number":4,"points":3,"passage":"Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures.","question":"Quand une personne seule peut-elle venir sans réservation ?","options":["Dimanche pendant les horaires indiqués","Après seize heures dimanche","Tous les soirs","Uniquement en hiver"],"correct":"A","explanation":"Le passage indique : « Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures. » Cela justifie la réponse : Dimanche pendant les horaires indiqués."},{"number":5,"points":9,"passage":"Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre.","question":"Quelle précaution est conseillée ?","options":["Protéger les jeunes plants du gel","Les laisser sans lumière pendant un mois","Les arroser avec de l'eau glacée","Les planter immédiatement dehors"],"correct":"A","explanation":"Le passage indique : « Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre. » Cela justifie la réponse : Protéger les jeunes plants du gel."},{"number":6,"points":9,"passage":"L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé.","question":"Que deviendront les documents prêtés ?","options":["Ils resteront obligatoirement au musée","Ils seront vendus aux visiteurs","Ils seront restitués après copie","Ils seront détruits après exposition"],"correct":"C","explanation":"Le passage indique : « L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé. » Cela justifie la réponse : Ils seront restitués après copie."},{"number":7,"points":9,"passage":"Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie.","question":"Quelle démarche est demandée à certaines personnes ?","options":["Approcher seules les ruches","Renoncer à toute activité rurale","Apporter leur propre miel","Prévenir l'organisateur à l'avance"],"correct":"D","explanation":"Le passage indique : « Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie. » Cela justifie la réponse : Prévenir l'organisateur à l'avance."},{"number":8,"points":9,"passage":"Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger.","question":"Pourquoi le contenu change-t-il ?","options":["Une récolte a subi un aléa météo","Tous les fruits ont été vendus à l'étranger","Les clients ont demandé uniquement des légumes","Le point de retrait est fermé"],"correct":"A","explanation":"Le passage indique : « Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger. » Cela justifie la réponse : Une récolte a subi un aléa météo."},{"number":9,"points":9,"passage":"Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche.","question":"Quel équipement est recommandé ?","options":["Des sandales de ville","Des chaussures adaptées à la boue","Des patins","Un masque de plongée"],"correct":"B","explanation":"Le passage indique : « Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche. » Cela justifie la réponse : Des chaussures adaptées à la boue."},{"number":10,"points":9,"passage":"Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant.","question":"Pourquoi choisir cet horaire ?","options":["Éviter toute rencontre","Limiter la fatigue liée à la chaleur","Terminer une livraison nocturne","Profiter d'une température plus élevée"],"correct":"B","explanation":"Le passage indique : « Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant. » Cela justifie la réponse : Limiter la fatigue liée à la chaleur."},{"number":11,"points":15,"passage":"Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs.","question":"Quel intérêt est souligné ?","options":["La suppression des plantes aquatiques","La préservation d'habitats particuliers","L'uniformité esthétique","La création d'un parking"],"correct":"B","explanation":"Le passage indique : « Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs. » Cela justifie la réponse : La préservation d'habitats particuliers."},{"number":12,"points":15,"passage":"Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser.","question":"À quoi sert la rotation ?","options":["Transformer les prairies en routes","Récolter le lait sans déplacement","Laisser les prairies se renouveler","Éviter toute alimentation des animaux"],"correct":"C","explanation":"Le passage indique : « Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser. » Cela justifie la réponse : Laisser les prairies se renouveler."},{"number":13,"points":15,"passage":"Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu.","question":"Quelle information complète le comptage ?","options":["Le prix des clôtures","La présence de fleurs","La couleur des maisons","Le nombre de voitures"],"correct":"B","explanation":"Le passage indique : « Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu. » Cela justifie la réponse : La présence de fleurs."},{"number":14,"points":15,"passage":"Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent.","question":"Quel objectif économique est poursuivi ?","options":["Supprimer toutes les ventes fraîches","Travailler uniquement un mois par an","Acheter exclusivement des produits importés","Réduire les variations saisonnières de revenus"],"correct":"D","explanation":"Le passage indique : « Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent. » Cela justifie la réponse : Réduire les variations saisonnières de revenus."},{"number":15,"points":15,"passage":"Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment.","question":"Quel apprentissage est visé ?","options":["Éviter toute observation","Appliquer une règle identique à toutes les graines","Distinguer les conditions de culture","Mesurer seulement le prix des sachets"],"correct":"C","explanation":"Le passage indique : « Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment. » Cela justifie la réponse : Distinguer les conditions de culture."},{"number":16,"points":15,"passage":"Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux.","question":"Quel avantage est indiqué ?","options":["Remplacer les pierres par du plastique","Empêcher tous les passages d'eau","Conserver plusieurs fonctions du muret","Rendre le sol totalement étanche"],"correct":"C","explanation":"Le passage indique : « Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux. » Cela justifie la réponse : Conserver plusieurs fonctions du muret."},{"number":17,"points":15,"passage":"Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants.","question":"Quelle responsabilité accompagne l'activité ?","options":["Récolter dans toutes les parcelles","Préserver les cultures pendant la récolte","Choisir gratuitement tout le stock","Entrer sans consigne"],"correct":"B","explanation":"Le passage indique : « Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants. » Cela justifie la réponse : Préserver les cultures pendant la récolte."},{"number":18,"points":15,"passage":"Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible.","question":"Quel effet est attendu ?","options":["Une fermeture des commerces","Une hausse obligatoire des achats","Une suppression des relations de voisinage","Un accès plus autonome au marché"],"correct":"D","explanation":"Le passage indique : « Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible. » Cela justifie la réponse : Un accès plus autonome au marché."},{"number":19,"points":15,"passage":"Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale.","question":"Quelle prudence est exprimée ?","options":["Refuser toute comparaison annuelle","Ignorer les dates de floraison","Croiser les observations avant de conclure","Considérer un seul événement comme suffisant"],"correct":"C","explanation":"Le passage indique : « Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale. » Cela justifie la réponse : Croiser les observations avant de conclure."},{"number":20,"points":21,"passage":"Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris.","question":"Quel équilibre est recherché ?","options":["Donner de la stabilité avec un suivi","Exiger des résultats immédiats identiques","Réserver les terres aux exploitants déjà installés","Offrir un accès sans aucune règle"],"correct":"A","explanation":"Le passage indique : « Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. » Cela justifie la réponse : Donner de la stabilité avec un suivi."},{"number":21,"points":21,"passage":"Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble.","question":"Pourquoi rester prudent sur la cause ?","options":["Plusieurs changements ont eu lieu simultanément","Les habitants ignorent le lieu de la ferme","Les mesures n'ont jamais été réalisées","Aucun oiseau n'a été observé"],"correct":"A","explanation":"Le passage indique : « Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. » Cela justifie la réponse : Plusieurs changements ont eu lieu simultanément."},{"number":22,"points":21,"passage":"Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification.","question":"Quelle démarche est décrite ?","options":["Préserver tout en adaptant à un nouvel usage","Conserver uniquement le nom de la ferme","Reconstruire une copie sans utiliser le bâtiment","Interdire toute activité nouvelle"],"correct":"A","explanation":"Le passage indique : « Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. » Cela justifie la réponse : Préserver tout en adaptant à un nouvel usage."},{"number":23,"points":21,"passage":"Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits.","question":"Quelle contrepartie accompagne le gain de temps ?","options":["Une disparition des responsabilités","Une coordination entre producteurs","L'arrêt de toute production","L'obligation de vendre les mêmes produits"],"correct":"B","explanation":"Le passage indique : « Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. » Cela justifie la réponse : Une coordination entre producteurs."},{"number":24,"points":21,"passage":"Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor.","question":"Quelle lecture du paysage est proposée ?","options":["Remplacer les fermes par des cartes postales","Ignorer toute intervention humaine","Évaluer uniquement les couleurs","Comprendre les activités qui le façonnent"],"correct":"D","explanation":"Le passage indique : « Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. » Cela justifie la réponse : Comprendre les activités qui le façonnent."},{"number":25,"points":21,"passage":"Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir.","question":"Pourquoi commencer par cet état des lieux ?","options":["Supprimer toutes les récoltes","Garantir immédiatement un nouvel entrepôt","Choisir l'emplacement des bureaux seulement","Vérifier les besoins réels de capacité"],"correct":"D","explanation":"Le passage indique : « Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir. » Cela justifie la réponse : Vérifier les besoins réels de capacité."},{"number":26,"points":21,"passage":"Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement.","question":"Quel aspect complète le projet ?","options":["L'absence de responsabilité après plantation","La vente immédiate de toute la place","La garantie de fruits dès le lendemain","L'organisation de l'entretien dans la durée"],"correct":"D","explanation":"Le passage indique : « Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement. » Cela justifie la réponse : L'organisation de l'entretien dans la durée."},{"number":27,"points":21,"passage":"Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement.","question":"Quelle erreur d'interprétation est corrigée ?","options":["Penser que les saisons existent","Reconnaître que l'eau peut varier","Confondre un état saisonnier avec une absence de fonction","Observer le site en été"],"correct":"C","explanation":"Le passage indique : « Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement. » Cela justifie la réponse : Confondre un état saisonnier avec une absence de fonction."},{"number":28,"points":21,"passage":"Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché.","question":"Quel objectif motive son choix ?","options":["Maximiser uniquement le revenu de l'année","Limiter un risque économique","Abandonner toute vente","Produire pour un client unique"],"correct":"B","explanation":"Le passage indique : « Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché. » Cela justifie la réponse : Limiter un risque économique."},{"number":29,"points":21,"passage":"Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion.","question":"Comment le programme évolue-t-il ?","options":["Il associe héritage et nouvelles contributions","Il est fixé sans échange","Il refuse toute proposition extérieure","Il supprime toutes les habitudes"],"correct":"A","explanation":"Le passage indique : « Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion. » Cela justifie la réponse : Il associe héritage et nouvelles contributions."},{"number":30,"points":26,"passage":"L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique.","question":"Quelle simplification est contestée ?","options":["L'idée d'un monde rural uniforme et sans changement","La diversité des territoires","La possibilité de nouveaux habitants","L'existence de métiers agricoles"],"correct":"A","explanation":"Le passage indique : « L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique. » Cela justifie la réponse : L'idée d'un monde rural uniforme et sans changement."},{"number":31,"points":26,"passage":"Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage.","question":"Quel indicateur complémentaire est proposé ?","options":["La longueur des discours","La couleur des formulaires","Le nombre de photos prises","Le maintien des arbres dans le temps"],"correct":"D","explanation":"Le passage indique : « Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage. » Cela justifie la réponse : Le maintien des arbres dans le temps."},{"number":32,"points":26,"passage":"Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs.","question":"Quelle distinction faut-il retenir ?","options":["Tout achat direct vient nécessairement du village","Tout intermédiaire impose un trajet international","La distance ne peut jamais être estimée","Nombre d'intermédiaires et distance ne sont pas identiques"],"correct":"D","explanation":"Le passage indique : « Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs. » Cela justifie la réponse : Nombre d'intermédiaires et distance ne sont pas identiques."},{"number":33,"points":26,"passage":"Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement.","question":"Quelle démarche est mise en avant ?","options":["Croiser savoirs d'expérience et informations nouvelles","Considérer l'outil comme infaillible","Écarter toute observation locale","Refuser toute donnée mesurée"],"correct":"A","explanation":"Le passage indique : « Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement. » Cela justifie la réponse : Croiser savoirs d'expérience et informations nouvelles."},{"number":34,"points":26,"passage":"Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà.","question":"Quel enjeu d'aménagement apparaît ?","options":["Organiser la coexistence des usages","Supprimer toute information sur les récoltes","Interdire l'agriculture près des promenades","Réserver tous les chemins à un seul public"],"correct":"A","explanation":"Le passage indique : « Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà. » Cela justifie la réponse : Organiser la coexistence des usages."},{"number":35,"points":26,"passage":"Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante.","question":"Quel type de découverte est valorisé ?","options":["Une imitation des seules publicités","Une approche comprenant les contraintes du métier","Une visite réduite aux souvenirs vendus","Une présentation sans aucune difficulté"],"correct":"B","explanation":"Le passage indique : « Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante. » Cela justifie la réponse : Une approche comprenant les contraintes du métier."},{"number":36,"points":33,"passage":"Un projet propose de protéger un paysage en interdisant toute transformation. Les habitants rappellent que ce paysage résulte lui-même de pratiques successives. Ils souhaitent préserver des qualités sans figer les conditions de vie. La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre.","question":"Quelle tension le projet soulève-t-il ?","options":["Supprimer toute notion de patrimoine","Remplacer tous les habitants par des visiteurs","Préserver un paysage tout en permettant son évolution","Choisir entre deux couleurs de clôture uniquement"],"correct":"C","explanation":"Le passage indique : « La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre. » Cela justifie la réponse : Préserver un paysage tout en permettant son évolution."},{"number":37,"points":33,"passage":"Une exploitation est souvent évaluée par son rendement sur une seule culture. Pourtant, elle entretient aussi des haies, partage du matériel et contribue à l'emploi local. Ces fonctions ne justifient pas d'ignorer le rendement, mais elles élargissent les questions à poser. Une performance devient différente selon les dimensions que l'on accepte de compter.","question":"Quelle approche est proposée ?","options":["Une suppression de tout indicateur productif","Une évaluation comportant plusieurs dimensions","Une assimilation de toutes les fermes","Une comparaison limitée à la superficie"],"correct":"B","explanation":"Le passage indique : « Une performance devient différente selon les dimensions que l'on accepte de compter. » Cela justifie la réponse : Une évaluation comportant plusieurs dimensions."},{"number":38,"points":33,"passage":"La vente directe est parfois présentée comme une relation spontanée entre producteur et consommateur. Elle demande pourtant du temps pour accueillir, expliquer et organiser les commandes. Un producteur peut bien cultiver sans souhaiter assurer seul cette activité supplémentaire. Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge.","question":"Quelle idée est soulignée ?","options":["La vente directe ne demande aucun travail","Les tâches de commercialisation doivent toujours être réalisées","Le producteur doit nécessairement tout faire seul","Les consommateurs peuvent supprimer toutes les commandes"],"correct":"B","explanation":"Le passage indique : « Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge. » Cela justifie la réponse : Les tâches de commercialisation doivent toujours être réalisées."},{"number":39,"points":33,"passage":"Un village développe son attractivité pour retenir des habitants. Des services nouveaux apparaissent, mais le prix des logements augmente. Les familles que le projet voulait initialement maintenir peuvent alors rencontrer davantage de difficultés. L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents.","question":"Quel effet contradictoire est décrit ?","options":["Une disparition immédiate des nouveaux services","Une baisse certaine de tous les loyers","Un succès territorial qui peut compliquer le maintien des résidents","Un arrêt de toute arrivée de population"],"correct":"C","explanation":"Le passage indique : « L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents. » Cela justifie la réponse : Un succès territorial qui peut compliquer le maintien des résidents."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-13','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-13","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 13","topic":"Usages numériques et vie privée","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents.","question":"Quel service sera maintenu ?","options":["L'impression à l'accueil","L'accès à tous les ordinateurs","Le cours dans la salle fermée","Le prêt d'une imprimante personnelle"],"correct":"A","explanation":"Le passage indique : « La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents. » Cela justifie la réponse : L'impression à l'accueil."},{"number":2,"points":3,"passage":"Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle.","question":"Que faut-il faire après un appel suspect ?","options":["Publier ses identifiants","Joindre l'assistance par son canal connu","Donner son mot de passe","Rappeler le numéro fourni sans vérification"],"correct":"B","explanation":"Le passage indique : « Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle. » Cela justifie la réponse : Joindre l'assistance par son canal connu."},{"number":3,"points":3,"passage":"L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées.","question":"Quelle préparation est demandée ?","options":["Supprimer la batterie","Acheter un nouveau téléphone","Recharger l'appareil","Imprimer toutes les photos"],"correct":"C","explanation":"Le passage indique : « L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées. » Cela justifie la réponse : Recharger l'appareil."},{"number":4,"points":3,"passage":"Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche.","question":"Quel bouton finalise le dossier ?","options":["Envoyer","Enregistrer provisoirement","Agrandir le texte","Fermer la fenêtre"],"correct":"A","explanation":"Le passage indique : « Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche. » Cela justifie la réponse : Envoyer."},{"number":5,"points":9,"passage":"Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes.","question":"Pourquoi utiliser un dossier commun ?","options":["Empêcher toute modification","Réduire le nombre de participants","Remplacer les fichiers par des appels","Limiter la confusion entre les versions"],"correct":"D","explanation":"Le passage indique : « Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes. » Cela justifie la réponse : Limiter la confusion entre les versions."},{"number":6,"points":9,"passage":"La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même.","question":"Quelle règle protège l'utilisateur ?","options":["Le partage de tous les mots de passe","La non-conservation des codes par l'accompagnateur","L'envoi des codes aux autres participants","La publication des comptes créés"],"correct":"B","explanation":"Le passage indique : « La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même. » Cela justifie la réponse : La non-conservation des codes par l'accompagnateur."},{"number":7,"points":9,"passage":"Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil.","question":"Quelle décision est prise ?","options":["Abandonner tout appel","Prolonger l'usage du téléphone","Vendre la batterie neuve","Acheter immédiatement un modèle récent"],"correct":"B","explanation":"Le passage indique : « Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil. » Cela justifie la réponse : Prolonger l'usage du téléphone."},{"number":8,"points":9,"passage":"Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance.","question":"Quel autre support est prévu ?","options":["Un nouvel ordinateur gratuit","Un examen en salle obligatoire","Une vidéo sans son uniquement","Un texte de la séance"],"correct":"D","explanation":"Le passage indique : « Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance. » Cela justifie la réponse : Un texte de la séance."},{"number":9,"points":9,"passage":"J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis.","question":"Quel objectif poursuit cette personne ?","options":["Travailler uniquement la nuit","Mieux maîtriser les interruptions","Supprimer définitivement sa messagerie","Empêcher tous ses proches d'écrire"],"correct":"B","explanation":"Le passage indique : « J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis. » Cela justifie la réponse : Mieux maîtriser les interruptions."},{"number":10,"points":9,"passage":"Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur.","question":"Que faut-il restituer ?","options":["Un appareil acheté neuf","La tablette et son chargeur","Uniquement la housse","Un abonnement téléphonique"],"correct":"B","explanation":"Le passage indique : « Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur. » Cela justifie la réponse : La tablette et son chargeur."},{"number":11,"points":15,"passage":"Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées.","question":"Quelle priorité est donnée ?","options":["Acheter du stockage supplémentaire","Effacer tous les dossiers","Créer des programmes complexes","Acquérir un repère de base"],"correct":"D","explanation":"Le passage indique : « Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées. » Cela justifie la réponse : Acquérir un repère de base."},{"number":12,"points":15,"passage":"Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée.","question":"Quelle question faut-il se poser ?","options":["Si l'accès demandé correspond au service","Si tous les contacts utilisent l'application","Si le logo est suffisamment coloré","Si le téléphone est assez grand"],"correct":"A","explanation":"Le passage indique : « Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée. » Cela justifie la réponse : Si l'accès demandé correspond au service."},{"number":13,"points":15,"passage":"Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche.","question":"Quel objectif est poursuivi ?","options":["Maintenir plusieurs voies d'accès au service","Supprimer les formulaires","Réserver les appels aux informaticiens","Obliger chacun à acheter un ordinateur"],"correct":"A","explanation":"Le passage indique : « Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche. » Cela justifie la réponse : Maintenir plusieurs voies d'accès au service."},{"number":14,"points":15,"passage":"Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte.","question":"À quoi sert la seconde copie ?","options":["Rendre les photos publiques","Augmenter automatiquement la qualité des images","Supprimer le besoin de classement","Limiter les conséquences de la perte de l'appareil"],"correct":"D","explanation":"Le passage indique : « Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte. » Cela justifie la réponse : Limiter les conséquences de la perte de l'appareil."},{"number":15,"points":15,"passage":"Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court.","question":"Quel aspect doit être amélioré ?","options":["Le nombre de fenêtres de la salle","Le prix du papier","Le rythme de l'interaction","La couleur du bâtiment"],"correct":"C","explanation":"Le passage indique : « Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court. » Cela justifie la réponse : Le rythme de l'interaction."},{"number":16,"points":15,"passage":"Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif.","question":"Quelle distinction est précisée ?","options":["Le livre reste acquis pour toujours","L'emprunteur doit imprimer chaque page","Le droit de lecture est temporaire","Le prêt n'a aucune durée"],"correct":"C","explanation":"Le passage indique : « Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif. » Cela justifie la réponse : Le droit de lecture est temporaire."},{"number":17,"points":15,"passage":"Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données.","question":"Quel critère dépasse l'usage immédiat ?","options":["La couleur du câble","Le nombre de publicités","La possibilité de changer d'outil plus tard","La taille du logo"],"correct":"C","explanation":"Le passage indique : « Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données. » Cela justifie la réponse : La possibilité de changer d'outil plus tard."},{"number":18,"points":15,"passage":"Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs.","question":"Quelle précaution est enseignée ?","options":["Faire confiance à toute copie visuelle","Télécharger tous les fichiers proposés","Vérifier l'adresse plutôt que le seul aspect","Ignorer les informations du navigateur"],"correct":"C","explanation":"Le passage indique : « Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs. » Cela justifie la réponse : Vérifier l'adresse plutôt que le seul aspect."},{"number":19,"points":15,"passage":"Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier.","question":"Quelle limite est rappelée ?","options":["La publication est obligatoire après réception","Les familles ne peuvent jamais regarder les photos","Toute image de groupe doit être vendue","Recevoir une image ne suffit pas à autoriser sa diffusion"],"correct":"D","explanation":"Le passage indique : « Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier. » Cela justifie la réponse : Recevoir une image ne suffit pas à autoriser sa diffusion."},{"number":20,"points":21,"passage":"Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes.","question":"Comment les erreurs sont-elles utilisées ?","options":["Pour améliorer la conception du service","Pour supprimer automatiquement les dossiers","Pour éviter toute correction","Pour classer publiquement les usagers"],"correct":"A","explanation":"Le passage indique : « Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. » Cela justifie la réponse : Pour améliorer la conception du service."},{"number":21,"points":21,"passage":"Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne.","question":"Quel problème doit être géré ?","options":["L'impossibilité d'écrire sans internet","Le manque de papier","La disparition obligatoire du fichier","La réunion de modifications concurrentes"],"correct":"D","explanation":"Le passage indique : « Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. » Cela justifie la réponse : La réunion de modifications concurrentes."},{"number":22,"points":21,"passage":"Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité.","question":"Quel effet cherche-t-elle à limiter ?","options":["Le classement chronologique des dates","La concentration de l'attention sur quelques avis","L'apparition de nouveaux commentaires","La possibilité de lire les avis récents"],"correct":"B","explanation":"Le passage indique : « Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. » Cela justifie la réponse : La concentration de l'attention sur quelques avis."},{"number":23,"points":21,"passage":"Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers.","question":"Quelle possibilité est offerte ?","options":["Conserver ses documents avant de partir","Transférer les fichiers sans accord à la publicité","Interdire la suppression du compte","Rester abonné sans le savoir"],"correct":"A","explanation":"Le passage indique : « Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. » Cela justifie la réponse : Conserver ses documents avant de partir."},{"number":24,"points":21,"passage":"Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance.","question":"Quel principe guide le changement ?","options":["Remplacer tous les échanges par le silence","Choisir le moyen de communication selon l'usage","Éviter toute trace écrite","Imposer une caméra permanente"],"correct":"B","explanation":"Le passage indique : « Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. » Cela justifie la réponse : Choisir le moyen de communication selon l'usage."},{"number":25,"points":21,"passage":"Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant.","question":"Quel avantage présente ce choix ?","options":["Découvrir avant de s'engager dans une inscription","Éviter d'expliquer les fonctions","Supprimer toute possibilité d'apprentissage","Garantir une absence totale de données sur internet"],"correct":"A","explanation":"Le passage indique : « Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant. » Cela justifie la réponse : Découvrir avant de s'engager dans une inscription."},{"number":26,"points":21,"passage":"Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié.","question":"Quel apport fournit cette explication ?","options":["Une suppression des choix possibles","Un changement automatique de destination","Une meilleure compréhension de la recommandation","Une garantie que le trajet convient à tous"],"correct":"C","explanation":"Le passage indique : « Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié. » Cela justifie la réponse : Une meilleure compréhension de la recommandation."},{"number":27,"points":21,"passage":"Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux.","question":"Quelle approche est privilégiée ?","options":["Remplacer les discussions par des sanctions","Condamner tous les usages sans échange","Ignorer les expériences des jeunes","Examiner les pratiques avec les utilisateurs"],"correct":"D","explanation":"Le passage indique : « Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux. » Cela justifie la réponse : Examiner les pratiques avec les utilisateurs."},{"number":28,"points":21,"passage":"Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs.","question":"Que montre cet effet ?","options":["L'accessibilité impose de supprimer les contenus","Les lecteurs d'écran gênent nécessairement les autres","Un travail d'accessibilité peut bénéficier largement","Tous les visiteurs utilisent le même outil"],"correct":"C","explanation":"Le passage indique : « Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs. » Cela justifie la réponse : Un travail d'accessibilité peut bénéficier largement."},{"number":29,"points":21,"passage":"Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible.","question":"Pourquoi partir d'une tâche réelle ?","options":["Éviter toute autonomie","Remplacer les démarches par des jeux uniquement","Rendre les outils plus coûteux","Donner du sens aux apprentissages"],"correct":"D","explanation":"Le passage indique : « Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible. » Cela justifie la réponse : Donner du sens aux apprentissages."},{"number":30,"points":26,"passage":"Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite.","question":"Quelle responsabilité le service reconnaît-il ?","options":["L'absence de toute influence des paramètres","L'effet des choix initiaux sur la confidentialité","L'obligation de tout rendre public","L'impossibilité de modifier un réglage"],"correct":"B","explanation":"Le passage indique : « Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite. » Cela justifie la réponse : L'effet des choix initiaux sur la confidentialité."},{"number":31,"points":26,"passage":"Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs.","question":"Quelle amélioration est recherchée ?","options":["Multiplier les étapes ordinaires","Réduire toute possibilité d'action","Rendre les usages fréquents plus lisibles","Masquer définitivement les fonctions utiles"],"correct":"C","explanation":"Le passage indique : « Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs. » Cela justifie la réponse : Rendre les usages fréquents plus lisibles."},{"number":32,"points":26,"passage":"Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard.","question":"Quelle condition de durée est soulignée ?","options":["Organiser la conservation et l'interprétation des fichiers","Stocker sans classement une seule copie","Choisir uniquement le format le plus récent","Supprimer toute description des documents"],"correct":"A","explanation":"Le passage indique : « Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard. » Cela justifie la réponse : Organiser la conservation et l'interprétation des fichiers."},{"number":33,"points":26,"passage":"Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total.","question":"Quel examen complémentaire est nécessaire ?","options":["Compter uniquement les réponses rapides","Identifier quels cas subissent les erreurs","Supprimer tous les exemples","Considérer la moyenne comme exhaustive"],"correct":"B","explanation":"Le passage indique : « Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total. » Cela justifie la réponse : Identifier quels cas subissent les erreurs."},{"number":34,"points":26,"passage":"Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion.","question":"Quel équilibre est recherché ?","options":["Absence de tout accord collectif","Connexion continue de tous les salariés","Suppression des échanges écrits","Souplesse de travail et limites de disponibilité"],"correct":"D","explanation":"Le passage indique : « Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion. » Cela justifie la réponse : Souplesse de travail et limites de disponibilité."},{"number":35,"points":26,"passage":"Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran.","question":"Quelle compétence durable cherchent-ils à développer ?","options":["Une dépendance permanente au formateur","La capacité de s'orienter face à un changement","La mémorisation immuable d'une interface","Le refus de tout nouvel outil"],"correct":"B","explanation":"Le passage indique : « Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran. » Cela justifie la réponse : La capacité de s'orienter face à un changement."},{"number":36,"points":33,"passage":"Une plateforme présente ses recommandations comme neutres parce qu'elles sont calculées. Pourtant, elle doit choisir ce qu'elle optimise : durée de consultation, diversité ou satisfaction déclarée. Ces objectifs peuvent conduire à des sélections différentes. Un calcul n'efface pas les choix inscrits dans les critères qui le guident.","question":"Quelle idée est contestée ?","options":["La sélection dépend de ce qu'on souhaite favoriser","Un système doit utiliser des critères","L'automaticité garantirait une neutralité sans choix","Des objectifs différents peuvent produire des résultats différents"],"correct":"C","explanation":"Le passage indique : « Un calcul n'efface pas les choix inscrits dans les critères qui le guident. » Cela justifie la réponse : L'automaticité garantirait une neutralité sans choix."},{"number":37,"points":33,"passage":"Une administration remplace un guichet par une démarche en ligne. Le nombre de dossiers déposés augmente, mais les personnes en difficulté se déplacent désormais vers les associations pour obtenir de l'aide. Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître.","question":"Quel effet doit être pris en compte ?","options":["L'autonomie immédiate de tous les usagers","La disparition totale des besoins d'accompagnement","La réduction automatique des déplacements pour chacun","Le transfert de certaines tâches d'aide"],"correct":"D","explanation":"Le passage indique : « Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître. » Cela justifie la réponse : Le transfert de certaines tâches d'aide."},{"number":38,"points":33,"passage":"Un service demande le consentement avant d'utiliser des données, puis présente un formulaire très long dont le refus est difficile à trouver. Le choix existe juridiquement à l'écran, mais l'organisation de la page peut orienter fortement la décision. La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres.","question":"Quelle limite du consentement est soulignée ?","options":["Toute option affichée est également accessible","Un formulaire long garantit une meilleure compréhension","Les conditions de présentation influencent le choix réel","Refuser est toujours impossible techniquement"],"correct":"C","explanation":"Le passage indique : « La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres. » Cela justifie la réponse : Les conditions de présentation influencent le choix réel."},{"number":39,"points":33,"passage":"Un logiciel rend une tâche plus rapide. Les professionnels conservent néanmoins un moyen de travailler en cas de panne et des connaissances pour contrôler les résultats. Ils ne rejettent pas l'automatisation ; ils évitent qu'une commodité se transforme en dépendance sans recours. La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement.","question":"Quelle forme d'autonomie est défendue ?","options":["Garder des capacités de contrôle et de solution de repli","Supprimer les connaissances humaines après installation","Refuser toute amélioration technique","Déléguer toute vérification au logiciel"],"correct":"A","explanation":"Le passage indique : « La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement. » Cela justifie la réponse : Garder des capacités de contrôle et de solution de repli."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-14','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-14","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 14","topic":"Information, médias et communication","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant.","question":"Quand une annonce tardive sera-t-elle publiée ?","options":["Vendredi soir obligatoirement","Le mois suivant","Jamais","Avant son envoi"],"correct":"B","explanation":"Le passage indique : « Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant. » Cela justifie la réponse : Le mois suivant."},{"number":2,"points":3,"passage":"La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite.","question":"Pourquoi faut-il réserver ?","options":["L'accès est réservé aux journalistes","Les lecteurs doivent apporter un article","La réunion est payante","La capacité est limitée"],"correct":"D","explanation":"Le passage indique : « La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite. » Cela justifie la réponse : La capacité est limitée."},{"number":3,"points":3,"passage":"Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé.","question":"Quel usage est autorisé sous condition de citation ?","options":["Une attribution à un autre photographe","Toute publicité commerciale","Une vente sans accord","Un travail scolaire"],"correct":"D","explanation":"Le passage indique : « Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé. » Cela justifie la réponse : Un travail scolaire."},{"number":4,"points":3,"passage":"Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie.","question":"Où peut-on le consulter ?","options":["À la mairie","Au guichet de la piscine seulement","Dans chaque train","Uniquement dans les boîtes aux lettres"],"correct":"A","explanation":"Le passage indique : « Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie. » Cela justifie la réponse : À la mairie."},{"number":5,"points":9,"passage":"Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont.","question":"Quelle vérification est demandée ?","options":["La taille du fichier uniquement","Le nombre de photos du pont","La date de l'information","Le nom de tous les lecteurs"],"correct":"C","explanation":"Le passage indique : « Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont. » Cela justifie la réponse : La date de l'information."},{"number":6,"points":9,"passage":"Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus.","question":"Quelle étape est prévue ?","options":["Une publication automatique intégrale","Un vote sur son identité","Une diffusion sans contact préalable","Une confirmation avec le témoin"],"correct":"D","explanation":"Le passage indique : « Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus. » Cela justifie la réponse : Une confirmation avec le témoin."},{"number":7,"points":9,"passage":"J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre.","question":"Quel type de contenu est recherché ?","options":["Une annonce uniquement promotionnelle","Un portrait comportant des questions critiques","Un catalogue de prix sans entretien","Un texte rédigé par tous les clients"],"correct":"B","explanation":"Le passage indique : « J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre. » Cela justifie la réponse : Un portrait comportant des questions critiques."},{"number":8,"points":9,"passage":"Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace.","question":"Pourquoi séparer les espaces ?","options":["Supprimer les annonces de service","Rendre les informations urgentes plus visibles","Augmenter le nombre d'alertes sans distinction","Interdire toute discussion"],"correct":"B","explanation":"Le passage indique : « Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace. » Cela justifie la réponse : Rendre les informations urgentes plus visibles."},{"number":9,"points":9,"passage":"Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème.","question":"Quelle correction est demandée ?","options":["Le nom de l'association","Le sujet complet de l'article","Toutes les citations","La date de l'entretien"],"correct":"A","explanation":"Le passage indique : « Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème. » Cela justifie la réponse : Le nom de l'association."},{"number":10,"points":9,"passage":"Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants.","question":"Quelle limite est reconnue ?","options":["Seuls les élus peuvent témoigner","Un témoignage représente d'abord une expérience individuelle","Chaque récit décrit nécessairement toute la population","Les souvenirs doivent tous être identiques"],"correct":"B","explanation":"Le passage indique : « Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants. » Cela justifie la réponse : Un témoignage représente d'abord une expérience individuelle."},{"number":11,"points":15,"passage":"Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose.","question":"Quel intérêt présente cette publication ?","options":["Éviter toute lecture critique","Prouver que toute analyse est impossible","Permettre de vérifier le point de départ","Remplacer l'enquête par un titre"],"correct":"C","explanation":"Le passage indique : « Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose. » Cela justifie la réponse : Permettre de vérifier le point de départ."},{"number":12,"points":15,"passage":"Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse.","question":"Quelle information manque pour l'interpréter ?","options":["Le nom du fabricant du papier","Le moment de la prise de vue","Le prix de l'appareil","La largeur du cadre"],"correct":"B","explanation":"Le passage indique : « Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse. » Cela justifie la réponse : Le moment de la prise de vue."},{"number":13,"points":15,"passage":"Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles.","question":"Pourquoi afficher cette date ?","options":["Éviter une confusion temporelle","Augmenter le volume sonore","Interdire la rediffusion","Cacher l'origine du programme"],"correct":"A","explanation":"Le passage indique : « Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles. » Cela justifie la réponse : Éviter une confusion temporelle."},{"number":14,"points":15,"passage":"Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés.","question":"Quelle compétence est travaillée ?","options":["Désigner un titre sans lire","Éviter toute comparaison","Mémoriser tous les titres","Identifier un choix de présentation"],"correct":"D","explanation":"Le passage indique : « Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés. » Cela justifie la réponse : Identifier un choix de présentation."},{"number":15,"points":15,"passage":"Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments.","question":"Quelle distinction est rendue visible ?","options":["La taille des bureaux","Le poids du papier","La nature des textes publiés","La profession de tous les abonnés"],"correct":"C","explanation":"Le passage indique : « Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments. » Cela justifie la réponse : La nature des textes publiés."},{"number":16,"points":15,"passage":"Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article.","question":"Quel principe applique-t-il ?","options":["La transparence sur les rectifications","L'effacement de toute responsabilité","La suppression de toutes les archives","L'interdiction de signaler une erreur"],"correct":"A","explanation":"Le passage indique : « Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article. » Cela justifie la réponse : La transparence sur les rectifications."},{"number":17,"points":15,"passage":"Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets.","question":"Quelle démarche complète le communiqué ?","options":["Le refus de consulter les habitants","Le remplacement du projet par une rumeur","Le recueil de points de vue indépendants de l'annonce","La copie exacte de la publicité"],"correct":"C","explanation":"Le passage indique : « Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets. » Cela justifie la réponse : Le recueil de points de vue indépendants de l'annonce."},{"number":18,"points":15,"passage":"Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation.","question":"Quelle information aide à juger la portée du résultat ?","options":["La longueur du titre","Le prix de l'abonnement","La couleur du graphique","La taille du groupe interrogé"],"correct":"D","explanation":"Le passage indique : « Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation. » Cela justifie la réponse : La taille du groupe interrogé."},{"number":19,"points":15,"passage":"Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles.","question":"Pourquoi cette distinction importe-t-elle ?","options":["Une experte ne peut avoir aucune préférence","Le métier suffit à valider toute opinion","Toutes ses opinions n'ont pas le même fondement d'expertise","Les connaissances interdisent les questions"],"correct":"C","explanation":"Le passage indique : « Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles. » Cela justifie la réponse : Toutes ses opinions n'ont pas le même fondement d'expertise."},{"number":20,"points":21,"passage":"Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement.","question":"Quel équilibre cherche-t-il ?","options":["Réserver l'article aux spécialistes","Remplacer toutes les preuves par des slogans","Supprimer les informations importantes","Rendre le texte accessible sans effacer ses fondements"],"correct":"D","explanation":"Le passage indique : « Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. » Cela justifie la réponse : Rendre le texte accessible sans effacer ses fondements."},{"number":21,"points":21,"passage":"Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées.","question":"Pourquoi annoncer ces liens ?","options":["Éviter d'identifier les sujets","Remplacer les informations par des adhésions","Permettre au lecteur d'apprécier leur position","Garantir que toute critique sera supprimée"],"correct":"C","explanation":"Le passage indique : « Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. » Cela justifie la réponse : Permettre au lecteur d'apprécier leur position."},{"number":22,"points":21,"passage":"Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion.","question":"Quelle place est donnée aux lecteurs ?","options":["Supprimer les vérifications","Remplacer tous les journalistes","Décider du résultat avant l'enquête","Contribuer aux questions à examiner"],"correct":"D","explanation":"Le passage indique : « Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. » Cela justifie la réponse : Contribuer aux questions à examiner."},{"number":23,"points":21,"passage":"Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution.","question":"Quel problème est identifié ?","options":["Un contexte ajouté de manière erronée","Une image entièrement inventée nécessairement","Une absence de toute scène visible","Une qualité technique trop faible uniquement"],"correct":"A","explanation":"Le passage indique : « Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. » Cela justifie la réponse : Un contexte ajouté de manière erronée."},{"number":24,"points":21,"passage":"Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information.","question":"Quelle différence est faite ?","options":["Une identité connue doit toujours être publiée","La protection d'une source interdit tout entretien","L'anonymat impose de ne rien vérifier","Anonymat public et absence de vérification ne se confondent pas"],"correct":"D","explanation":"Le passage indique : « Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. » Cela justifie la réponse : Anonymat public et absence de vérification ne se confondent pas."},{"number":25,"points":21,"passage":"Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue.","question":"Quelle déduction faut-il éviter ?","options":["Confondre popularité et fiabilité","Observer la diffusion d'un message","Comparer plusieurs documents","Rechercher une source"],"correct":"A","explanation":"Le passage indique : « Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue. » Cela justifie la réponse : Confondre popularité et fiabilité."},{"number":26,"points":21,"passage":"Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation.","question":"Quelle est la portée du reportage ?","options":["Garantir une moyenne statistique nationale","Supprimer toute singularité","Approfondir un cas sans le rendre universel","Mesurer toutes les familles du pays"],"correct":"C","explanation":"Le passage indique : « Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation. » Cela justifie la réponse : Approfondir un cas sans le rendre universel."},{"number":27,"points":21,"passage":"Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances.","question":"Quel critère dépasse l'égalité du temps de parole ?","options":["La solidité et la place des arguments dans le savoir disponible","La longueur des biographies","Le nombre de spectateurs seulement","La couleur du studio"],"correct":"A","explanation":"Le passage indique : « Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances. » Cela justifie la réponse : La solidité et la place des arguments dans le savoir disponible."},{"number":28,"points":21,"passage":"Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables.","question":"Quel objectif est poursuivi ?","options":["Remplacer toutes les enquêtes par des titres","Interdire la lecture complète","Supprimer les documents annexes","Offrir plusieurs niveaux de lecture"],"correct":"D","explanation":"Le passage indique : « Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables. » Cela justifie la réponse : Offrir plusieurs niveaux de lecture."},{"number":29,"points":21,"passage":"Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif.","question":"Quelle information rend le processus plus lisible ?","options":["Le nombre de feuilles utilisées","Les choix écartés et leur justification","La météo de la réunion","Uniquement la liste des absents"],"correct":"B","explanation":"Le passage indique : « Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif. » Cela justifie la réponse : Les choix écartés et leur justification."},{"number":30,"points":26,"passage":"Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué.","question":"Quelle précaution est recommandée ?","options":["Faire confiance au format court","Compter seulement les caractères","Lire le contexte de la citation","Remplacer les mots par une image"],"correct":"C","explanation":"Le passage indique : « Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué. » Cela justifie la réponse : Lire le contexte de la citation."},{"number":31,"points":26,"passage":"La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite.","question":"Quel arbitrage est assumé ?","options":["Publier d'abord toutes les rumeurs","Privilégier une vérification nécessaire sur l'immédiateté","Supprimer toute information récente","Confondre attente et censure automatique"],"correct":"B","explanation":"Le passage indique : « La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite. » Cela justifie la réponse : Privilégier une vérification nécessaire sur l'immédiateté."},{"number":32,"points":26,"passage":"Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie.","question":"Quelle vigilance est demandée ?","options":["Examiner la construction visuelle du graphique","Déduire une cause de la seule couleur","Ignorer les valeurs indiquées","Rejeter tous les graphiques"],"correct":"A","explanation":"Le passage indique : « Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie. » Cela justifie la réponse : Examiner la construction visuelle du graphique."},{"number":33,"points":26,"passage":"Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts.","question":"Quelle tension est décrite ?","options":["Proximité utile et indépendance éditoriale","Publicité et coût du papier uniquement","Lecture et absence de documents","Distance géographique et vitesse du courrier"],"correct":"A","explanation":"Le passage indique : « Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts. » Cela justifie la réponse : Proximité utile et indépendance éditoriale."},{"number":34,"points":26,"passage":"Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation.","question":"Quel enjeu dépasse la simple publication d'un correctif ?","options":["Effacer toutes les archives exactes","Modifier uniquement la date du journal","Faire parvenir la correction aux personnes exposées","Interdire les réactions des lecteurs"],"correct":"C","explanation":"Le passage indique : « Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation. » Cela justifie la réponse : Faire parvenir la correction aux personnes exposées."},{"number":35,"points":26,"passage":"Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer.","question":"Quelle démarche est défendue ?","options":["Croiser des formes de preuve aux portées différentes","Considérer toutes les informations comme identiques","Remplacer les sources par une seule émotion","Transformer chaque témoignage en statistique nationale"],"correct":"A","explanation":"Le passage indique : « Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer. » Cela justifie la réponse : Croiser des formes de preuve aux portées différentes."},{"number":36,"points":33,"passage":"Une rédaction veut représenter équitablement un débat. Elle invite les acteurs les plus visibles, puis découvre que certains habitants directement concernés ne disposent d'aucun porte-parole organisé. La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation.","question":"Que doit-elle corriger ?","options":["La vérification des déclarations","La sélection de voix fondée uniquement sur leur visibilité","La présence des habitants concernés","L'existence de tout débat"],"correct":"B","explanation":"Le passage indique : « La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation. » Cela justifie la réponse : La sélection de voix fondée uniquement sur leur visibilité."},{"number":37,"points":33,"passage":"Un média explique ses choix de sujets. Certains lecteurs y voient un aveu de subjectivité qui invaliderait toute information. La rédaction répond que sélectionner est inévitable, mais que les critères peuvent être discutés et les faits vérifiés. Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent.","question":"Quelle idée défend la rédaction ?","options":["Toute sélection rend la vérification inutile","Les faits changent selon le prix du journal","L'absence d'explication garantit la neutralité","Des choix éditoriaux explicites peuvent coexister avec la rigueur"],"correct":"D","explanation":"Le passage indique : « Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent. » Cela justifie la réponse : Des choix éditoriaux explicites peuvent coexister avec la rigueur."},{"number":38,"points":33,"passage":"Une campagne de communication cherche un message très simple. Les responsables retirent successivement les réserves jusqu'à produire une promesse plus forte que le projet réel. La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce.","question":"Quelle limite de la simplification est soulignée ?","options":["Elle exige toujours de supprimer les réserves","Elle doit préserver les conditions essentielles de la promesse","Elle remplace la réalisation du projet","Elle interdit tout message court"],"correct":"B","explanation":"Le passage indique : « La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce. » Cela justifie la réponse : Elle doit préserver les conditions essentielles de la promesse."},{"number":39,"points":33,"passage":"Les plateformes recommandent souvent des contenus suscitant une réaction rapide. Une enquête complexe demande au contraire du temps avant de produire une conclusion. Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive.","question":"Quel effet du critère d'évaluation est envisagé ?","options":["Une meilleure vérification automatique des faits","Une durée de lecture identique pour tous les contenus","Une moindre visibilité de certains travaux approfondis","Une disparition de toutes les réactions rapides"],"correct":"C","explanation":"Le passage indique : « Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive. » Cela justifie la réponse : Une moindre visibilité de certains travaux approfondis."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-15','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-15","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 15","topic":"Économie, achats et services","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement.","question":"Quelle possibilité est annoncée ?","options":["Un remboursement sans ticket","Un échange sans limite de temps","Une reprise par n'importe quel magasin","Un échange sous conditions"],"correct":"D","explanation":"Le passage indique : « Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement. » Cela justifie la réponse : Un échange sous conditions."},{"number":2,"points":3,"passage":"Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul.","question":"Que se passe-t-il si la demande change ?","options":["Le prix doit être recalculé","Le devis initial s'applique toujours","Le service devient gratuit","Le délai disparaît"],"correct":"A","explanation":"Le passage indique : « Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul. » Cela justifie la réponse : Le prix doit être recalculé."},{"number":3,"points":3,"passage":"Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place.","question":"Où retirer une commande ?","options":["Chez un commerçant voisin","À la caisse principale obligatoirement","Dans l'atelier fermé","À l'arrière du magasin"],"correct":"D","explanation":"Le passage indique : « Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place. » Cela justifie la réponse : À l'arrière du magasin."},{"number":4,"points":3,"passage":"La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse.","question":"Quelle action est attendue du client ?","options":["Remplacer lui-même toutes les pièces","Envoyer une publicité","Accepter ou refuser le devis","Venir chercher une commande déjà achevée"],"correct":"C","explanation":"Le passage indique : « La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse. » Cela justifie la réponse : Accepter ou refuser le devis."},{"number":5,"points":9,"passage":"J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service.","question":"Pourquoi ce choix est-il fait ?","options":["Payer nécessairement le moins cher sur douze mois","Limiter la durée d'engagement","Obtenir un contrat définitif","Éviter toute facture"],"correct":"B","explanation":"Le passage indique : « J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service. » Cela justifie la réponse : Limiter la durée d'engagement."},{"number":6,"points":9,"passage":"Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer.","question":"Quelle adaptation est proposée ?","options":["Une livraison gratuite à l'étranger","Un délai de retrait prolongé","Une annulation automatique","Un achat supplémentaire obligatoire"],"correct":"B","explanation":"Le passage indique : « Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer. » Cela justifie la réponse : Un délai de retrait prolongé."},{"number":7,"points":9,"passage":"Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ?","question":"Quelle information est recherchée ?","options":["L'ensemble des frais liés au contrat","Le nombre de publicités","La couleur du matériel","Le prix du premier mois uniquement"],"correct":"A","explanation":"Le passage indique : « Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ? » Cela justifie la réponse : L'ensemble des frais liés au contrat."},{"number":8,"points":9,"passage":"La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité.","question":"Que doit faire le client intéressé ?","options":["Venir sans signaler son besoin","Attendre la fin de la réparation","Demander le prêt dès le dépôt","Acheter un appareil neuf obligatoirement"],"correct":"C","explanation":"Le passage indique : « La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité. » Cela justifie la réponse : Demander le prêt dès le dépôt."},{"number":9,"points":9,"passage":"Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production.","question":"Quelle solution évite les commandes multiples ?","options":["Commander trois tailles","Produire sans connaître les dimensions","Attendre le retour de tous les clients","Mesurer avant fabrication"],"correct":"D","explanation":"Le passage indique : « Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production. » Cela justifie la réponse : Mesurer avant fabrication."},{"number":10,"points":9,"passage":"La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas.","question":"Quel changement est annoncé ?","options":["Une suppression de la main-d'œuvre","Une hausse automatique","Une présentation plus détaillée","Une réduction des fournitures"],"correct":"C","explanation":"Le passage indique : « La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas. » Cela justifie la réponse : Une présentation plus détaillée."},{"number":11,"points":15,"passage":"Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées.","question":"Quelle information accompagne la vente ?","options":["L'historique des réparations effectuées","La liste des anciens utilisateurs","Une promesse de fonctionnement éternel","Le prix de tous les objets neufs"],"correct":"A","explanation":"Le passage indique : « Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées. » Cela justifie la réponse : L'historique des réparations effectuées."},{"number":12,"points":15,"passage":"Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes.","question":"Quel objectif poursuit cet affichage ?","options":["Comparer uniquement les couleurs","Faciliter une comparaison homogène","Éviter de montrer les prix","Garantir que la plus grosse bouteille coûte moins cher"],"correct":"B","explanation":"Le passage indique : « Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes. » Cela justifie la réponse : Faciliter une comparaison homogène."},{"number":13,"points":15,"passage":"Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur.","question":"Quelle est la limite de l'accompagnement ?","options":["L'association signe tous les contrats","Tous les fournisseurs sont exclus","Le consommateur doit changer d'offre","La décision reste au consommateur"],"correct":"D","explanation":"Le passage indique : « Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur. » Cela justifie la réponse : La décision reste au consommateur."},{"number":14,"points":15,"passage":"Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées.","question":"Quelle information est importante ?","options":["L'autorisation du client n'a aucun rôle","Tout n'est pas inclus dans le forfait","Le forfait interdit les interventions","Chaque réparation est nécessairement gratuite"],"correct":"B","explanation":"Le passage indique : « Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées. » Cela justifie la réponse : Tout n'est pas inclus dans le forfait."},{"number":15,"points":15,"passage":"Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés.","question":"Quel avantage économique est recherché ?","options":["Supprimer toutes les réservations","Acheter une machine pour chaque heure","Mieux utiliser un équipement commun","Réduire les compétences nécessaires"],"correct":"C","explanation":"Le passage indique : « Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés. » Cela justifie la réponse : Mieux utiliser un équipement commun."},{"number":16,"points":15,"passage":"Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites.","question":"Que peut attendre le client ?","options":["Un nettoyage inclus","Un achat définitif","La possibilité de découper le vêtement","Une fabrication sur mesure automatique"],"correct":"A","explanation":"Le passage indique : « Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites. » Cela justifie la réponse : Un nettoyage inclus."},{"number":17,"points":15,"passage":"Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic.","question":"Quelle démarche adopte-t-il ?","options":["Identifier la cause avant d'engager une dépense","Changer immédiatement tout l'appareil","Vendre uniquement du matériel neuf","Garantir une panne précise sans examen"],"correct":"A","explanation":"Le passage indique : « Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic. » Cela justifie la réponse : Identifier la cause avant d'engager une dépense."},{"number":18,"points":15,"passage":"Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue.","question":"À quoi sert l'acompte ?","options":["Garantir l'absence de toute facture","Payer un service déjà terminé uniquement","Supprimer le montant final","Financer une partie de la préparation"],"correct":"D","explanation":"Le passage indique : « Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue. » Cela justifie la réponse : Financer une partie de la préparation."},{"number":19,"points":15,"passage":"Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète.","question":"Quelle limite est reconnue ?","options":["Le contrôle ne garantit pas tous les aspects techniques","Aucune observation n'est réalisée","Les objets sont tous neufs","Le prix assure automatiquement la sécurité"],"correct":"A","explanation":"Le passage indique : « Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète. » Cela justifie la réponse : Le contrôle ne garantit pas tous les aspects techniques."},{"number":20,"points":21,"passage":"Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités.","question":"Quelle condition faut-il examiner ?","options":["L'adéquation entre quantité achetée et besoin","La musique diffusée","Le nombre de caisses du magasin","La taille de l'affiche"],"correct":"A","explanation":"Le passage indique : « Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. » Cela justifie la réponse : L'adéquation entre quantité achetée et besoin."},{"number":21,"points":21,"passage":"Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles.","question":"Quel compromis est proposé ?","options":["Un retrait obligatoire à l'usine","Moins de rapidité contre une meilleure organisation","Une suppression de tous les délais","Une livraison immédiate garantie partout"],"correct":"B","explanation":"Le passage indique : « Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. » Cela justifie la réponse : Moins de rapidité contre une meilleure organisation."},{"number":22,"points":21,"passage":"Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun.","question":"Quelle obligation accompagne cette organisation ?","options":["Vendre tous les objets au même prix","Abandonner son propre atelier","Participer à la tenue de la boutique","Refuser les nouveaux clients"],"correct":"C","explanation":"Le passage indique : « Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. » Cela justifie la réponse : Participer à la tenue de la boutique."},{"number":23,"points":21,"passage":"Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur.","question":"Quel critère complète le prix d'achat ?","options":["Le nombre de slogans","La date des publicités","La possibilité d'entretenir le produit","Le volume de l'emballage seulement"],"correct":"C","explanation":"Le passage indique : « Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. » Cela justifie la réponse : La possibilité d'entretenir le produit."},{"number":24,"points":21,"passage":"Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement.","question":"Quelle ambition est précisée ?","options":["Interdire la monnaie habituelle","Supprimer les prix","Obliger tous les magasins à participer","Soutenir certains échanges de proximité"],"correct":"D","explanation":"Le passage indique : « Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. » Cela justifie la réponse : Soutenir certains échanges de proximité."},{"number":25,"points":21,"passage":"Un service de réservation facture une annulation tardive. Il explique cette règle avant paiement, car le créneau ne peut pas toujours être attribué à un autre client.","question":"Quel motif justifie la règle annoncée ?","options":["L'absence de toute réservation","La volonté de réduire les informations","La gratuité du service","La perte possible d'un créneau réservé"],"correct":"D","explanation":"Le passage indique : « Un service de réservation facture une annulation tardive. Il explique cette règle avant paiement, car le créneau ne peut pas toujours être attribué à un autre client. » Cela justifie la réponse : La perte possible d'un créneau réservé."},{"number":26,"points":21,"passage":"Une entreprise annonce une hausse de prix et décrit les coûts concernés. Certains clients restent mécontents, mais peuvent comparer les raisons données plutôt que découvrir un montant sans explication.","question":"Quel apport fournit cette démarche ?","options":["Une interdiction de comparer les offres","Une satisfaction garantie de tous","Une disparition de la hausse","Une base de compréhension et de discussion"],"correct":"D","explanation":"Le passage indique : « Une entreprise annonce une hausse de prix et décrit les coûts concernés. Certains clients restent mécontents, mais peuvent comparer les raisons données plutôt que découvrir un montant sans explication. » Cela justifie la réponse : Une base de compréhension et de discussion."},{"number":27,"points":21,"passage":"Une étude de satisfaction reçoit surtout les réponses des clients très contents ou très déçus. Le commerce ajoute des entretiens courts avec des acheteurs ordinaires.","question":"Pourquoi compléter l'enquête ?","options":["Supprimer les critiques reçues","Garantir une note parfaite","Mieux représenter des expériences moins exprimées","Interdire les avis favorables"],"correct":"C","explanation":"Le passage indique : « Une étude de satisfaction reçoit surtout les réponses des clients très contents ou très déçus. Le commerce ajoute des entretiens courts avec des acheteurs ordinaires. » Cela justifie la réponse : Mieux représenter des expériences moins exprimées."},{"number":28,"points":21,"passage":"Une offre gratuite est financée par la publicité. Les utilisateurs ne paient pas directement, mais leur attention intéresse les annonceurs.","question":"Quelle source économique est identifiée ?","options":["Les revenus publicitaires","L'absence totale de financement","Le remboursement des utilisateurs","Une vente obligatoire d'objets"],"correct":"A","explanation":"Le passage indique : « Une offre gratuite est financée par la publicité. Les utilisateurs ne paient pas directement, mais leur attention intéresse les annonceurs. » Cela justifie la réponse : Les revenus publicitaires."},{"number":29,"points":21,"passage":"Un commerçant préfère une petite gamme suivie à un choix très vaste souvent indisponible. Il veut rendre plus fiables les promesses de stock.","question":"Quel avantage recherche-t-il ?","options":["Une absence de relations avec les fournisseurs","Une meilleure disponibilité des références proposées","Un nombre maximal d'articles affichés sans stock","Une réduction des informations de prix"],"correct":"B","explanation":"Le passage indique : « Un commerçant préfère une petite gamme suivie à un choix très vaste souvent indisponible. Il veut rendre plus fiables les promesses de stock. » Cela justifie la réponse : Une meilleure disponibilité des références proposées."},{"number":30,"points":26,"passage":"Le coût d'un produit comprend parfois des dépenses reportées : consommables, entretien et remplacement d'accessoires. Un prix de départ attractif ne suffit donc pas à juger une offre. Comparer suppose de définir une durée et des usages vraisemblables.","question":"Quelle méthode est recommandée ?","options":["Additionner toutes les publicités","Évaluer le coût dans les conditions d'utilisation prévues","Regarder seulement le prix du premier jour","Choisir l'emballage le plus grand"],"correct":"B","explanation":"Le passage indique : « Le coût d'un produit comprend parfois des dépenses reportées : consommables, entretien et remplacement d'accessoires. Un prix de départ attractif ne suffit donc pas à juger une offre. Comparer suppose de définir une durée et des usages vraisemblables. » Cela justifie la réponse : Évaluer le coût dans les conditions d'utilisation prévues."},{"number":31,"points":26,"passage":"Une entreprise mesure le service client par la durée moyenne des appels. Les employés raccourcissent les échanges, mais les mêmes personnes rappellent davantage. L'amélioration apparente d'un indicateur peut donc masquer une résolution moins efficace des problèmes.","question":"Quelle limite de l'indicateur apparaît ?","options":["Un appel court n'est pas forcément un problème résolu","La durée ne peut jamais être mesurée","Les rappels prouvent une satisfaction parfaite","Tous les appels longs sont inutiles"],"correct":"A","explanation":"Le passage indique : « Une entreprise mesure le service client par la durée moyenne des appels. Les employés raccourcissent les échanges, mais les mêmes personnes rappellent davantage. L'amélioration apparente d'un indicateur peut donc masquer une résolution moins efficace des problèmes. » Cela justifie la réponse : Un appel court n'est pas forcément un problème résolu."},{"number":32,"points":26,"passage":"Un magasin affirme pratiquer des prix équitables. Pour rendre l'engagement compréhensible, il explique la répartition du prix entre production, transport et distribution. Une formule valorisante devient plus informative lorsqu'elle renvoie à des éléments que l'on peut examiner.","question":"Qu'est-ce qui renforce la crédibilité de l'annonce ?","options":["L'absence de toute comparaison","La répétition du mot équitable uniquement","Un logo sans information","Des explications sur les mécanismes du prix"],"correct":"D","explanation":"Le passage indique : « Un magasin affirme pratiquer des prix équitables. Pour rendre l'engagement compréhensible, il explique la répartition du prix entre production, transport et distribution. Une formule valorisante devient plus informative lorsqu'elle renvoie à des éléments que l'on peut examiner. » Cela justifie la réponse : Des explications sur les mécanismes du prix."},{"number":33,"points":26,"passage":"Un service de location réduit l'achat individuel d'équipements rarement utilisés. Son intérêt dépend toutefois de la durée de vie du matériel et des déplacements nécessaires. Le partage constitue une possibilité d'économie, pas une garantie indépendante de son organisation.","question":"Quelle approche du partage est proposée ?","options":["Compter uniquement les inscriptions","Évaluer ses conditions concrètes de fonctionnement","Le rejeter dès qu'un trajet existe","Le considérer toujours bénéfique sans examen"],"correct":"B","explanation":"Le passage indique : « Un service de location réduit l'achat individuel d'équipements rarement utilisés. Son intérêt dépend toutefois de la durée de vie du matériel et des déplacements nécessaires. Le partage constitue une possibilité d'économie, pas une garantie indépendante de son organisation. » Cela justifie la réponse : Évaluer ses conditions concrètes de fonctionnement."},{"number":34,"points":26,"passage":"Une boutique veut fidéliser ses clients par des réductions fréquentes. Certains attendent alors systématiquement la prochaine promotion. Le mécanisme qui devait stimuler l'achat immédiat transforme la perception du prix habituel et peut ralentir les ventes entre deux offres.","question":"Quel effet imprévu est décrit ?","options":["Les prix deviennent identiques partout","Les clients ne voient plus les promotions","La fidélité supprime toutes les attentes","Les promotions incitent à différer certains achats"],"correct":"D","explanation":"Le passage indique : « Une boutique veut fidéliser ses clients par des réductions fréquentes. Certains attendent alors systématiquement la prochaine promotion. Le mécanisme qui devait stimuler l'achat immédiat transforme la perception du prix habituel et peut ralentir les ventes entre deux offres. » Cela justifie la réponse : Les promotions incitent à différer certains achats."},{"number":35,"points":26,"passage":"Un contrat standard facilite la vente rapide. Mais lorsqu'une situation particulière apparaît, le client doit pouvoir comprendre ses options. Une entreprise forme donc ses équipes à expliquer les clauses plutôt qu'à renvoyer systématiquement vers un document difficile à lire.","question":"Quel besoin complète la standardisation ?","options":["Une disparition des contrats","Une interdiction de poser des questions","Une capacité d'explication adaptée","Une signature sans information"],"correct":"C","explanation":"Le passage indique : « Un contrat standard facilite la vente rapide. Mais lorsqu'une situation particulière apparaît, le client doit pouvoir comprendre ses options. Une entreprise forme donc ses équipes à expliquer les clauses plutôt qu'à renvoyer systématiquement vers un document difficile à lire. » Cela justifie la réponse : Une capacité d'explication adaptée."},{"number":36,"points":33,"passage":"Une plateforme classe les offres selon leur popularité. Les nouveaux fournisseurs, encore peu visibles, ont alors moins de chances d'obtenir les achats qui amélioreraient leur classement. Un indicateur censé refléter le succès peut aussi contribuer à reproduire l'avantage de ceux qui sont déjà installés.","question":"Quel mécanisme est mis en évidence ?","options":["Un prix identique pour toutes les offres","Une disparition de tout classement","Un renforcement circulaire de la visibilité","Une égalité automatique entre anciens et nouveaux"],"correct":"C","explanation":"Le passage indique : « Un indicateur censé refléter le succès peut aussi contribuer à reproduire l'avantage de ceux qui sont déjà installés. » Cela justifie la réponse : Un renforcement circulaire de la visibilité."},{"number":37,"points":33,"passage":"Une entreprise revendique un service rapide en supprimant certaines étapes de contrôle. Les délais diminuent, mais les retours augmentent. Elle doit comparer le gain initial au travail supplémentaire causé par les erreurs. L'efficacité ne se mesure pas toujours au temps économisé à une seule étape du parcours.","question":"Quel bilan faut-il réaliser ?","options":["Un comptage limité à la première livraison","Un bilan du processus entier","Une mesure du seul emballage","Une suppression des données sur les retours"],"correct":"B","explanation":"Le passage indique : « L'efficacité ne se mesure pas toujours au temps économisé à une seule étape du parcours. » Cela justifie la réponse : Un bilan du processus entier."},{"number":38,"points":33,"passage":"Un consommateur choisit un article durable pour limiter ses achats. Les campagnes du fabricant l'encouragent néanmoins à le remplacer souvent pour suivre de nouvelles versions. La durée de vie technique d'un produit ne garantit pas sa durée réelle d'usage si les pratiques commerciales poussent à son renouvellement.","question":"Quelle distinction le texte souligne-t-il ?","options":["Durabilité de l'objet et durée de conservation par l'utilisateur","Prix initial et poids du carton uniquement","Nouveauté et qualité nécessairement supérieure","Garantie et absence de toute réparation"],"correct":"A","explanation":"Le passage indique : « La durée de vie technique d'un produit ne garantit pas sa durée réelle d'usage si les pratiques commerciales poussent à son renouvellement. » Cela justifie la réponse : Durabilité de l'objet et durée de conservation par l'utilisateur."},{"number":39,"points":33,"passage":"Une entreprise associe des clients à la conception d'un service. Les participants les plus disponibles ne représentent pas tous les futurs usagers. L'équipe cherche donc d'autres retours avant de stabiliser le projet. La participation fournit des informations précieuses sans supprimer la question de ceux qui n'ont pas pu participer.","question":"Quelle précaution méthodologique est prise ?","options":["Fixer le service avant toute observation","Élargir les retours au-delà du groupe volontaire","Considérer les volontaires comme parfaitement représentatifs","Écarter toutes les contributions des clients"],"correct":"B","explanation":"Le passage indique : « La participation fournit des informations précieuses sans supprimer la question de ceux qui n'ont pas pu participer. » Cela justifie la réponse : Élargir les retours au-delà du groupe volontaire."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-16','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-16","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 16","topic":"Patrimoine, architecture et vie urbaine","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures.","question":"Quel espace ouvre le matin ?","options":["La tour","La salle haute","Le toit","La cour"],"correct":"D","explanation":"Le passage indique : « La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures. » Cela justifie la réponse : La cour."},{"number":2,"points":3,"passage":"La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée.","question":"Que faut-il laisser au vestiaire ?","options":["La pièce d'identité","Le billet de visite","Les sacs","Les lunettes"],"correct":"C","explanation":"Le passage indique : « La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée. » Cela justifie la réponse : Les sacs."},{"number":3,"points":3,"passage":"Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud.","question":"Quelle direction faut-il prendre ?","options":["Le passage fermé","Le sommet des remparts","La sortie sans panneau","La porte sud"],"correct":"D","explanation":"Le passage indique : « Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud. » Cela justifie la réponse : La porte sud."},{"number":4,"points":3,"passage":"L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation.","question":"Quel service exige toujours une réservation ?","options":["L'accès à toutes les rues","La visite accompagnée","La lecture des panneaux","L'entrée libre à l'exposition"],"correct":"B","explanation":"Le passage indique : « L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation. » Cela justifie la réponse : La visite accompagnée."},{"number":5,"points":9,"passage":"J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville.","question":"Pourquoi choisir cette visite ?","options":["Acheter une usine","Revoir uniquement le château","Éviter toute activité culturelle","Découvrir une histoire moins familière"],"correct":"D","explanation":"Le passage indique : « J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville. » Cela justifie la réponse : Découvrir une histoire moins familière."},{"number":6,"points":9,"passage":"Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade.","question":"À quoi servira la photo ?","options":["Prouver la propriété d'un bâtiment","Observer les transformations du quartier","Remplacer la carte de transport","Décorer uniquement la salle d'accueil"],"correct":"B","explanation":"Le passage indique : « Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade. » Cela justifie la réponse : Observer les transformations du quartier."},{"number":7,"points":9,"passage":"La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée.","question":"Quel élément est conservé ?","options":["Le projet présenté","Le numéro de téléphone uniquement","L'horaire initial","La date de publication du bulletin"],"correct":"A","explanation":"Le passage indique : « La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée. » Cela justifie la réponse : Le projet présenté."},{"number":8,"points":9,"passage":"Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe.","question":"Comment obtenir ce matériel ?","options":["Le retirer dans la boutique voisine","Acheter une place assise spéciale","Le demander à l'accueil","Attendre la fin du parcours"],"correct":"C","explanation":"Le passage indique : « Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe. » Cela justifie la réponse : Le demander à l'accueil."},{"number":9,"points":9,"passage":"Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat.","question":"Quel besoin guide ce choix ?","options":["Exposer un travail déjà terminé","Gagner un prix dès la première séance","Éviter toute pratique","Se former sans compétition"],"correct":"D","explanation":"Le passage indique : « Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat. » Cela justifie la réponse : Se former sans compétition."},{"number":10,"points":9,"passage":"Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit.","question":"Qui peut contribuer ?","options":["Une personne ayant un souvenir à raconter","Uniquement un propriétaire d'archives papier","Un vendeur de matériel audio","Seulement un historien diplômé"],"correct":"A","explanation":"Le passage indique : « Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit. » Cela justifie la réponse : Une personne ayant un souvenir à raconter."},{"number":11,"points":15,"passage":"Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs.","question":"Quel type de transformation est réalisé ?","options":["Une fermeture au public","Un nouvel usage respectant des éléments du bâtiment","Une démolition complète","Un retour obligatoire au commerce d'origine"],"correct":"B","explanation":"Le passage indique : « Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs. » Cela justifie la réponse : Un nouvel usage respectant des éléments du bâtiment."},{"number":12,"points":15,"passage":"Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives.","question":"Quelle information complète les sources officielles ?","options":["La taille des dossiers municipaux","Les horaires des magasins uniquement","La mémoire des pratiques locales","Le prix des panneaux routiers"],"correct":"C","explanation":"Le passage indique : « Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives. » Cela justifie la réponse : La mémoire des pratiques locales."},{"number":13,"points":15,"passage":"Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble.","question":"Quel critère guide le choix ?","options":["La compatibilité avec les matériaux existants","La dureté maximale à tout prix","La rapidité de la publicité","La couleur de l'emballage"],"correct":"A","explanation":"Le passage indique : « Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble. » Cela justifie la réponse : La compatibilité avec les matériaux existants."},{"number":14,"points":15,"passage":"Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent.","question":"Quel compromis est recherché ?","options":["Éteindre tous les services publics","Augmenter la puissance partout","Rendre les monuments invisibles en journée","Maintenir la visibilité avec moins d'éclairage"],"correct":"D","explanation":"Le passage indique : « Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent. » Cela justifie la réponse : Maintenir la visibilité avec moins d'éclairage."},{"number":15,"points":15,"passage":"Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères.","question":"Que souhaite transmettre l'aménagement ?","options":["Uniquement des conseils de jardinage","Une compréhension de l'histoire du lieu","Une interdiction de marcher","Le programme des trains actuels"],"correct":"B","explanation":"Le passage indique : « Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères. » Cela justifie la réponse : Une compréhension de l'histoire du lieu."},{"number":16,"points":15,"passage":"Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées.","question":"Quel aspect du patrimoine est complété ?","options":["Le stock de produits à vendre","Les plans des parkings actuels","La mémoire du travail vécu","Les tarifs des visites"],"correct":"C","explanation":"Le passage indique : « Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées. » Cela justifie la réponse : La mémoire du travail vécu."},{"number":17,"points":15,"passage":"Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques.","question":"Quels besoins sont associés ?","options":["Démolition et publicité","Accessibilité et préservation","Stationnement et circulation rapide","Fermeture et abandon"],"correct":"B","explanation":"Le passage indique : « Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques. » Cela justifie la réponse : Accessibilité et préservation."},{"number":18,"points":15,"passage":"Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence.","question":"Quelle précaution est demandée ?","options":["Vérifier la fonction de la fontaine","Boire à toutes les fontaines décoratives","Ignorer les indications","Se fier uniquement à la forme"],"correct":"A","explanation":"Le passage indique : « Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence. » Cela justifie la réponse : Vérifier la fonction de la fontaine."},{"number":19,"points":15,"passage":"Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens.","question":"Quelle idée défend-elle ?","options":["Des constructions récentes méritent aussi d'être comprises","Les quartiers modernes sont tous identiques","Les promenades doivent éviter les habitants","Seuls les châteaux ont une histoire"],"correct":"A","explanation":"Le passage indique : « Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens. » Cela justifie la réponse : Des constructions récentes méritent aussi d'être comprises."},{"number":20,"points":21,"passage":"Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence.","question":"À quoi a servi l'essai ?","options":["Confirmer automatiquement le premier plan","Éviter toute consultation","Observer les usages avant de fixer l'aménagement","Réduire le nombre d'arbres sans raison"],"correct":"C","explanation":"Le passage indique : « Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. » Cela justifie la réponse : Observer les usages avant de fixer l'aménagement."},{"number":21,"points":21,"passage":"Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres.","question":"Quelle évolution du regard est proposée ?","options":["Inclure des acteurs longtemps peu visibles","Remplacer l'histoire par une liste de prix","Présenter uniquement les visiteurs actuels","Supprimer toute information sur le palais"],"correct":"A","explanation":"Le passage indique : « Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. » Cela justifie la réponse : Inclure des acteurs longtemps peu visibles."},{"number":22,"points":21,"passage":"Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique.","question":"Pourquoi ajouter des informations ?","options":["Éviter de mentionner son origine","Préserver le sens de l'objet conservé","Augmenter automatiquement sa valeur","Garantir la réouverture du commerce"],"correct":"B","explanation":"Le passage indique : « Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. » Cela justifie la réponse : Préserver le sens de l'objet conservé."},{"number":23,"points":21,"passage":"Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie.","question":"Quelle position adoptent-ils ?","options":["Réserver la place aux voitures","Interdire toute présence humaine","Accepter toute nuisance","Organiser les usages plutôt que les supprimer"],"correct":"D","explanation":"Le passage indique : « Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. » Cela justifie la réponse : Organiser les usages plutôt que les supprimer."},{"number":24,"points":21,"passage":"La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs.","question":"Quelle priorité pratique demeure ?","options":["Transformer tous les quais en exposition","Permettre aux usagers de se repérer","Limiter l'accès aux historiens","Supprimer les horaires"],"correct":"B","explanation":"Le passage indique : « La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. » Cela justifie la réponse : Permettre aux usagers de se repérer."},{"number":25,"points":21,"passage":"Une archive montre un projet jamais construit. Les médiateurs le présentent comme une intention de l'époque, pas comme la preuve d'un état ancien de la ville.","question":"Quelle distinction est nécessaire ?","options":["Un projet dessiné n'est pas une réalisation","Tout dessin correspond à un bâtiment disparu","La ville n'a connu aucun changement","Une archive ne peut jamais être utile"],"correct":"A","explanation":"Le passage indique : « Une archive montre un projet jamais construit. Les médiateurs le présentent comme une intention de l'époque, pas comme la preuve d'un état ancien de la ville. » Cela justifie la réponse : Un projet dessiné n'est pas une réalisation."},{"number":26,"points":21,"passage":"Une rue reçoit des revêtements moins glissants à proximité d'un monument. L'équipe cherche une solution visuellement discrète, mais refuse que l'apparence rende le passage dangereux.","question":"Quel équilibre est recherché ?","options":["La suppression de tous les visiteurs","Une imitation des défauts anciens","Un décor sans fonction","Compatibilité visuelle et sécurité d'usage"],"correct":"D","explanation":"Le passage indique : « Une rue reçoit des revêtements moins glissants à proximité d'un monument. L'équipe cherche une solution visuellement discrète, mais refuse que l'apparence rende le passage dangereux. » Cela justifie la réponse : Compatibilité visuelle et sécurité d'usage."},{"number":27,"points":21,"passage":"Une maison d'artiste conserve plusieurs pièces intactes et transforme une autre en espace d'accueil. Le projet distingue les besoins de présentation des conditions nécessaires à la visite.","question":"Pourquoi cette transformation limitée ?","options":["Accueillir le public sans modifier toutes les pièces","Supprimer les œuvres exposées","Reconstruire entièrement la maison","Réserver le lieu aux anciens propriétaires"],"correct":"A","explanation":"Le passage indique : « Une maison d'artiste conserve plusieurs pièces intactes et transforme une autre en espace d'accueil. Le projet distingue les besoins de présentation des conditions nécessaires à la visite. » Cela justifie la réponse : Accueillir le public sans modifier toutes les pièces."},{"number":28,"points":21,"passage":"Des habitants participent au choix de nouveaux noms de rues. Une commission vérifie les propositions pour éviter les doublons qui compliqueraient l'orientation et les secours.","question":"Quel contrôle accompagne la consultation ?","options":["Le nombre de lettres des habitants","L'âge de tous les participants","La clarté pratique des noms choisis","Le prix des logements"],"correct":"C","explanation":"Le passage indique : « Des habitants participent au choix de nouveaux noms de rues. Une commission vérifie les propositions pour éviter les doublons qui compliqueraient l'orientation et les secours. » Cela justifie la réponse : La clarté pratique des noms choisis."},{"number":29,"points":21,"passage":"Une visite montre des traces de réparations successives sur un bâtiment. Elles témoignent de son histoire matérielle plutôt que d'un état originel resté inchangé.","question":"Que révèlent ces traces ?","options":["L'absence de tout entretien","La succession des interventions dans le temps","La disparition de tous les matériaux anciens","Une construction récente déguisée nécessairement"],"correct":"B","explanation":"Le passage indique : « Une visite montre des traces de réparations successives sur un bâtiment. Elles témoignent de son histoire matérielle plutôt que d'un état originel resté inchangé. » Cela justifie la réponse : La succession des interventions dans le temps."},{"number":30,"points":26,"passage":"La protection d'un centre ancien peut rendre certaines adaptations plus difficiles. Un urbaniste propose de discuter les effets concrets des règles : préserver des qualités ne suppose pas de refuser toute évolution des usages.","question":"Quelle approche est défendue ?","options":["Transformer tous les logements en vitrines","Abandonner toute protection","Appliquer un refus automatique à chaque changement","Examiner comment conservation et adaptation peuvent coexister"],"correct":"D","explanation":"Le passage indique : « La protection d'un centre ancien peut rendre certaines adaptations plus difficiles. Un urbaniste propose de discuter les effets concrets des règles : préserver des qualités ne suppose pas de refuser toute évolution des usages. » Cela justifie la réponse : Examiner comment conservation et adaptation peuvent coexister."},{"number":31,"points":26,"passage":"Un objet quotidien devient une pièce de musée. Sa conservation change le regard porté sur lui, mais peut aussi l'éloigner des gestes qui expliquaient son usage. Les médiateurs ajoutent des démonstrations pour rendre cette dimension perceptible.","question":"Que cherchent à restituer les démonstrations ?","options":["Le prix actuel de tous les produits","Le contexte pratique de l'objet","La propriété du bâtiment","Une garantie de fabrication moderne"],"correct":"B","explanation":"Le passage indique : « Un objet quotidien devient une pièce de musée. Sa conservation change le regard porté sur lui, mais peut aussi l'éloigner des gestes qui expliquaient son usage. Les médiateurs ajoutent des démonstrations pour rendre cette dimension perceptible. » Cela justifie la réponse : Le contexte pratique de l'objet."},{"number":32,"points":26,"passage":"Les touristes photographient un monument depuis un même point, devenu célèbre en ligne. Le gestionnaire ouvre un second parcours pour montrer des aspects moins connus. Il ne conteste pas la première vue, mais veut éviter qu'elle résume toute l'expérience du lieu.","question":"Quel objectif poursuit-il ?","options":["Élargir le regard au-delà d'une image dominante","Interdire toute photographie","Fermer les autres chemins","Reproduire partout le même point de vue"],"correct":"A","explanation":"Le passage indique : « Les touristes photographient un monument depuis un même point, devenu célèbre en ligne. Le gestionnaire ouvre un second parcours pour montrer des aspects moins connus. Il ne conteste pas la première vue, mais veut éviter qu'elle résume toute l'expérience du lieu. » Cela justifie la réponse : Élargir le regard au-delà d'une image dominante."},{"number":33,"points":26,"passage":"Une ville restaure un ancien lavoir tout en conservant les marques d'usure. Les pierres abîmées ne sont pas toutes remplacées : certaines portent les traces des gestes répétés. La valeur historique ne se réduit pas à une apparence parfaitement neuve.","question":"Pourquoi conserver certaines marques ?","options":["Elles témoignent des usages passés","Elles réduisent toujours le coût à zéro","Elles garantissent une meilleure étanchéité","Elles remplacent les informations historiques"],"correct":"A","explanation":"Le passage indique : « Une ville restaure un ancien lavoir tout en conservant les marques d'usure. Les pierres abîmées ne sont pas toutes remplacées : certaines portent les traces des gestes répétés. La valeur historique ne se réduit pas à une apparence parfaitement neuve. » Cela justifie la réponse : Elles témoignent des usages passés."},{"number":34,"points":26,"passage":"Une exposition sur l'urbanisme confronte plans officiels et récits de résidents. Les premiers montrent des intentions et des règles ; les seconds révèlent des usages parfois différents. Comprendre la ville suppose de regarder ce qui a été prévu et ce qui a été vécu.","question":"Quelle démarche est proposée ?","options":["Écarter tous les témoignages","Considérer les intentions comme des résultats assurés","Croiser conception et expérience des lieux","Choisir uniquement les plans"],"correct":"C","explanation":"Le passage indique : « Une exposition sur l'urbanisme confronte plans officiels et récits de résidents. Les premiers montrent des intentions et des règles ; les seconds révèlent des usages parfois différents. Comprendre la ville suppose de regarder ce qui a été prévu et ce qui a été vécu. » Cela justifie la réponse : Croiser conception et expérience des lieux."},{"number":35,"points":26,"passage":"La réutilisation d'un bâtiment semble éviter une construction neuve. Son intérêt doit néanmoins être étudié avec les adaptations nécessaires et les besoins futurs. Conserver à tout prix une structure très inadaptée peut déplacer les coûts plutôt que résoudre le problème d'usage.","question":"Quelle réserve est formulée ?","options":["Toute réutilisation est impossible","Une construction neuve est toujours préférable","Le réemploi doit être évalué selon la situation réelle","Les besoins futurs sont sans importance"],"correct":"C","explanation":"Le passage indique : « La réutilisation d'un bâtiment semble éviter une construction neuve. Son intérêt doit néanmoins être étudié avec les adaptations nécessaires et les besoins futurs. Conserver à tout prix une structure très inadaptée peut déplacer les coûts plutôt que résoudre le problème d'usage. » Cela justifie la réponse : Le réemploi doit être évalué selon la situation réelle."},{"number":36,"points":33,"passage":"Un quartier souhaite valoriser son histoire. Les habitants les plus anciens possèdent beaucoup de souvenirs, mais les nouveaux arrivants contribuent aussi à la vie actuelle du lieu. Le projet accueille les deux perspectives. Le patrimoine partagé peut se construire à partir d'héritages différents sans exiger une ancienneté identique pour participer.","question":"Quelle conception du patrimoine est défendue ?","options":["Un récit sans aucun souvenir local","Une histoire qui efface tous les nouveaux usages","Un héritage ouvert à des contributions diverses","Une mémoire réservée aux résidents les plus anciens"],"correct":"C","explanation":"Le passage indique : « Le patrimoine partagé peut se construire à partir d'héritages différents sans exiger une ancienneté identique pour participer. » Cela justifie la réponse : Un héritage ouvert à des contributions diverses."},{"number":37,"points":33,"passage":"La reconstruction d'une façade disparue peut redonner une image familière à une place. Elle ne restitue pourtant ni tous les matériaux ni toutes les fonctions du bâtiment d'origine. Une ressemblance visuelle doit être distinguée d'une continuité historique complète.","question":"Quelle prudence est recommandée ?","options":["Abandonner toute information sur les transformations","Ne pas confondre restitution d'une apparence et retour intégral du passé","Déduire l'usage actuel de la seule décoration","Considérer toute façade reconstruite comme strictement ancienne"],"correct":"B","explanation":"Le passage indique : « Une ressemblance visuelle doit être distinguée d'une continuité historique complète. » Cela justifie la réponse : Ne pas confondre restitution d'une apparence et retour intégral du passé."},{"number":38,"points":33,"passage":"Une ville veut attirer des visiteurs grâce à un label patrimonial. Certains ateliers et logements risquent de devenir des hébergements touristiques. Le conseil débat donc d'outils pour conserver des fonctions ordinaires. Valoriser un lieu peut fragiliser ce qui le rend habitable si l'attractivité devient son seul objectif.","question":"Quel enjeu accompagne la valorisation ?","options":["Supprimer les services ordinaires devenus invisibles","Éviter toute visite extérieure","Préserver une vie locale au-delà de la fréquentation touristique","Transformer systématiquement tous les logements"],"correct":"C","explanation":"Le passage indique : « Valoriser un lieu peut fragiliser ce qui le rend habitable si l'attractivité devient son seul objectif. » Cela justifie la réponse : Préserver une vie locale au-delà de la fréquentation touristique."},{"number":39,"points":33,"passage":"Des archives numérisées rendent une collection plus largement consultable. Pourtant, certaines descriptions reflètent d'anciennes catégories contestées. L'équipe conserve la trace historique tout en ajoutant des explications. Faciliter l'accès à une source ne dispense pas d'aider à comprendre les conditions dans lesquelles elle a été produite.","question":"Quelle démarche documentaire est choisie ?","options":["Retirer toutes les sources difficiles","Présenter chaque ancienne catégorie comme une vérité actuelle","Remplacer les archives par des récits sans origine","Contextualiser les documents sans effacer leur histoire"],"correct":"D","explanation":"Le passage indique : « Faciliter l'accès à une source ne dispense pas d'aider à comprendre les conditions dans lesquelles elle a été produite. » Cela justifie la réponse : Contextualiser les documents sans effacer leur histoire."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-17','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-17","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 17","topic":"Familles, générations et liens sociaux","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée.","question":"Où déposer les poussettes ?","options":["Dans chaque salle d'activité","Dans l'espace près de l'entrée","Sur l'escalier","Dans la cuisine"],"correct":"B","explanation":"Le passage indique : « L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée. » Cela justifie la réponse : Dans l'espace près de l'entrée."},{"number":2,"points":3,"passage":"La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables.","question":"Que doivent savoir les inscrits ?","options":["Ils doivent tous payer une seconde fois","Le groupe change de destination obligatoirement","Leur inscription est conservée","La sortie est annulée définitivement"],"correct":"C","explanation":"Le passage indique : « La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables. » Cela justifie la réponse : Leur inscription est conservée."},{"number":3,"points":3,"passage":"La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions.","question":"Qui peut être accueilli ?","options":["Seulement les enfants majeurs","Uniquement une famille au complet","Un parent non accompagné","Les professionnels exclusivement"],"correct":"C","explanation":"Le passage indique : « La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions. » Cela justifie la réponse : Un parent non accompagné."},{"number":4,"points":3,"passage":"Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus.","question":"Que doivent nécessairement préparer les participants ?","options":["Un gâteau chacun","Des boissons sucrées","Un repas complet","Aucun plat n'est obligatoire"],"correct":"D","explanation":"Le passage indique : « Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus. » Cela justifie la réponse : Aucun plat n'est obligatoire."},{"number":5,"points":9,"passage":"Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé.","question":"Quelle contrainte est exprimée ?","options":["Une heure de fin à respecter","Un changement d'école","Une obligation de rester jusqu'au soir","Un refus de toute garde"],"correct":"A","explanation":"Le passage indique : « Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé. » Cela justifie la réponse : Une heure de fin à respecter."},{"number":6,"points":9,"passage":"Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille.","question":"Quelle condition n'est pas exigée ?","options":["Respecter le lieu de départ","Prendre connaissance de l'horaire","Être accompagné d'un enfant","Participer à la promenade"],"correct":"C","explanation":"Le passage indique : « Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille. » Cela justifie la réponse : Être accompagné d'un enfant."},{"number":7,"points":9,"passage":"J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces.","question":"Quel aspect veut-on conserver ?","options":["Les horaires de la cuisine","Uniquement les prix des ingrédients","Le nom des magasins","Les gestes et conseils associés à la recette"],"correct":"D","explanation":"Le passage indique : « J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces. » Cela justifie la réponse : Les gestes et conseils associés à la recette."},{"number":8,"points":9,"passage":"La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents.","question":"Quel service est proposé ?","options":["Imposer un jeu unique à toutes les familles","Aider à choisir un jeu partagé","Remplacer les parents pendant une semaine","Vendre tous les jouets neufs"],"correct":"B","explanation":"Le passage indique : « La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents. » Cela justifie la réponse : Aider à choisir un jeu partagé."},{"number":9,"points":9,"passage":"Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ?","question":"Que demande cette personne ?","options":["Une dispense de recevoir les informations","Une suppression de la réunion","Un autre accès aux informations et aux échanges","Un changement de tous les participants"],"correct":"C","explanation":"Le passage indique : « Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ? » Cela justifie la réponse : Un autre accès aux informations et aux échanges."},{"number":10,"points":9,"passage":"Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication.","question":"Quelle règle est rappelée ?","options":["Publier automatiquement chaque visage","Vérifier les autorisations de diffusion","Vendre les photos aux invités","Éviter toute prise de vue privée nécessairement"],"correct":"B","explanation":"Le passage indique : « Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication. » Cela justifie la réponse : Vérifier les autorisations de diffusion."},{"number":11,"points":15,"passage":"Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge.","question":"Quel principe guide la répartition ?","options":["Le statut professionnel des parents","La diversité des contributions possibles","Une hiérarchie fixe par génération","La force physique uniquement"],"correct":"B","explanation":"Le passage indique : « Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge. » Cela justifie la réponse : La diversité des contributions possibles."},{"number":12,"points":15,"passage":"Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes.","question":"Quel besoin ce service vise-t-il ?","options":["Des meubles définitifs pour chaque maison","Un transport scolaire permanent","Des équipements temporaires","Des réparations industrielles"],"correct":"C","explanation":"Le passage indique : « Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes. » Cela justifie la réponse : Des équipements temporaires."},{"number":13,"points":15,"passage":"Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité.","question":"Quelle place est donnée aux participants ?","options":["Appliquer un questionnaire sans discussion","Présenter des informations personnelles obligatoires","Évaluer les autres familles publiquement","Définir les sujets utiles à partir de leurs besoins"],"correct":"D","explanation":"Le passage indique : « Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité. » Cela justifie la réponse : Définir les sujets utiles à partir de leurs besoins."},{"number":14,"points":15,"passage":"Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé.","question":"Quelle idée est évitée ?","options":["Accueillir des jeunes visiteurs","Réduire les personnes âgées à leurs souvenirs","Permettre des intérêts communs","Choisir des sujets actuels"],"correct":"B","explanation":"Le passage indique : « Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé. » Cela justifie la réponse : Réduire les personnes âgées à leurs souvenirs."},{"number":15,"points":15,"passage":"Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription.","question":"Quelle souplesse est prévue ?","options":["La participation avec un accompagnateur non apparenté","La garde anonyme des enfants","La suppression des inscriptions","L'absence de tout adulte responsable"],"correct":"A","explanation":"Le passage indique : « Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription. » Cela justifie la réponse : La participation avec un accompagnateur non apparenté."},{"number":16,"points":15,"passage":"Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément.","question":"Quel apprentissage est proposé ?","options":["Supprimer les documents individuels","Confier toutes les décisions au groupe","Partager sans effacer toute confidentialité","Rendre tous les dossiers publics"],"correct":"C","explanation":"Le passage indique : « Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément. » Cela justifie la réponse : Partager sans effacer toute confidentialité."},{"number":17,"points":15,"passage":"Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents.","question":"Quel obstacle cherche-t-elle à réduire ?","options":["La présence des nouveaux habitants","L'incompatibilité de certains horaires","Le nombre de salles seulement","Le manque de sujets à discuter"],"correct":"B","explanation":"Le passage indique : « Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents. » Cela justifie la réponse : L'incompatibilité de certains horaires."},{"number":18,"points":15,"passage":"Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau.","question":"Quelle règle protège la souplesse du dispositif ?","options":["Le refus ponctuel reste possible","Le calendrier est fixé pour dix ans","Une absence entraîne une exclusion automatique","Toute demande doit être acceptée"],"correct":"A","explanation":"Le passage indique : « Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau. » Cela justifie la réponse : Le refus ponctuel reste possible."},{"number":19,"points":15,"passage":"Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire.","question":"Quelle finalité est privilégiée ?","options":["Partager un moment autour de la lecture","Préparer un concours obligatoire","Mesurer la vitesse de lecture uniquement","Classer les familles"],"correct":"A","explanation":"Le passage indique : « Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire. » Cela justifie la réponse : Partager un moment autour de la lecture."},{"number":20,"points":21,"passage":"Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée.","question":"Quel équilibre est recherché ?","options":["Obligation de participer chaque soir","Séparation complète de toutes les générations","Suppression de tous les espaces privés","Rencontres possibles et respect de l'intimité"],"correct":"D","explanation":"Le passage indique : « Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. » Cela justifie la réponse : Rencontres possibles et respect de l'intimité."},{"number":21,"points":21,"passage":"Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance.","question":"Quelle cause possible est identifiée ?","options":["Une difficulté d'accès au lieu","Une absence certaine d'intérêt","Un prix obligatoirement trop élevé","Un manque de jeux dans chaque foyer"],"correct":"A","explanation":"Le passage indique : « Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. » Cela justifie la réponse : Une difficulté d'accès au lieu."},{"number":22,"points":21,"passage":"Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs.","question":"Quel besoin expriment-ils ?","options":["Un centre commercial obligatoire","Une salle sans possibilité de discussion","Un espace de sociabilité accessible","Une compétition permanente"],"correct":"C","explanation":"Le passage indique : « Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. » Cela justifie la réponse : Un espace de sociabilité accessible."},{"number":23,"points":21,"passage":"Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats.","question":"Quel aspect est mieux pris en compte ?","options":["Le travail d'organisation","La surface des logements uniquement","Le nombre de meubles","Les achats de loisirs"],"correct":"A","explanation":"Le passage indique : « Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. » Cela justifie la réponse : Le travail d'organisation."},{"number":24,"points":21,"passage":"Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres.","question":"Quelle prudence est recommandée ?","options":["Adapter les échanges aux situations particulières","Éviter tous les témoignages","Imposer une méthode unique","Considérer les contraintes comme identiques"],"correct":"A","explanation":"Le passage indique : « Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. » Cela justifie la réponse : Adapter les échanges aux situations particulières."},{"number":25,"points":21,"passage":"Un quartier installe des bancs près de l'aire de jeux. Les adultes peuvent rester confortablement, ce qui facilite aussi la venue des grands-parents et les échanges entre accompagnateurs.","question":"Quel effet dépasse le jeu des enfants ?","options":["La fermeture des espaces voisins","Une meilleure possibilité de présence et de rencontre des adultes","Une réduction obligatoire de la durée des sorties","La suppression des activités entre générations"],"correct":"B","explanation":"Le passage indique : « Un quartier installe des bancs près de l'aire de jeux. Les adultes peuvent rester confortablement, ce qui facilite aussi la venue des grands-parents et les échanges entre accompagnateurs. » Cela justifie la réponse : Une meilleure possibilité de présence et de rencontre des adultes."},{"number":26,"points":21,"passage":"Une association propose des conseils aux parents en plusieurs langues. Elle utilise aussi des exemples concrets plutôt que traduire uniquement des termes administratifs difficiles.","question":"Quelle adaptation complète la traduction ?","options":["Supprimer les informations pratiques","Réserver les échanges aux traducteurs","Ajouter des formulaires plus longs","Rendre le contenu plus compréhensible"],"correct":"D","explanation":"Le passage indique : « Une association propose des conseils aux parents en plusieurs langues. Elle utilise aussi des exemples concrets plutôt que traduire uniquement des termes administratifs difficiles. » Cela justifie la réponse : Rendre le contenu plus compréhensible."},{"number":27,"points":21,"passage":"Des résidents souhaitent un téléphone collectif pour les appels vidéo. L'équipe organise des créneaux accompagnés, car la présence du matériel ne suffit pas à garantir son utilisation.","question":"Quel besoin complémentaire est reconnu ?","options":["La suppression des échanges en personne","L'achat d'un second bâtiment","Un soutien à l'usage","Une obligation d'appeler chaque jour"],"correct":"C","explanation":"Le passage indique : « Des résidents souhaitent un téléphone collectif pour les appels vidéo. L'équipe organise des créneaux accompagnés, car la présence du matériel ne suffit pas à garantir son utilisation. » Cela justifie la réponse : Un soutien à l'usage."},{"number":28,"points":21,"passage":"Une commune associe les enfants à l'évaluation des trajets scolaires. Leur taille et leur expérience font apparaître des obstacles peu visibles pour les adultes.","question":"Pourquoi leur point de vue est-il utile ?","options":["Il révèle une expérience différente des aménagements","Il garantit l'absence de danger","Il remplace toutes les mesures techniques","Il ne concerne que la décoration des rues"],"correct":"A","explanation":"Le passage indique : « Une commune associe les enfants à l'évaluation des trajets scolaires. Leur taille et leur expérience font apparaître des obstacles peu visibles pour les adultes. » Cela justifie la réponse : Il révèle une expérience différente des aménagements."},{"number":29,"points":21,"passage":"Un groupe organise un échange de savoirs entre générations. Les jeunes ne sont pas toujours les élèves : ils présentent aussi des pratiques que les plus âgés souhaitent découvrir.","question":"Quelle relation est mise en valeur ?","options":["Une égalité de toutes les expériences sans échange","Une séparation stricte des groupes","Un enseignement réservé aux aînés","Une transmission dans plusieurs sens"],"correct":"D","explanation":"Le passage indique : « Un groupe organise un échange de savoirs entre générations. Les jeunes ne sont pas toujours les élèves : ils présentent aussi des pratiques que les plus âgés souhaitent découvrir. » Cela justifie la réponse : Une transmission dans plusieurs sens."},{"number":30,"points":26,"passage":"La solidarité familiale est parfois supposée disponible sans limite. Elle dépend pourtant du temps, de la proximité et des ressources de chacun. Un service public qui compte uniquement sur elle risque de traiter différemment des personnes ayant les mêmes besoins mais des entourages très différents.","question":"Quelle limite de cette supposition est soulignée ?","options":["Les capacités d'aide des entourages sont inégales","Les besoins disparaissent avec des proches","La solidarité ne peut jamais exister","Toutes les familles vivent au même endroit"],"correct":"A","explanation":"Le passage indique : « La solidarité familiale est parfois supposée disponible sans limite. Elle dépend pourtant du temps, de la proximité et des ressources de chacun. Un service public qui compte uniquement sur elle risque de traiter différemment des personnes ayant les mêmes besoins mais des entourages très différents. » Cela justifie la réponse : Les capacités d'aide des entourages sont inégales."},{"number":31,"points":26,"passage":"Une activité dite familiale peut sembler ouverte à tous. Si elle suppose deux adultes disponibles le samedi et une voiture, certaines familles restent à l'écart. Les conditions concrètes de participation comptent autant que le nom accueillant donné au programme.","question":"Que faut-il examiner ?","options":["La profession des animateurs seulement","Les contraintes implicites de l'organisation","Uniquement le mot utilisé sur l'affiche","Le nombre de couleurs du logo"],"correct":"B","explanation":"Le passage indique : « Une activité dite familiale peut sembler ouverte à tous. Si elle suppose deux adultes disponibles le samedi et une voiture, certaines familles restent à l'écart. Les conditions concrètes de participation comptent autant que le nom accueillant donné au programme. » Cela justifie la réponse : Les contraintes implicites de l'organisation."},{"number":32,"points":26,"passage":"La mémoire familiale se construit avec des récits qui évoluent selon ceux qui les racontent. Des versions différentes ne signifient pas nécessairement qu'une personne cherche à tromper. Elles peuvent refléter des positions, des âges et des expériences distincts dans un même événement.","question":"Quelle lecture des désaccords est proposée ?","options":["Un souvenir doit être identique chez tous","L'âge n'influence jamais une perception","Toute différence prouve un mensonge","Des perspectives différentes peuvent expliquer des récits variés"],"correct":"D","explanation":"Le passage indique : « La mémoire familiale se construit avec des récits qui évoluent selon ceux qui les racontent. Des versions différentes ne signifient pas nécessairement qu'une personne cherche à tromper. Elles peuvent refléter des positions, des âges et des expériences distincts dans un même événement. » Cela justifie la réponse : Des perspectives différentes peuvent expliquer des récits variés."},{"number":33,"points":26,"passage":"Un service souhaite soutenir les aidants sans décider à leur place. Il propose des temps de relais et demande régulièrement si les besoins ont changé. L'accompagnement ne consiste pas à fixer une fois pour toutes une solution supposée convenir à toute la durée de la situation.","question":"Quelle caractéristique du soutien est valorisée ?","options":["L'absence de consultation","Sa capacité d'ajustement","Une disponibilité identique pour tous","Son caractère immuable"],"correct":"B","explanation":"Le passage indique : « Un service souhaite soutenir les aidants sans décider à leur place. Il propose des temps de relais et demande régulièrement si les besoins ont changé. L'accompagnement ne consiste pas à fixer une fois pour toutes une solution supposée convenir à toute la durée de la situation. » Cela justifie la réponse : Sa capacité d'ajustement."},{"number":34,"points":26,"passage":"Un projet rapproche des générations par des activités communes. Les organisateurs évitent de supposer d'avance que les jeunes veulent uniquement du numérique et les anciens uniquement raconter le passé. Les centres d'intérêt réels émergent des rencontres.","question":"Quelle erreur veulent-ils éviter ?","options":["Permettre de nouveaux apprentissages","Organiser des échanges réciproques","Découvrir des intérêts inattendus","Attribuer des goûts fixes selon l'âge"],"correct":"D","explanation":"Le passage indique : « Un projet rapproche des générations par des activités communes. Les organisateurs évitent de supposer d'avance que les jeunes veulent uniquement du numérique et les anciens uniquement raconter le passé. Les centres d'intérêt réels émergent des rencontres. » Cela justifie la réponse : Attribuer des goûts fixes selon l'âge."},{"number":35,"points":26,"passage":"Une consultation compte une réponse par foyer. Des participants soulignent que cette unité peut masquer les besoins différents des personnes qui y vivent. Un avis commun est utile pour certaines questions, mais ne remplace pas toujours l'écoute individuelle.","question":"Quelle limite de la méthode est signalée ?","options":["Les besoins individuels sont impossibles à connaître","Toutes les personnes d'un foyer pensent pareil","Le foyer n'est pas nécessairement une voix homogène","Une réponse familiale est toujours sans intérêt"],"correct":"C","explanation":"Le passage indique : « Une consultation compte une réponse par foyer. Des participants soulignent que cette unité peut masquer les besoins différents des personnes qui y vivent. Un avis commun est utile pour certaines questions, mais ne remplace pas toujours l'écoute individuelle. » Cela justifie la réponse : Le foyer n'est pas nécessairement une voix homogène."},{"number":36,"points":33,"passage":"Une résidence promet de lutter contre la solitude en rapprochant des générations. Elle découvre que la proximité physique facilite certaines rencontres sans garantir la confiance. Des activités choisies et un respect du refus sont nécessaires. Créer les conditions d'une relation ne revient pas à pouvoir l'imposer.","question":"Quelle distinction est essentielle ?","options":["Prévoir une salle et acheter des chaises seulement","Participer à une activité et sortir du bâtiment","Vivre près d'une personne et connaître son âge","Faciliter les liens et obliger à entretenir une relation"],"correct":"D","explanation":"Le passage indique : « Créer les conditions d'une relation ne revient pas à pouvoir l'imposer. » Cela justifie la réponse : Faciliter les liens et obliger à entretenir une relation."},{"number":37,"points":33,"passage":"Une campagne valorise les grands-parents très actifs, toujours disponibles et connectés. Des associations apprécient cette image positive, mais craignent qu'elle devienne une norme excluant les personnes fatiguées ou moins équipées. Combattre un stéréotype ne devrait pas consister à le remplacer par une exigence de performance identique pour tous.","question":"Quelle réserve est exprimée ?","options":["Les personnes âgées ne peuvent jamais être actives","L'équipement numérique définit la valeur d'une personne","Toute campagne positive doit disparaître","Une image valorisante peut devenir une nouvelle norme contraignante"],"correct":"D","explanation":"Le passage indique : « Combattre un stéréotype ne devrait pas consister à le remplacer par une exigence de performance identique pour tous. » Cela justifie la réponse : Une image valorisante peut devenir une nouvelle norme contraignante."},{"number":38,"points":33,"passage":"Des parents sont invités à participer aux activités de l'école. Les personnes disponibles en journée deviennent les interlocuteurs les plus visibles. L'équipe organise d'autres moyens de contribution pour entendre aussi celles qui ne peuvent pas venir. La disponibilité ne doit pas être confondue avec l'intérêt porté à la scolarité.","question":"Quelle interprétation veut-on éviter ?","options":["Reconnaître des contraintes horaires","Proposer plusieurs façons de participer","Juger l'engagement à partir de la seule présence en journée","Demander l'avis de familles absentes"],"correct":"C","explanation":"Le passage indique : « La disponibilité ne doit pas être confondue avec l'intérêt porté à la scolarité. » Cela justifie la réponse : Juger l'engagement à partir de la seule présence en journée."},{"number":39,"points":33,"passage":"Un atelier réunit des aidants pour partager des pratiques. Les animateurs veillent à ce que l'échange ne transforme pas chacun en responsable de résoudre seul toutes les difficultés. L'entraide peut renforcer les personnes tout en faisant apparaître des besoins qui demandent une réponse collective ou professionnelle.","question":"Quelle complémentarité est défendue ?","options":["Écarter toute aide professionnelle","Associer soutien entre personnes et recours à d'autres ressources","Remplacer tous les services par des proches","Considérer les difficultés comme toujours individuelles"],"correct":"B","explanation":"Le passage indique : « L'entraide peut renforcer les personnes tout en faisant apparaître des besoins qui demandent une réponse collective ou professionnelle. » Cela justifie la réponse : Associer soutien entre personnes et recours à d'autres ressources."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-18','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-18","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 18","topic":"Mer, montagne et découverte des paysages","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant.","question":"À quelle heure faut-il être présent ?","options":["Six heures","Six heures quarante-cinq","Huit heures","Sept heures quinze"],"correct":"B","explanation":"Le passage indique : « Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant. » Cela justifie la réponse : Six heures quarante-cinq."},{"number":2,"points":3,"passage":"Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée.","question":"Quel équipement reste nécessaire ?","options":["Une bouteille de gaz","Un sac de couchage","Un oreiller neuf","Une tente obligatoire"],"correct":"B","explanation":"Le passage indique : « Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée. » Cela justifie la réponse : Un sac de couchage."},{"number":3,"points":3,"passage":"La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée.","question":"Que précise l'annonce ?","options":["La surveillance est assurée par tous les visiteurs","La surveillance commence à onze heures","La baignade est surveillée toute la nuit","La plage ferme à onze heures"],"correct":"B","explanation":"Le passage indique : « La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée. » Cela justifie la réponse : La surveillance commence à onze heures."},{"number":4,"points":3,"passage":"Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible.","question":"Quel itinéraire est proposé ?","options":["La route fermée","Le bord des falaises","Le sommet sans balisage","Le parcours intérieur"],"correct":"D","explanation":"Le passage indique : « Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible. » Cela justifie la réponse : Le parcours intérieur."},{"number":5,"points":9,"passage":"Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée.","question":"Quel avantage est recherché ?","options":["Parcourir le plus grand nombre de refuges","Explorer sans porter tout le matériel","Descendre immédiatement en ville","Éviter toute promenade"],"correct":"B","explanation":"Le passage indique : « Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée. » Cela justifie la réponse : Explorer sans porter tout le matériel."},{"number":6,"points":9,"passage":"La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place.","question":"Quelle règle concerne les animaux observés ?","options":["Ne pas les emporter","Les déposer au musée","Les conserver comme souvenirs","Les vendre au retour"],"correct":"A","explanation":"Le passage indique : « La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place. » Cela justifie la réponse : Ne pas les emporter."},{"number":7,"points":9,"passage":"Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent.","question":"Pourquoi modifier le départ ?","options":["Éviter de rencontrer le guide","Changer automatiquement de destination","Attendre une meilleure visibilité","Profiter d'un brouillard plus épais"],"correct":"C","explanation":"Le passage indique : « Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent. » Cela justifie la réponse : Attendre une meilleure visibilité."},{"number":8,"points":9,"passage":"Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer.","question":"Quelle précaution est recommandée ?","options":["Prévoir une tenue chaude","Renoncer à toute protection","Se fier uniquement au temps sur le quai","Acheter un vêtement à chaque escale"],"correct":"A","explanation":"Le passage indique : « Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer. » Cela justifie la réponse : Prévoir une tenue chaude."},{"number":9,"points":9,"passage":"La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter.","question":"Quelle solution alternative existe ?","options":["Un accès à tous les étages par ascenseur","Une fermeture complète aux visiteurs","Une montée en voiture","Une découverte sans ascension"],"correct":"D","explanation":"Le passage indique : « La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter. » Cela justifie la réponse : Une découverte sans ascension."},{"number":10,"points":9,"passage":"Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté.","question":"Pourquoi louer d'abord ?","options":["Essayer le matériel avant de choisir","Obtenir un achat définitif gratuit","Remplacer les conseils du guide par un tirage au sort","Éviter toute observation"],"correct":"A","explanation":"Le passage indique : « Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté. » Cela justifie la réponse : Essayer le matériel avant de choisir."},{"number":11,"points":15,"passage":"Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer.","question":"Pourquoi conserver les mêmes repères ?","options":["Garantir l'absence de changement","Modifier artificiellement la taille du glacier","Éviter de noter les dates","Rendre l'évolution observable de manière comparable"],"correct":"D","explanation":"Le passage indique : « Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer. » Cela justifie la réponse : Rendre l'évolution observable de manière comparable."},{"number":12,"points":15,"passage":"Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces.","question":"Pourquoi ne pas retirer les algues ?","options":["Elles ont une fonction dans le milieu","Elles empêchent toute vie animale","Elles remplacent les poubelles","Elles sont toutes dangereuses à toucher"],"correct":"A","explanation":"Le passage indique : « Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces. » Cela justifie la réponse : Elles ont une fonction dans le milieu."},{"number":13,"points":15,"passage":"Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs.","question":"Quel besoin encadre la visite ?","options":["Une reproduction identique chaque jour","L'absence de tout contact professionnel","Le maintien de l'activité portuaire","L'arrêt de tous les navires"],"correct":"C","explanation":"Le passage indique : « Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs. » Cela justifie la réponse : Le maintien de l'activité portuaire."},{"number":14,"points":15,"passage":"Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations.","question":"Pourquoi encadrer la fréquentation ?","options":["Accélérer la formation des roches","Préserver un milieu sensible","Transformer la grotte en parking","Garantir un éclairage permanent"],"correct":"B","explanation":"Le passage indique : « Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations. » Cela justifie la réponse : Préserver un milieu sensible."},{"number":15,"points":15,"passage":"Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide.","question":"Quel objectif est poursuivi ?","options":["Conserver une solution de repli","Suivre uniquement les autres marcheurs","Interdire tout appareil numérique","Éviter d'apprendre les repères"],"correct":"A","explanation":"Le passage indique : « Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide. » Cela justifie la réponse : Conserver une solution de repli."},{"number":16,"points":15,"passage":"Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés.","question":"Quel usage est fait des photographies ?","options":["Vendre toutes les captures","Participer à un suivi des animaux","Décorer les billets de bateau","Remplacer les règles de navigation"],"correct":"B","explanation":"Le passage indique : « Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés. » Cela justifie la réponse : Participer à un suivi des animaux."},{"number":17,"points":15,"passage":"Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol.","question":"Quel effet veut-on limiter ?","options":["La lecture des panneaux","La croissance normale des fleurs","L'usure cumulée du milieu","La diversité des itinéraires autorisés"],"correct":"C","explanation":"Le passage indique : « Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol. » Cela justifie la réponse : L'usure cumulée du milieu."},{"number":18,"points":15,"passage":"Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau.","question":"Comment la formation continue-t-elle ?","options":["Par la vente des bateaux","Par l'arrêt définitif des cours","Par une sortie malgré l'interdiction","Par des apprentissages sans navigation"],"correct":"D","explanation":"Le passage indique : « Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau. » Cela justifie la réponse : Par des apprentissages sans navigation."},{"number":19,"points":15,"passage":"Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe.","question":"Quelle idée est mise en évidence ?","options":["Les relevés actuels suffisent à décrire tous les siècles","Les cartes anciennes sont toutes inutiles","La côte reste identique partout","Le littoral évolue dans le temps"],"correct":"D","explanation":"Le passage indique : « Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe. » Cela justifie la réponse : Le littoral évolue dans le temps."},{"number":20,"points":21,"passage":"Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée.","question":"Quel enjeu accompagne cette diversification ?","options":["Fermer tous les équipements existants","Garantir de la neige toute l'année","Construire des offres qui ne dépendent pas uniquement du ski","Transformer chaque habitant en moniteur"],"correct":"C","explanation":"Le passage indique : « Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. » Cela justifie la réponse : Construire des offres qui ne dépendent pas uniquement du ski."},{"number":21,"points":21,"passage":"Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes.","question":"Quel équilibre est recherché ?","options":["Permettre l'accès en préservant des fonctions naturelles","Supprimer la végétation pour mieux la protéger","Interdire toute présence humaine","Remplacer toutes les dunes par du béton"],"correct":"A","explanation":"Le passage indique : « Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. » Cela justifie la réponse : Permettre l'accès en préservant des fonctions naturelles."},{"number":22,"points":21,"passage":"Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies.","question":"Quel compromis est choisi ?","options":["S'approcher toujours davantage","Faire sortir les oiseaux de leurs refuges","Limiter l'observation pour respecter les animaux","Éclairer les nids en continu"],"correct":"C","explanation":"Le passage indique : « Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. » Cela justifie la réponse : Limiter l'observation pour respecter les animaux."},{"number":23,"points":21,"passage":"Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux.","question":"Quelle réponse est adoptée ?","options":["Supprimer toute information de sécurité","Reconstruire systématiquement chaque mètre au même endroit","Garantir l'immobilité de la falaise","Adapter le parcours à l'évolution du site"],"correct":"D","explanation":"Le passage indique : « Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. » Cela justifie la réponse : Adapter le parcours à l'évolution du site."},{"number":24,"points":21,"passage":"Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent.","question":"Quelle condition limite l'agrandissement ?","options":["La longueur du nom du refuge","La couleur des couvertures","La capacité réelle des ressources et des services","Le nombre de photos en ligne"],"correct":"C","explanation":"Le passage indique : « Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. » Cela justifie la réponse : La capacité réelle des ressources et des services."},{"number":25,"points":21,"passage":"Une sortie d'observation annonce des espèces possibles, pas une rencontre garantie. Le guide rappelle que les animaux restent libres et que l'absence d'apparition ne signifie pas que le milieu est vide.","question":"Quelle attente est corrigée ?","options":["Accepter un parcours encadré","S'intéresser à la vie animale","Confondre possibilité d'observer et spectacle assuré","Prévoir des conditions météo"],"correct":"C","explanation":"Le passage indique : « Une sortie d'observation annonce des espèces possibles, pas une rencontre garantie. Le guide rappelle que les animaux restent libres et que l'absence d'apparition ne signifie pas que le milieu est vide. » Cela justifie la réponse : Confondre possibilité d'observer et spectacle assuré."},{"number":26,"points":21,"passage":"Une ville portuaire expose des objets trouvés lors d'un chantier. Leur emplacement de découverte est documenté, car un objet isolé de son contexte perd une partie des informations qu'il peut apporter.","question":"Pourquoi noter cet emplacement ?","options":["Garantir sa vente rapide","Éviter de décrire sa matière","Comprendre la relation entre l'objet et son contexte","Augmenter son poids"],"correct":"C","explanation":"Le passage indique : « Une ville portuaire expose des objets trouvés lors d'un chantier. Leur emplacement de découverte est documenté, car un objet isolé de son contexte perd une partie des informations qu'il peut apporter. » Cela justifie la réponse : Comprendre la relation entre l'objet et son contexte."},{"number":27,"points":21,"passage":"Un parc autorise certains accès en hiver et les ferme au printemps pendant la reproduction. La règle suit les besoins du milieu plutôt qu'un calendrier touristique identique toute l'année.","question":"Quelle logique organise l'accès ?","options":["L'adaptation aux périodes sensibles","Le seul nombre d'hôtels","L'ouverture permanente sans condition","La fermeture selon le prix des billets"],"correct":"A","explanation":"Le passage indique : « Un parc autorise certains accès en hiver et les ferme au printemps pendant la reproduction. La règle suit les besoins du milieu plutôt qu'un calendrier touristique identique toute l'année. » Cela justifie la réponse : L'adaptation aux périodes sensibles."},{"number":28,"points":21,"passage":"Des habitants comparent les récits d'une grande tempête avec des relevés officiels. Les souvenirs décrivent les effets vécus ; les mesures situent l'événement dans une série plus longue.","question":"Pourquoi croiser ces sources ?","options":["Déclarer les souvenirs inutiles","Remplacer les mesures par une seule émotion","Associer expérience locale et comparaison temporelle","Garantir une prévision exacte de la prochaine tempête"],"correct":"C","explanation":"Le passage indique : « Des habitants comparent les récits d'une grande tempête avec des relevés officiels. Les souvenirs décrivent les effets vécus ; les mesures situent l'événement dans une série plus longue. » Cela justifie la réponse : Associer expérience locale et comparaison temporelle."},{"number":29,"points":21,"passage":"Une entreprise propose des excursions plus lentes en bateau. Elle réduit le nombre de sites visités pour consacrer davantage de temps à l'observation et à l'explication.","question":"Quel choix est assumé ?","options":["Garantir toutes les rencontres animales","Approfondir plutôt que multiplier les étapes","Voir chaque site le plus rapidement possible","Supprimer le rôle du guide"],"correct":"B","explanation":"Le passage indique : « Une entreprise propose des excursions plus lentes en bateau. Elle réduit le nombre de sites visités pour consacrer davantage de temps à l'observation et à l'explication. » Cela justifie la réponse : Approfondir plutôt que multiplier les étapes."},{"number":30,"points":26,"passage":"La beauté d'un paysage peut donner l'impression d'un espace sans travail humain. Pourtant, terrasses, pâtures et chemins résultent souvent d'un entretien continu. Une visite guidée rend ces activités visibles sans nier les processus naturels qui façonnent aussi le lieu.","question":"Quel regard est proposé ?","options":["Réduire le paysage à une décoration immobile","Ignorer les pratiques d'entretien","Comprendre l'interaction entre activités humaines et milieu","Présenter toute montagne comme entièrement artificielle"],"correct":"C","explanation":"Le passage indique : « La beauté d'un paysage peut donner l'impression d'un espace sans travail humain. Pourtant, terrasses, pâtures et chemins résultent souvent d'un entretien continu. Une visite guidée rend ces activités visibles sans nier les processus naturels qui façonnent aussi le lieu. » Cela justifie la réponse : Comprendre l'interaction entre activités humaines et milieu."},{"number":31,"points":26,"passage":"Une carte de risques n'annonce pas qu'un événement touchera chaque parcelle à une date précise. Elle décrit des zones et des probabilités utiles à la décision. La lire comme une prédiction individuelle certaine conduirait à des attentes que l'outil ne peut pas satisfaire.","question":"Quelle distinction est nécessaire ?","options":["Prévention et interdiction de décider","Évaluation du risque et prédiction exacte","Carte et absence totale de données","Probabilité et certitude absolue"],"correct":"B","explanation":"Le passage indique : « Une carte de risques n'annonce pas qu'un événement touchera chaque parcelle à une date précise. Elle décrit des zones et des probabilités utiles à la décision. La lire comme une prédiction individuelle certaine conduirait à des attentes que l'outil ne peut pas satisfaire. » Cela justifie la réponse : Évaluation du risque et prédiction exacte."},{"number":32,"points":26,"passage":"Un équipement touristique peut faciliter la découverte d'un site tout en augmentant sa fréquentation. Les responsables étudient donc les effets de la nouvelle accessibilité avant d'agrandir davantage. Un aménagement utile individuellement peut créer une pression collective supplémentaire.","question":"Quel effet indirect faut-il examiner ?","options":["L'augmentation possible de la pression des visiteurs","La stabilité garantie du nombre de visiteurs","L'inutilité de toute observation","La disparition automatique du tourisme"],"correct":"A","explanation":"Le passage indique : « Un équipement touristique peut faciliter la découverte d'un site tout en augmentant sa fréquentation. Les responsables étudient donc les effets de la nouvelle accessibilité avant d'agrandir davantage. Un aménagement utile individuellement peut créer une pression collective supplémentaire. » Cela justifie la réponse : L'augmentation possible de la pression des visiteurs."},{"number":33,"points":26,"passage":"Un littoral évolue malgré des ouvrages de protection. Certains habitants demandent d'adapter les usages plutôt que renforcer sans cesse les mêmes défenses. Le débat ne sépare pas simplement ceux qui protègent et ceux qui abandonnent : il porte aussi sur ce qui peut être maintenu et à quel coût.","question":"Quelle lecture du débat est défendue ?","options":["Écarter tous les habitants concernés","Opposer uniquement courage et abandon","Supposer les ouvrages sans limites","Comparer différentes manières de s'adapter"],"correct":"D","explanation":"Le passage indique : « Un littoral évolue malgré des ouvrages de protection. Certains habitants demandent d'adapter les usages plutôt que renforcer sans cesse les mêmes défenses. Le débat ne sépare pas simplement ceux qui protègent et ceux qui abandonnent : il porte aussi sur ce qui peut être maintenu et à quel coût. » Cela justifie la réponse : Comparer différentes manières de s'adapter."},{"number":34,"points":26,"passage":"Une station mesure sa réussite au nombre de nuitées. Une association propose aussi d'examiner les ressources consommées et la qualité des emplois. Une hausse de fréquentation peut produire des bénéfices tout en accentuant des contraintes mal décrites par le seul volume des séjours.","question":"Quelle évaluation est proposée ?","options":["Un bilan des bénéfices et des contraintes","Un classement fondé uniquement sur les nuitées","Une suppression de toutes les données","Un refus de tout séjour extérieur"],"correct":"A","explanation":"Le passage indique : « Une station mesure sa réussite au nombre de nuitées. Une association propose aussi d'examiner les ressources consommées et la qualité des emplois. Une hausse de fréquentation peut produire des bénéfices tout en accentuant des contraintes mal décrites par le seul volume des séjours. » Cela justifie la réponse : Un bilan des bénéfices et des contraintes."},{"number":35,"points":26,"passage":"La découverte d'un espace naturel peut sensibiliser à sa protection. Elle peut aussi l'abîmer si les conditions de visite sont mal organisées. Le lien entre fréquentation et préservation n'est donc ni automatique ni nécessairement impossible : il dépend des usages et de leur encadrement.","question":"Quelle position résume le texte ?","options":["Toute découverte détruit nécessairement le milieu","Aucune règle ne peut influencer les usages","Toute fréquentation protège forcément le site","La visite peut soutenir la protection sous certaines conditions"],"correct":"D","explanation":"Le passage indique : « La découverte d'un espace naturel peut sensibiliser à sa protection. Elle peut aussi l'abîmer si les conditions de visite sont mal organisées. Le lien entre fréquentation et préservation n'est donc ni automatique ni nécessairement impossible : il dépend des usages et de leur encadrement. » Cela justifie la réponse : La visite peut soutenir la protection sous certaines conditions."},{"number":36,"points":33,"passage":"Un sentier réputé facile attire de nombreux débutants. La description indique une faible distance, mais ne mentionne pas un passage très exposé. Des guides demandent de compléter l'information. Une difficulté globale ne se déduit pas d'un seul chiffre lorsque certaines portions exigent des capacités particulières.","question":"Quelle limite de l'annonce est soulignée ?","options":["Un débutant doit connaître tous les chemins","La distance ne suffit pas à apprécier la difficulté","Un trajet court est toujours sans risque","Le nombre de visiteurs remplace toute description"],"correct":"B","explanation":"Le passage indique : « Une difficulté globale ne se déduit pas d'un seul chiffre lorsque certaines portions exigent des capacités particulières. » Cela justifie la réponse : La distance ne suffit pas à apprécier la difficulté."},{"number":37,"points":33,"passage":"La restauration d'une dune peut sembler désordonnée : clôtures légères, plantes irrégulières, zones fermées. Certains visiteurs préfèrent un rivage entièrement dégagé. Les gestionnaires expliquent les fonctions du dispositif. Ce qui paraît moins soigné selon des critères décoratifs peut mieux répondre aux besoins du milieu.","question":"Quelle distinction est proposée ?","options":["Apparence ordonnée et fonctionnement écologique","Dune naturelle et lieu sans aucune évolution","Plantes et décoration nécessairement identiques","Accès gratuit et absence de végétation"],"correct":"A","explanation":"Le passage indique : « Ce qui paraît moins soigné selon des critères décoratifs peut mieux répondre aux besoins du milieu. » Cela justifie la réponse : Apparence ordonnée et fonctionnement écologique."},{"number":38,"points":33,"passage":"Une destination valorise des images de solitude et de nature intacte. Le succès de ces images attire pourtant une fréquentation importante vers quelques lieux précis. La promesse qui motive la visite peut être fragilisée par l'ampleur même du public qu'elle attire.","question":"Quel paradoxe apparaît ?","options":["Les lieux très connus restent toujours déserts","La publicité n'influence aucun trajet","L'absence d'images garantit des visiteurs nombreux","La popularité menace parfois l'expérience annoncée"],"correct":"D","explanation":"Le passage indique : « La promesse qui motive la visite peut être fragilisée par l'ampleur même du public qu'elle attire. » Cela justifie la réponse : La popularité menace parfois l'expérience annoncée."},{"number":39,"points":33,"passage":"Un village de montagne veut conserver ses activités toute l'année. Il développe des offres nouvelles, mais vérifie aussi le logement des salariés et l'accès aux services. Diversifier les loisirs ne suffit pas si les personnes qui font fonctionner le territoire ne peuvent pas y vivre dans des conditions stables.","question":"Quelle condition complète la diversification touristique ?","options":["La multiplication des affiches uniquement","La fermeture des services ordinaires","La priorité absolue aux résidences vides","Le maintien de conditions de vie pour les travailleurs"],"correct":"D","explanation":"Le passage indique : « Diversifier les loisirs ne suffit pas si les personnes qui font fonctionner le territoire ne peuvent pas y vivre dans des conditions stables. » Cela justifie la réponse : Le maintien de conditions de vie pour les travailleurs."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-19','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-19","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 19","topic":"Énergie, techniques et habitat durable","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période.","question":"Quel équipement sera indisponible ?","options":["L'ascenseur","La cour extérieure","Le portail piéton manuel","La boîte aux lettres"],"correct":"A","explanation":"Le passage indique : « L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période. » Cela justifie la réponse : L'ascenseur."},{"number":2,"points":3,"passage":"Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires.","question":"Quel document est utile ?","options":["Une facture récente","Une carte de fidélité","Un devis de déménagement","Un relevé de tous les comptes"],"correct":"A","explanation":"Le passage indique : « Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires. » Cela justifie la réponse : Une facture récente."},{"number":3,"points":3,"passage":"Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention.","question":"Quelle consigne est donnée ?","options":["Laisser les robinets dans l'état demandé","Démonter les radiateurs","Couper tous les tuyaux","Ouvrir toutes les fenêtres obligatoirement"],"correct":"A","explanation":"Le passage indique : « Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention. » Cela justifie la réponse : Laisser les robinets dans l'état demandé."},{"number":4,"points":3,"passage":"Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système.","question":"Quelle est leur fonction ?","options":["Une alimentation électrique personnelle","Un support pédagogique","Une vente automatique de batteries","Un chauffage de la rue"],"correct":"B","explanation":"Le passage indique : « Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système. » Cela justifie la réponse : Un support pédagogique."},{"number":5,"points":9,"passage":"Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire.","question":"Pourquoi commencer par l'isolation ?","options":["Éviter toute analyse du logement","Évaluer les besoins avant de choisir l'équipement","Supprimer les factures existantes","Acheter l'appareil le plus puissant"],"correct":"B","explanation":"Le passage indique : « Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire. » Cela justifie la réponse : Évaluer les besoins avant de choisir l'équipement."},{"number":6,"points":9,"passage":"L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée.","question":"Quelle information faut-il relever en plus ?","options":["Le nombre de pièces du magasin","Le temps d'usage","La couleur de la prise","La marque du carnet"],"correct":"B","explanation":"Le passage indique : « L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée. » Cela justifie la réponse : Le temps d'usage."},{"number":7,"points":9,"passage":"Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels.","question":"Quel résultat est proposé ?","options":["Une certification de tous les appareils","Une obligation d'acheter auprès du conseiller","Une orientation pour préparer les décisions","Un chantier immédiatement terminé"],"correct":"C","explanation":"Le passage indique : « Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels. » Cela justifie la réponse : Une orientation pour préparer les décisions."},{"number":8,"points":9,"passage":"Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées.","question":"Quelle modification est prévue ?","options":["Éteindre le magasin pendant ses heures d'ouverture","Supprimer l'enseigne","Réduire l'éclairage nocturne","Ajouter des lampes à l'intérieur"],"correct":"C","explanation":"Le passage indique : « Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées. » Cela justifie la réponse : Réduire l'éclairage nocturne."},{"number":9,"points":9,"passage":"Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer.","question":"Quelle information manque pour décider ?","options":["Le nombre de réunions passées","La couleur des affiches","La date de fondation du fabricant uniquement","Le suivi de l'équipement"],"correct":"D","explanation":"Le passage indique : « Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer. » Cela justifie la réponse : Le suivi de l'équipement."},{"number":10,"points":9,"passage":"La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi.","question":"Quel objectif motive cette consigne ?","options":["Réduire l'entrée de chaleur","Empêcher toute aération nocturne","Refroidir le trottoir","Augmenter l'éclairage artificiel"],"correct":"A","explanation":"Le passage indique : « La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi. » Cela justifie la réponse : Réduire l'entrée de chaleur."},{"number":11,"points":15,"passage":"Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes.","question":"Pourquoi ajouter cette donnée ?","options":["Choisir la couleur des façades","Supprimer la mesure de consommation","Éviter d'attribuer tout changement aux travaux","Garantir des hivers identiques"],"correct":"C","explanation":"Le passage indique : « Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes. » Cela justifie la réponse : Éviter d'attribuer tout changement aux travaux."},{"number":12,"points":15,"passage":"Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité.","question":"Quel facteur complète la superficie ?","options":["Le nom de la rue","Le nombre de voisins","La couleur des factures","L'exposition du toit"],"correct":"D","explanation":"Le passage indique : « Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité. » Cela justifie la réponse : L'exposition du toit."},{"number":13,"points":15,"passage":"Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut.","question":"Quelle aide est nécessaire ?","options":["Déclarer tous les murs défectueux","Choisir uniquement la couleur la plus vive","Remplacer l'examen par une impression","Comprendre le sens des observations"],"correct":"D","explanation":"Le passage indique : « Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut. » Cela justifie la réponse : Comprendre le sens des observations."},{"number":14,"points":15,"passage":"Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre.","question":"Quelle priorité est donnée ?","options":["Augmenter la consommation immédiatement","Remplacer toutes les vitres par des écrans","Fermer l'école chaque été","Réduire le besoin avant d'ajouter un appareil"],"correct":"D","explanation":"Le passage indique : « Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre. » Cela justifie la réponse : Réduire le besoin avant d'ajouter un appareil."},{"number":15,"points":15,"passage":"Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles.","question":"Pourquoi publier cette liste ?","options":["Garantir la réparation de tout appareil","Informer sur les réparations réellement possibles","Vendre des pièces incompatibles","Refuser toute prise de contact"],"correct":"B","explanation":"Le passage indique : « Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles. » Cela justifie la réponse : Informer sur les réparations réellement possibles."},{"number":16,"points":15,"passage":"Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan.","question":"Quelle information complète le total ?","options":["Le nombre de décorations","L'évolution de l'occupation","La taille des boîtes aux lettres","Le prix des plantes"],"correct":"B","explanation":"Le passage indique : « Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan. » Cela justifie la réponse : L'évolution de l'occupation."},{"number":17,"points":15,"passage":"Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé.","question":"Quelle précaution accompagne la rénovation ?","options":["Supprimer toute entrée d'air","Maintenir une ventilation adaptée","Ouvrir tous les murs","Éviter de lire les consignes"],"correct":"B","explanation":"Le passage indique : « Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé. » Cela justifie la réponse : Maintenir une ventilation adaptée."},{"number":18,"points":15,"passage":"Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport.","question":"Quel avantage présente l'emplacement ?","options":["Un chauffage uniquement décoratif","Une indépendance totale de tous les équipements","Un trajet de chaleur plus court","Une production sans installation"],"correct":"C","explanation":"Le passage indique : « Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport. » Cela justifie la réponse : Un trajet de chaleur plus court."},{"number":19,"points":15,"passage":"Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée.","question":"Quelle démarche est adoptée ?","options":["Adapter le choix à l'usage","Choisir selon le prix de l'emballage","Ignorer la durée d'éclairage","Installer partout la même puissance sans étude"],"correct":"A","explanation":"Le passage indique : « Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée. » Cela justifie la réponse : Adapter le choix à l'usage."},{"number":20,"points":21,"passage":"Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres.","question":"Quelle attention guide le calendrier ?","options":["Le choix du devis le plus court uniquement","La cohérence entre les étapes","La suppression de toute anticipation","L'ordre alphabétique des entreprises"],"correct":"B","explanation":"Le passage indique : « Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. » Cela justifie la réponse : La cohérence entre les étapes."},{"number":21,"points":21,"passage":"Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort.","question":"Quel équilibre est recherché ?","options":["Maintien constant de la température maximale","Réduction fixe sans exception","Suppression de toute occupation","Économie et adaptation aux usages réels"],"correct":"D","explanation":"Le passage indique : « Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. » Cela justifie la réponse : Économie et adaptation aux usages réels."},{"number":22,"points":21,"passage":"Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie.","question":"Quel critère élargit la comparaison ?","options":["Le nombre de pages du devis uniquement","Le nom du modèle seulement","Les dépenses futures","La taille de l'affiche"],"correct":"C","explanation":"Le passage indique : « Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. » Cela justifie la réponse : Les dépenses futures."},{"number":23,"points":21,"passage":"Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été.","question":"Quel intérêt offre sa mobilité ?","options":["Adapter la protection aux saisons","Éviter toute attention à l'orientation","Assombrir définitivement le logement","Remplacer toutes les fenêtres"],"correct":"A","explanation":"Le passage indique : « Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. » Cela justifie la réponse : Adapter la protection aux saisons."},{"number":24,"points":21,"passage":"Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages.","question":"Quel complément est prévu ?","options":["Un remplacement de tous les agents","Une absence de décision","Une capacité d'interprétation humaine","Un affichage sans explication"],"correct":"C","explanation":"Le passage indique : « Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. » Cela justifie la réponse : Une capacité d'interprétation humaine."},{"number":25,"points":21,"passage":"Un atelier montre comment détecter de petites fuites d'eau. Les participants apprennent aussi quand faire appel à un professionnel plutôt qu'intervenir eux-mêmes.","question":"Quel objectif accompagne l'autonomie ?","options":["Éviter tout recours à un spécialiste","Reconnaître les limites de l'intervention personnelle","Supprimer les contrôles","Réparer toutes les installations sans compétence"],"correct":"B","explanation":"Le passage indique : « Un atelier montre comment détecter de petites fuites d'eau. Les participants apprennent aussi quand faire appel à un professionnel plutôt qu'intervenir eux-mêmes. » Cela justifie la réponse : Reconnaître les limites de l'intervention personnelle."},{"number":26,"points":21,"passage":"Un collectif achète de l'électricité produite par plusieurs sources. Il demande des informations sur la méthode de comptage pour comprendre les engagements annoncés.","question":"Quelle démarche suit le collectif ?","options":["Confondre consommation et prix du matériel","Se fier uniquement au dessin du contrat","Ignorer toute origine de production","Vérifier ce que les garanties signifient réellement"],"correct":"D","explanation":"Le passage indique : « Un collectif achète de l'électricité produite par plusieurs sources. Il demande des informations sur la méthode de comptage pour comprendre les engagements annoncés. » Cela justifie la réponse : Vérifier ce que les garanties signifient réellement."},{"number":27,"points":21,"passage":"Une rénovation conserve les matériaux encore utilisables. L'équipe vérifie leur état et leur compatibilité avant de décider du réemploi.","question":"Quelle condition encadre ce choix ?","options":["L'absence de toute inspection","Une préférence fondée uniquement sur l'âge","L'acceptation automatique de tout matériau","Une évaluation technique préalable"],"correct":"D","explanation":"Le passage indique : « Une rénovation conserve les matériaux encore utilisables. L'équipe vérifie leur état et leur compatibilité avant de décider du réemploi. » Cela justifie la réponse : Une évaluation technique préalable."},{"number":28,"points":21,"passage":"Un immeuble installe un espace de séchage collectif ventilé. Certains habitants réduisent l'usage d'appareils électriques, mais le service doit rester assez accessible pour être utilisé régulièrement.","question":"Quel facteur compte au-delà de l'installation ?","options":["La facilité d'usage au quotidien","Le nombre de prospectus","La couleur des murs seulement","L'absence de règles d'accès"],"correct":"A","explanation":"Le passage indique : « Un immeuble installe un espace de séchage collectif ventilé. Certains habitants réduisent l'usage d'appareils électriques, mais le service doit rester assez accessible pour être utilisé régulièrement. » Cela justifie la réponse : La facilité d'usage au quotidien."},{"number":29,"points":21,"passage":"Une entreprise affiche ses économies d'énergie par unité produite. Le volume total de production ayant augmenté, elle publie aussi sa consommation globale.","question":"Pourquoi ajouter le chiffre global ?","options":["Prouver que les deux valeurs sont identiques","Éviter toute comparaison","Masquer toute évolution de production","Distinguer efficacité unitaire et consommation totale"],"correct":"D","explanation":"Le passage indique : « Une entreprise affiche ses économies d'énergie par unité produite. Le volume total de production ayant augmenté, elle publie aussi sa consommation globale. » Cela justifie la réponse : Distinguer efficacité unitaire et consommation totale."},{"number":30,"points":26,"passage":"Un équipement très performant sur le papier peut donner des résultats décevants s'il est mal réglé ou utilisé dans un lieu inadapté. Une évaluation sérieuse doit donc articuler les caractéristiques techniques, l'installation et les usages.","question":"Quelle approche est recommandée ?","options":["Regarder le système en situation réelle","Considérer le réglage comme inutile","Déduire tout résultat du prix d'achat","Comparer uniquement les brochures"],"correct":"A","explanation":"Le passage indique : « Un équipement très performant sur le papier peut donner des résultats décevants s'il est mal réglé ou utilisé dans un lieu inadapté. Une évaluation sérieuse doit donc articuler les caractéristiques techniques, l'installation et les usages. » Cela justifie la réponse : Regarder le système en situation réelle."},{"number":31,"points":26,"passage":"Des travaux réduisent les besoins de chauffage. Les occupants gagnent aussi en confort, parfois en chauffant un peu plus qu'avant. Ce bénéfice ne rend pas les travaux inutiles ; il invite à distinguer économie mesurée et amélioration des conditions de vie.","question":"Quelle nuance est apportée au bilan ?","options":["Les travaux ne changent jamais les besoins","Toute hausse du confort prouve un échec","La température intérieure reste forcément identique","Le confort peut absorber une partie du gain énergétique"],"correct":"D","explanation":"Le passage indique : « Des travaux réduisent les besoins de chauffage. Les occupants gagnent aussi en confort, parfois en chauffant un peu plus qu'avant. Ce bénéfice ne rend pas les travaux inutiles ; il invite à distinguer économie mesurée et amélioration des conditions de vie. » Cela justifie la réponse : Le confort peut absorber une partie du gain énergétique."},{"number":32,"points":26,"passage":"Une ville cherche à rafraîchir une place. Les arbres, l'ombre et les sols perméables demandent une conception commune. Additionner des éléments présentés comme vertueux ne garantit pas leur efficacité si leurs fonctions et leurs conditions d'entretien se contredisent.","question":"Quelle nécessité est soulignée ?","options":["Éviter de prévoir l'entretien","Compter seulement les équipements ajoutés","Concevoir un ensemble cohérent","Choisir chaque élément sans regarder les autres"],"correct":"C","explanation":"Le passage indique : « Une ville cherche à rafraîchir une place. Les arbres, l'ombre et les sols perméables demandent une conception commune. Additionner des éléments présentés comme vertueux ne garantit pas leur efficacité si leurs fonctions et leurs conditions d'entretien se contredisent. » Cela justifie la réponse : Concevoir un ensemble cohérent."},{"number":33,"points":26,"passage":"Le partage d'un équipement réduit parfois les achats individuels. Mais si sa réservation est compliquée, les utilisateurs finissent par acheter leur propre appareil. L'économie de matière dépend donc aussi d'une organisation suffisamment simple pour durer.","question":"Quel facteur conditionne le bénéfice du partage ?","options":["La suppression des utilisateurs réguliers","Le nombre de slogans","La qualité de son organisation","La taille du logo"],"correct":"C","explanation":"Le passage indique : « Le partage d'un équipement réduit parfois les achats individuels. Mais si sa réservation est compliquée, les utilisateurs finissent par acheter leur propre appareil. L'économie de matière dépend donc aussi d'une organisation suffisamment simple pour durer. » Cela justifie la réponse : La qualité de son organisation."},{"number":34,"points":26,"passage":"Une aide publique couvre une part du coût des rénovations. Les ménages doivent néanmoins avancer le reste, parfois inaccessible à leur budget. Un taux d'aide identique ne produit donc pas la même possibilité d'agir pour tous.","question":"Quelle limite de l'égalité du taux est décrite ?","options":["Une aide proportionnelle supprime toute dépense","Les capacités de financement restantes sont inégales","Tous les ménages disposent du même budget","Le coût des travaux disparaît"],"correct":"B","explanation":"Le passage indique : « Une aide publique couvre une part du coût des rénovations. Les ménages doivent néanmoins avancer le reste, parfois inaccessible à leur budget. Un taux d'aide identique ne produit donc pas la même possibilité d'agir pour tous. » Cela justifie la réponse : Les capacités de financement restantes sont inégales."},{"number":35,"points":26,"passage":"Une démonstration compare deux fenêtres sous des conditions contrôlées. Elle aide à comprendre leurs performances respectives, mais ne permet pas d'annoncer directement l'économie exacte de chaque logement. Celle-ci dépend aussi des murs, des usages et du climat.","question":"Quelle portée faut-il donner à la démonstration ?","options":["Une comparaison utile mais limitée","Un diagnostic complet de chaque maison","Une facture future garantie pour tous","Une absence totale d'information"],"correct":"A","explanation":"Le passage indique : « Une démonstration compare deux fenêtres sous des conditions contrôlées. Elle aide à comprendre leurs performances respectives, mais ne permet pas d'annoncer directement l'économie exacte de chaque logement. Celle-ci dépend aussi des murs, des usages et du climat. » Cela justifie la réponse : Une comparaison utile mais limitée."},{"number":36,"points":33,"passage":"Une campagne encourage à remplacer les appareils anciens par des modèles efficaces. Pour un équipement encore peu utilisé, l'énergie et les matériaux nécessaires à la fabrication du nouveau peuvent peser dans le bilan. La décision doit donc considérer le cycle de vie et l'usage, plutôt qu'une comparaison limitée au fonctionnement instantané.","question":"Quelle comparaison est proposée ?","options":["Un bilan élargi incluant fabrication et usage","Le prix de la publicité","L'âge comme unique critère","La seule puissance affichée"],"correct":"A","explanation":"Le passage indique : « La décision doit donc considérer le cycle de vie et l'usage, plutôt qu'une comparaison limitée au fonctionnement instantané. » Cela justifie la réponse : Un bilan élargi incluant fabrication et usage."},{"number":37,"points":33,"passage":"Un immeuble rénové reçoit un système de commande complexe. Les occupants évitent certains réglages par peur de faire une erreur. L'équipe simplifie l'interface et organise un accompagnement. Une performance théorique ne devient réelle que si les personnes peuvent effectivement piloter les usages attendus.","question":"Quelle condition est mise en évidence ?","options":["L'absence de toute commande","Une complexité toujours plus grande","La suppression des explications","La compréhension pratique du système"],"correct":"D","explanation":"Le passage indique : « Une performance théorique ne devient réelle que si les personnes peuvent effectivement piloter les usages attendus. » Cela justifie la réponse : La compréhension pratique du système."},{"number":38,"points":33,"passage":"Une ville annonce une baisse de consommation dans ses bâtiments. Plusieurs équipements ont pourtant été fermés pendant la période observée. Les responsables recalculent les résultats à usage comparable. Un chiffre peut être exact tout en donnant une interprétation trompeuse s'il ne précise pas ce qui a changé autour de la mesure.","question":"Pourquoi corriger la comparaison ?","options":["Ignorer les fermetures","Distinguer économies et réduction d'activité","Effacer une baisse réelle dans tous les cas","Rendre les chiffres identiques par principe"],"correct":"B","explanation":"Le passage indique : « Un chiffre peut être exact tout en donnant une interprétation trompeuse s'il ne précise pas ce qui a changé autour de la mesure. » Cela justifie la réponse : Distinguer économies et réduction d'activité."},{"number":39,"points":33,"passage":"Un projet collectif veut produire de l'énergie près des habitants. Il organise aussi les décisions sur l'investissement et la répartition des bénéfices. Les initiateurs refusent de définir le caractère citoyen du projet par sa seule localisation. La proximité physique ne remplace pas une participation réelle aux choix qui structurent le service.","question":"Quel critère complète la localisation ?","options":["L'absence de tout contrat","La longueur du nom du projet","La gouvernance et la participation aux décisions","La couleur des installations"],"correct":"C","explanation":"Le passage indique : « La proximité physique ne remplace pas une participation réelle aux choix qui structurent le service. » Cela justifie la réponse : La gouvernance et la participation aux décisions."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-20','tcf-reading-2026-11-original-v2',$paper${"id":"tcf-reading-20","version":"tcf-reading-2026-11-original-v2","title":"TCF Reading · Test 20","topic":"Temps libre, organisation et transformations du quotidien","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures.","question":"Quelle limite est annoncée ?","options":["Le début des nouvelles parties après seize heures","L'arrivée de tous les visiteurs après quatorze heures","La présence des animateurs","La possibilité de jouer avant seize heures"],"correct":"A","explanation":"Le passage indique : « L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures. » Cela justifie la réponse : Le début des nouvelles parties après seize heures."},{"number":2,"points":3,"passage":"Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible.","question":"Quel espace est fermé ?","options":["La zone balisée du chantier","Tout le parc","Le jardin voisin","Toutes les allées"],"correct":"A","explanation":"Le passage indique : « Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible. » Cela justifie la réponse : La zone balisée du chantier."},{"number":3,"points":3,"passage":"Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante.","question":"Quelle démarche est urgente ?","options":["Acheter le matériel","S'inscrire","Venir chercher son certificat","Payer immédiatement"],"correct":"B","explanation":"Le passage indique : « Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante. » Cela justifie la réponse : S'inscrire."},{"number":4,"points":3,"passage":"Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures.","question":"Qu'est-ce qui change ?","options":["Le lieu de rassemblement","La durée de la promenade","Le jour choisi","L'heure du départ"],"correct":"A","explanation":"Le passage indique : « Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures. » Cela justifie la réponse : Le lieu de rassemblement."},{"number":5,"points":9,"passage":"Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires.","question":"Quelle intention est exprimée ?","options":["Prolonger le trajet","Préserver un temps de récupération","Ajouter une visite obligatoire","Organiser une compétition"],"correct":"B","explanation":"Le passage indique : « Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires. » Cela justifie la réponse : Préserver un temps de récupération."},{"number":6,"points":9,"passage":"Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple.","question":"Qui est accueilli ?","options":["Une personne ayant déjà terminé","Seulement un vendeur d'outils","Uniquement un professionnel","Une personne avec un projet modeste"],"correct":"D","explanation":"Le passage indique : « Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple. » Cela justifie la réponse : Une personne avec un projet modeste."},{"number":7,"points":9,"passage":"Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons.","question":"Quel intérêt présente la rencontre ?","options":["Éviter tout échange","Choisir uniquement selon le poids","Vendre tous les ouvrages","Découvrir les livres par la discussion"],"correct":"D","explanation":"Le passage indique : « Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons. » Cela justifie la réponse : Découvrir les livres par la discussion."},{"number":8,"points":9,"passage":"Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait.","question":"À quel besoin répond cette formule ?","options":["Une présence quotidienne obligatoire","Une fréquentation occasionnelle","Une activité réservée aux abonnés","Un accès sans horaire"],"correct":"B","explanation":"Le passage indique : « Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait. » Cela justifie la réponse : Une fréquentation occasionnelle."},{"number":9,"points":9,"passage":"Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage.","question":"Pourquoi le rendez-vous est-il reporté ?","options":["Parce que la salle a été vendue","Pour permettre davantage de participation","Parce que le rangement est terminé","Pour supprimer toute consultation"],"correct":"B","explanation":"Le passage indique : « Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage. » Cela justifie la réponse : Pour permettre davantage de participation."},{"number":10,"points":9,"passage":"Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos.","question":"Quel choix est défendu ?","options":["Laisser du temps sans objectif productif","Transformer chaque pause en tâche","Renoncer à tout repos","Organiser toutes les journées de la même façon"],"correct":"A","explanation":"Le passage indique : « Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos. » Cela justifie la réponse : Laisser du temps sans objectif productif."},{"number":11,"points":15,"passage":"Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration.","question":"Quelle étape est prioritaire ?","options":["Définir la fonction du meuble","Acheter un meuble neuf","Vendre immédiatement les outils","Choisir une couleur au hasard"],"correct":"A","explanation":"Le passage indique : « Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration. » Cela justifie la réponse : Définir la fonction du meuble."},{"number":12,"points":15,"passage":"Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin.","question":"Quelle solution évite d'avoir son propre matériel ?","options":["Venir uniquement regarder","S'inscrire dans une autre ville","Emprunter les pièces","Acheter une table"],"correct":"C","explanation":"Le passage indique : « Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin. » Cela justifie la réponse : Emprunter les pièces."},{"number":13,"points":15,"passage":"Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent.","question":"Quel regard est encouragé ?","options":["Le déplacement le plus rapide","L'attention au quotidien proche","La recherche exclusive de records","L'évitement de toute observation"],"correct":"B","explanation":"Le passage indique : « Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent. » Cela justifie la réponse : L'attention au quotidien proche."},{"number":14,"points":15,"passage":"Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve.","question":"Quel équilibre est recherché ?","options":["Supprimer les livres de loisir","Accueillir différents usages du lieu","Réserver tout le bâtiment aux candidats","Fermer pendant les examens"],"correct":"B","explanation":"Le passage indique : « Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve. » Cela justifie la réponse : Accueillir différents usages du lieu."},{"number":15,"points":15,"passage":"Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité.","question":"Quelle limite encadre la proposition ?","options":["Une réalisation automatique de chaque idée","Sa faisabilité dans le cadre du centre","L'absence de toute discussion","Le choix exclusif des adultes sans consultation"],"correct":"B","explanation":"Le passage indique : « Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité. » Cela justifie la réponse : Sa faisabilité dans le cadre du centre."},{"number":16,"points":15,"passage":"Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel.","question":"Pourquoi regarder aussi ces tâches ?","options":["Éviter toute évaluation","Augmenter artificiellement le nombre de réunions","Mesurer uniquement la taille des salles","Vérifier si le travail a simplement été déplacé"],"correct":"D","explanation":"Le passage indique : « Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel. » Cela justifie la réponse : Vérifier si le travail a simplement été déplacé."},{"number":17,"points":15,"passage":"Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles.","question":"Pourquoi conserver cette trace ?","options":["Encourager à venir malgré l'annulation","Remplacer les dates par des photos","Informer ceux qui avaient vu la première annonce","Masquer les changements"],"correct":"C","explanation":"Le passage indique : « Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles. » Cela justifie la réponse : Informer ceux qui avaient vu la première annonce."},{"number":18,"points":15,"passage":"Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention.","question":"Quelle compétence est également transmise ?","options":["Remplacer systématiquement chaque vêtement","Réparer tout objet sans exception","Éviter d'observer la matière","Reconnaître les limites d'une réparation"],"correct":"D","explanation":"Le passage indique : « Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention. » Cela justifie la réponse : Reconnaître les limites d'une réparation."},{"number":19,"points":15,"passage":"Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres.","question":"Quel objectif organise le jeu ?","options":["Supprimer toute règle","Désigner un perdant obligatoire","Récompenser uniquement le plus rapide","Réussir ensemble"],"correct":"D","explanation":"Le passage indique : « Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres. » Cela justifie la réponse : Réussir ensemble."},{"number":20,"points":21,"passage":"Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte.","question":"Quelle distinction est faite ?","options":["Tout temps d'attente est totalement libre","Tous les loisirs demandent le même temps","Les responsabilités disparaissent hors du bureau","L'absence de travail visible ne signifie pas une liberté complète"],"correct":"D","explanation":"Le passage indique : « Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. » Cela justifie la réponse : L'absence de travail visible ne signifie pas une liberté complète."},{"number":21,"points":21,"passage":"Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu.","question":"Quel aspect peut être évalué avant l'inscription ?","options":["La valeur de tous les équipements","Le programme de l'année suivante seulement","Le résultat garanti du trimestre","La manière de vivre l'activité dans le groupe"],"correct":"D","explanation":"Le passage indique : « Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. » Cela justifie la réponse : La manière de vivre l'activité dans le groupe."},{"number":22,"points":21,"passage":"Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable.","question":"Pourquoi choisir du matériel démontable ?","options":["Remplacer la rue chaque semaine","Garantir un projet définitif sans essai","Permettre une expérimentation réversible","Interdire toute participation"],"correct":"C","explanation":"Le passage indique : « Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. » Cela justifie la réponse : Permettre une expérimentation réversible."},{"number":23,"points":21,"passage":"Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne.","question":"Quel changement est recherché ?","options":["Mieux distinguer accès à l'information et interruption","Imposer une réaction immédiate à chacun","Rendre les informations confidentielles","Supprimer tous les messages"],"correct":"A","explanation":"Le passage indique : « Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. » Cela justifie la réponse : Mieux distinguer accès à l'information et interruption."},{"number":24,"points":21,"passage":"Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier.","question":"Quel besoin est reconnu ?","options":["La suppression des rencontres libres","Un accueil sans programme imposé","Une obligation permanente d'apprendre","Un accès réservé aux animateurs"],"correct":"B","explanation":"Le passage indique : « Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. » Cela justifie la réponse : Un accueil sans programme imposé."},{"number":25,"points":21,"passage":"Des bénévoles gèrent une collection de jeux. Ils notent les pièces manquantes avant le prêt, afin de distinguer un état ancien d'une perte récente.","question":"À quoi sert ce suivi ?","options":["Supprimer les contrôles au retour","Garantir que rien ne sera jamais perdu","Éviter des responsabilités attribuées à tort","Fixer le nombre de joueurs"],"correct":"C","explanation":"Le passage indique : « Des bénévoles gèrent une collection de jeux. Ils notent les pièces manquantes avant le prêt, afin de distinguer un état ancien d'une perte récente. » Cela justifie la réponse : Éviter des responsabilités attribuées à tort."},{"number":26,"points":21,"passage":"Un magasin organise des ateliers de réparation gratuits. Il précise quels produits sont concernés et ne conditionne pas l'accès à un nouvel achat.","question":"Quelle règle évite une confusion commerciale ?","options":["Chaque participant doit s'abonner","Tous les produits seront remplacés gratuitement","L'atelier n'impose pas d'achat","La gratuité dépend d'une commande"],"correct":"C","explanation":"Le passage indique : « Un magasin organise des ateliers de réparation gratuits. Il précise quels produits sont concernés et ne conditionne pas l'accès à un nouvel achat. » Cela justifie la réponse : L'atelier n'impose pas d'achat."},{"number":27,"points":21,"passage":"Une commune consulte les usagers d'un parc en semaine et le week-end. Les profils présents diffèrent selon les horaires.","question":"Pourquoi varier les moments d'enquête ?","options":["Éviter les habitués du lieu","Obtenir des réponses identiques","Supprimer toute comparaison","Entendre des usages qui ne sont pas tous simultanés"],"correct":"D","explanation":"Le passage indique : « Une commune consulte les usagers d'un parc en semaine et le week-end. Les profils présents diffèrent selon les horaires. » Cela justifie la réponse : Entendre des usages qui ne sont pas tous simultanés."},{"number":28,"points":21,"passage":"Un club propose des sorties courtes proches des transports. Les nouveaux participants peuvent rejoindre facilement l'activité sans posséder de voiture.","question":"Quel obstacle est pris en compte ?","options":["Le prix des photographies","L'âge des arbres","La mobilité nécessaire pour participer","Le manque de matériel professionnel uniquement"],"correct":"C","explanation":"Le passage indique : « Un club propose des sorties courtes proches des transports. Les nouveaux participants peuvent rejoindre facilement l'activité sans posséder de voiture. » Cela justifie la réponse : La mobilité nécessaire pour participer."},{"number":29,"points":21,"passage":"Une bibliothèque d'objets prépare des fiches simples. Un prêt devient plus utile lorsque les personnes savent installer, utiliser et rapporter correctement l'équipement.","question":"Quelle condition complète la mise à disposition ?","options":["Un accompagnement compréhensible de l'usage","Une absence de toute explication","Un matériel réservé aux experts","Une multiplication des règles cachées"],"correct":"A","explanation":"Le passage indique : « Une bibliothèque d'objets prépare des fiches simples. Un prêt devient plus utile lorsque les personnes savent installer, utiliser et rapporter correctement l'équipement. » Cela justifie la réponse : Un accompagnement compréhensible de l'usage."},{"number":30,"points":26,"passage":"Les loisirs sont parfois décrits comme un choix purement personnel. Les horaires, l'offre locale, le coût et les responsabilités familiales orientent pourtant les possibilités. Étudier les goûts sans regarder ces conditions risque de confondre préférence et adaptation à des contraintes.","question":"Quelle précaution d'analyse est proposée ?","options":["Supposer une liberté identique pour tous","Ignorer les coûts et les horaires","Déduire les goûts du seul âge","Relier les choix aux possibilités concrètes"],"correct":"D","explanation":"Le passage indique : « Les loisirs sont parfois décrits comme un choix purement personnel. Les horaires, l'offre locale, le coût et les responsabilités familiales orientent pourtant les possibilités. Étudier les goûts sans regarder ces conditions risque de confondre préférence et adaptation à des contraintes. » Cela justifie la réponse : Relier les choix aux possibilités concrètes."},{"number":31,"points":26,"passage":"Un service promet de faire gagner du temps. Il demande toutefois à l'utilisateur de saisir régulièrement des données et de corriger les erreurs. Le gain doit être évalué sur l'ensemble des tâches, pas seulement sur celle que le service accomplit automatiquement.","question":"Quelle comparaison est nécessaire ?","options":["Ignorer toutes les corrections","Regarder uniquement la vitesse annoncée","Compter aussi le travail demandé à l'utilisateur","Comparer seulement les logos"],"correct":"C","explanation":"Le passage indique : « Un service promet de faire gagner du temps. Il demande toutefois à l'utilisateur de saisir régulièrement des données et de corriger les erreurs. Le gain doit être évalué sur l'ensemble des tâches, pas seulement sur celle que le service accomplit automatiquement. » Cela justifie la réponse : Compter aussi le travail demandé à l'utilisateur."},{"number":32,"points":26,"passage":"Une place publique accueille des usages variés qui ne s'accordent pas spontanément : repos, jeux, passage et manifestations. Un aménagement réussi ne supprime pas forcément les différences ; il peut organiser leur coexistence par des espaces, des horaires et des règles discutées.","question":"Quelle approche de l'espace public est défendue ?","options":["Permettre plusieurs usages compatibles","Éviter toute règle commune","Choisir un seul public définitif","Rendre la place inaccessible"],"correct":"A","explanation":"Le passage indique : « Une place publique accueille des usages variés qui ne s'accordent pas spontanément : repos, jeux, passage et manifestations. Un aménagement réussi ne supprime pas forcément les différences ; il peut organiser leur coexistence par des espaces, des horaires et des règles discutées. » Cela justifie la réponse : Permettre plusieurs usages compatibles."},{"number":33,"points":26,"passage":"Un atelier valorise le fait de terminer un projet lentement. Les participants découvrent des gestes qu'une solution rapide aurait évités. La durée n'est pas automatiquement un défaut lorsqu'elle fait partie de ce que l'activité permet d'apprendre ou d'éprouver.","question":"Quelle valeur du temps est mise en avant ?","options":["Toute lenteur prouve une mauvaise méthode","L'activité doit toujours être raccourcie","Une durée peut contribuer à l'expérience","Apprendre exige d'éviter les gestes"],"correct":"C","explanation":"Le passage indique : « Un atelier valorise le fait de terminer un projet lentement. Les participants découvrent des gestes qu'une solution rapide aurait évités. La durée n'est pas automatiquement un défaut lorsqu'elle fait partie de ce que l'activité permet d'apprendre ou d'éprouver. » Cela justifie la réponse : Une durée peut contribuer à l'expérience."},{"number":34,"points":26,"passage":"Un agenda collectif rend visibles les activités d'un groupe, mais peut devenir envahissant si chaque créneau libre paraît disponible pour une nouvelle tâche. Les membres décident de protéger aussi des périodes sans rendez-vous.","question":"Quel risque veulent-ils éviter ?","options":["Remplacer le repos par des réunions","Transformer toute disponibilité apparente en obligation","Supprimer toutes les informations utiles","Rendre les tâches impossibles à prévoir"],"correct":"B","explanation":"Le passage indique : « Un agenda collectif rend visibles les activités d'un groupe, mais peut devenir envahissant si chaque créneau libre paraît disponible pour une nouvelle tâche. Les membres décident de protéger aussi des périodes sans rendez-vous. » Cela justifie la réponse : Transformer toute disponibilité apparente en obligation."},{"number":35,"points":26,"passage":"Une enquête mesure le nombre d'activités pratiquées. Des participants ayant peu d'activités déclarent pourtant y être très attachés. La richesse d'un loisir ne se confond pas toujours avec la diversité ou la fréquence mesurable des sorties.","question":"Quelle nuance est apportée ?","options":["Les loisirs rares sont nécessairement inutiles","La diversité garantit la satisfaction","L'importance vécue dépasse parfois le nombre d'activités","Tous les participants souhaitent multiplier les sorties"],"correct":"C","explanation":"Le passage indique : « Une enquête mesure le nombre d'activités pratiquées. Des participants ayant peu d'activités déclarent pourtant y être très attachés. La richesse d'un loisir ne se confond pas toujours avec la diversité ou la fréquence mesurable des sorties. » Cela justifie la réponse : L'importance vécue dépasse parfois le nombre d'activités."},{"number":36,"points":33,"passage":"La multiplication des activités proposées peut donner l'impression d'un choix toujours plus large. Mais si toutes exigent réservation anticipée et présence régulière, les personnes aux horaires imprévisibles restent exclues. La diversité des contenus ne garantit pas une diversité des conditions de participation.","question":"Quelle limite de l'offre est décrite ?","options":["Des règles d'accès semblables peuvent exclure malgré un programme varié","La variété des sujets supprime les contraintes horaires","Tous les participants disposent du même emploi du temps","Une inscription anticipée convient nécessairement à chacun"],"correct":"A","explanation":"Le passage indique : « La diversité des contenus ne garantit pas une diversité des conditions de participation. » Cela justifie la réponse : Des règles d'accès semblables peuvent exclure malgré un programme varié."},{"number":37,"points":33,"passage":"Un lieu de rencontre souhaite rester ouvert sans obligation d'achat. Pour durer, il doit néanmoins financer le local et l'accueil. Les organisateurs rendent ces coûts visibles et recherchent plusieurs soutiens. L'absence de paiement à l'entrée ne signifie pas l'absence de ressources nécessaires à l'existence du service.","question":"Quelle distinction est essentielle ?","options":["Local partagé et bâtiment sans entretien","Financement multiple et achat obligatoire","Gratuité pour l'usager et coût de fonctionnement","Accueil libre et absence de toute organisation"],"correct":"C","explanation":"Le passage indique : « L'absence de paiement à l'entrée ne signifie pas l'absence de ressources nécessaires à l'existence du service. » Cela justifie la réponse : Gratuité pour l'usager et coût de fonctionnement."},{"number":38,"points":33,"passage":"Une équipe mesure le temps gagné par un nouvel outil et souhaite remplir immédiatement les minutes libérées. Certains salariés proposent d'en conserver une partie pour traiter les imprévus. Un planning occupé en permanence devient fragile face à la moindre variation. Une marge non affectée peut contribuer au bon fonctionnement plutôt que représenter un temps perdu.","question":"Quelle utilité est attribuée aux marges ?","options":["Absorber les variations et les imprévus","Garantir que rien ne changera","Prouver une absence de travail","Supprimer la nécessité de s'organiser"],"correct":"A","explanation":"Le passage indique : « Une marge non affectée peut contribuer au bon fonctionnement plutôt que représenter un temps perdu. » Cela justifie la réponse : Absorber les variations et les imprévus."},{"number":39,"points":33,"passage":"Un quartier lance une initiative temporaire qui rencontre un grand succès. Les habitants veulent la prolonger, mais les bénévoles n'ont pas prévu un engagement permanent. Le projet doit être réorganisé et financé autrement. Le succès d'une expérience ne garantit pas que les conditions qui l'ont rendue possible puissent durer sans transformation.","question":"Quelle transition devient nécessaire ?","options":["Exiger la même disponibilité sans discussion","Passer d'un essai ponctuel à une organisation soutenable","Supprimer tout rôle aux participants","Considérer les ressources comme illimitées"],"correct":"B","explanation":"Le passage indique : « Le succès d'une expérience ne garantit pas que les conditions qui l'ont rendue possible puissent durer sans transformation. » Cela justifie la réponse : Passer d'un essai ponctuel à une organisation soutenable."}]}$paper$::jsonb);
create or replace function public.academy_tcf_reading_command(p_action text,p_id uuid default null,p_payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();a academy_tcf_reading.attempts;paper jsonb;history jsonb;question_no text;choice text;
begin
 perform academy_ai.require_access(u);
 if p_action is null or p_action not in ('catalog','start','read','answer','submit') or p_payload is null or jsonb_typeof(p_payload)<>'object' or octet_length(p_payload::text)>1000 then raise exception 'Invalid reading action';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where not (k=any(case p_action when 'start' then array['testId','version'] when 'answer' then array['number','choice','revision'] when 'submit' then array['revision'] else array[]::text[] end))) then raise exception 'Invalid reading request';end if;
 if p_action='catalog' then
  select coalesce(jsonb_agg(to_jsonb(h) order by h."startedAt" desc),'[]') into history from (
   select id,test_id "testId",version,status,started_at "startedAt",deadline from academy_tcf_reading.attempts where user_id=u order by started_at desc limit 50) h;
  return jsonb_build_object('tests',(select jsonb_agg(jsonb_build_object('id',id,'version',version,'title',content->>'title','topic',content->>'topic','questions',39,'seconds',3600,'maxPoints',699) order by id) from academy_tcf_reading.papers),'history',history,'serverNow',now());
 end if;
 if p_id is null then raise exception 'Invalid reading attempt';end if;
 -- Serialize starts per account, rather than a shared/global lock.
 if p_action='start' then perform 1 from auth.users where id=u for update;end if;
 select * into a from academy_tcf_reading.attempts where id=p_id for update;
 if found and a.user_id<>u then raise exception 'Reading attempt not found' using errcode='42501';end if;
 if p_action='start' then
  if not exists(select 1 from academy_tcf_reading.papers p where p.id=p_payload->>'testId' and p.version=p_payload->>'version') then raise exception 'Reading paper changed. Refresh before starting';end if;
  if a.id is not null and (a.test_id<>p_payload->>'testId' or a.version<>p_payload->>'version') then raise exception 'Reading attempt already used';end if;
  if a.id is null then
   -- Finish expired saved work, then resume any unexpired attempt of this paper.
   update academy_tcf_reading.attempts t set status='completed',submitted_at=t.deadline,
    result=academy_tcf_reading.grade(p.content,t.answers),revision=t.revision+1
    from academy_tcf_reading.papers p where t.user_id=u and t.status='active' and now()>=t.deadline and p.id=t.test_id and p.version=t.version;
   select * into a from academy_tcf_reading.attempts where user_id=u and status='active' and test_id=p_payload->>'testId' and version=p_payload->>'version' for update;
   if a.id is null then insert into academy_tcf_reading.attempts(id,user_id,test_id,version) values(p_id,u,p_payload->>'testId',p_payload->>'version') returning * into a;end if;
  end if;
 end if;
 if a.id is null then raise exception 'Reading attempt not found' using errcode='42501';end if;
 select content into paper from academy_tcf_reading.papers where id=a.test_id and version=a.version;
 if a.status='active' and now()>=a.deadline then
  update academy_tcf_reading.attempts set status='completed',submitted_at=deadline,result=academy_tcf_reading.grade(paper,answers),revision=revision+1 where id=a.id returning * into a;
 end if;
 if a.status='active' and p_action in ('answer','submit') then
  if p_payload->'revision' is distinct from to_jsonb(a.revision) then raise exception 'Reading answers changed in another tab. Reload saved answers';end if;
  if p_action='answer' then
   if jsonb_typeof(p_payload->'number') is distinct from 'number' or p_payload->>'number' !~ '^([1-9]|[12][0-9]|3[0-9])$' or not (p_payload ? 'choice') or (p_payload->'choice'<>'null'::jsonb and (jsonb_typeof(p_payload->'choice')<>'string' or p_payload->>'choice' not in ('A','B','C','D'))) then raise exception 'Invalid reading choice';end if;
   question_no:=p_payload->>'number';choice:=p_payload->>'choice';
   update academy_tcf_reading.attempts set answers=case when choice is null then answers-question_no else jsonb_set(answers,array[question_no],to_jsonb(choice)) end,revision=revision+1 where id=a.id returning * into a;
  else
   update academy_tcf_reading.attempts set status='completed',submitted_at=now(),result=academy_tcf_reading.grade(paper,answers),revision=revision+1 where id=a.id returning * into a;
  end if;
 end if;
 return jsonb_build_object('id',a.id,'testId',a.test_id,'version',a.version,'status',a.status,'answers',a.answers,'revision',a.revision,'startedAt',a.started_at,'deadline',a.deadline,'submittedAt',a.submitted_at,'serverNow',now(),
 'paper',jsonb_build_object('id',a.test_id,'version',a.version,'title',paper->>'title','seconds',paper->'seconds','questions',(select jsonb_agg(q-'correct'-'explanation' order by (q->>'number')::int) from jsonb_array_elements(paper->'questions') q)),
 'result',a.result);
end;$$;
revoke all on function public.academy_tcf_reading_command(text,uuid,jsonb) from public,anon,service_role;
grant execute on function public.academy_tcf_reading_command(text,uuid,jsonb) to authenticated;

create function academy_tcf_reading.freeze_identity() returns trigger language plpgsql set search_path='' as $$begin
 if new.user_id is distinct from old.user_id or new.test_id is distinct from old.test_id or new.version is distinct from old.version then raise exception 'Reading attempt identity is immutable';end if;return new;
end;$$;
revoke all on function academy_tcf_reading.freeze_identity() from public,anon,authenticated,service_role;
create trigger reading_identity_immutable before update on academy_tcf_reading.attempts for each row execute function academy_tcf_reading.freeze_identity();
create function academy_tcf_reading.freeze_paper() returns trigger language plpgsql set search_path='' as $$begin
 raise exception 'Reading papers are immutable; publish a new version';
end;$$;
revoke all on function academy_tcf_reading.freeze_paper() from public,anon,authenticated,service_role;
create trigger reading_papers_immutable before update or delete on academy_tcf_reading.papers for each row execute function academy_tcf_reading.freeze_paper();
notify pgrst,'reload schema';
commit;
